window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s21-190","number":190,"surah":21,"verses":[49],"references":[{"surah":21,"verses":[49]}],"verseLabel":"الأنبياء: 49","question":"ما الفرق بين خشية الرب بالغيب والإشفاق من الساعة؟","answer":"الخشية خوف يمتزج بالتعظيم وينشأ عن معرفة، فجاءت متعلقة بالرب الذي لم يروه أو في خلواتهم حيث لا يراهم الناس. أما الإشفاق فهو شدة الخوف، فناسب الساعة بما فيها من أهوال؛ وبذلك جمع الوصف بين تعظيم الله والخوف الشديد من لقائه وحسابه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 120–123، مبحث «يخشون ربهم بالغيب».","url":""}]},{"id":"s21-191","number":191,"surah":21,"verses":[50],"references":[{"surah":21,"verses":[50]}],"verseLabel":"الأنبياء: 50","question":"ما دلالة تقديم وصف القرآن بأنه ﴿مُبَارَكٌ﴾ على قوله: ﴿أَنْزَلْنَاهُ﴾؟","answer":"قدم البركة لإبرازها والعناية بها؛ فالقرآن كثير الخير دائم النفع قبل أن يذكر جهة إنزاله. ووصفه أولًا بأنه «ذكر» يصل الآية بما سبق من ذكر التوراة، ثم ميّزه بالبركة ليقوم الاستفهام بعده حجة: كيف يُنكر كتاب هذه صفته؟","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 123–125، مبحث «وهذا ذكر مبارك أنزلناه».","url":""}]},{"id":"s21-192","number":192,"surah":21,"verses":[51],"references":[{"surah":21,"verses":[51]}],"verseLabel":"الأنبياء: 51","question":"ما دلالة إضافة الرشد إلى إبراهيم في قوله: ﴿آتَيْنَا إِبْرَاهِيمَ رُشْدَهُ﴾؟","answer":"الإضافة تفيد الرشد الكامل اللائق بمقام إبراهيم وبأمثاله من كبار الرسل، لا قدرًا مطلقًا غير محدد. فكل ما يصح أن يكون رشدًا خاصًا به قد أوتيه، وجاء ذلك تمهيدًا لحجته الواضحة على قومه وشجاعته في مواجهة باطلهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 137–138، مبحث «ولقد آتينا إبراهيم رشده».","url":""}]},{"id":"s21-193","number":193,"surah":21,"verses":[57,58],"references":[{"surah":21,"verses":[57,58]}],"verseLabel":"الأنبياء: 57–58","question":"ما سر القسم بالتاء في قوله: ﴿وَتَاللَّهِ لَأَكِيدَنَّ أَصْنَامَكُمْ﴾؟","answer":"لتاء القسم إيحاء بالتعجب والتفخيم، فالمقسم عليه أمر عظيم في أعين قوم يعكفون على أصنامهم، ومع ذلك عزم إبراهيم عليه غير مبال بالعاقبة. وتتابع التوكيد في التاء واللام والنون الثقيلة يصور رسوخ عزمه وقوة المواجهة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 145–148، مبحث «وتالله لأكيدن أصنامكم».","url":""}]},{"id":"s21-194","number":194,"surah":21,"verses":[89,90],"references":[{"surah":21,"verses":[89,90]}],"verseLabel":"الأنبياء: 89–90","question":"ما سر مجيء دعاء زكريا موجزًا: ﴿رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنْتَ خَيْرُ الْوَارِثِينَ﴾؟","answer":"يناسب الإيجاز سياق السورة الذي يسوق نماذج متتابعة للأنبياء، بخلاف التفصيل في سورتي آل عمران ومريم. وجمع الدعاء بين طلب الولد والتفويض؛ فهو لا يريد بقاءه فردًا، لكنه يقر في ختام الطلب بأن الله خير من يبقى بعد فناء الخلق ووارثهم الحق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 205–207، مبحث «وزكريا إذ نادى ربه».","url":""}]},{"id":"s21-195","number":195,"surah":21,"verses":[93],"references":[{"surah":21,"verses":[93]}],"verseLabel":"الأنبياء: 93","question":"ما أثر الالتفات من الخطاب إلى الغيبة في قوله: ﴿وَتَقَطَّعُوا أَمْرَهُمْ بَيْنَهُمْ﴾؟","answer":"الأصل بحسب ما قبله أن يقال «وتقطعتم»، لكن الكلام صرف عنهم إلى الغيبة كأن فعلهم من القبح يُحكى لغيرهم ويُنعى عليهم. وصوّر الدين شيئًا قطعوه ووزعوه بينهم، فتحول الأمر الواحد إلى فرق وأحزاب، ثم جمعهم الوعيد: ﴿كُلٌّ إِلَيْنَا رَاجِعُونَ﴾.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 217–218، مبحث «وتقطعوا أمرهم بينهم».","url":""}]},{"id":"s21-196","number":196,"surah":21,"verses":[95],"references":[{"surah":21,"verses":[95]}],"verseLabel":"الأنبياء: 95","question":"كيف أفاد قوله: ﴿وَحَرَامٌ عَلَى قَرْيَةٍ… أَنَّهُمْ لَا يَرْجِعُونَ﴾ حتمية الرجوع؟","answer":"المعنى أن عدم رجوعهم ممتنع ومحال؛ فإذا حُرّم عدم الرجوع ثبت أن الرجوع واجب واقع. وجاء التركيب بعد ﴿كُلٌّ إِلَيْنَا رَاجِعُونَ﴾ وكتابة السعي، فربط الوعد والوعيد بحتمية البعث والجزاء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 224–228، مبحث «وحرام على قرية أهلكناها».","url":""}]},{"id":"s21-197","number":197,"surah":21,"verses":[96],"references":[{"surah":21,"verses":[96]}],"verseLabel":"الأنبياء: 96","question":"ما سر تأنيث ﴿فُتِحَتْ﴾ مع يأجوج ومأجوج، ولماذا جيء بـ﴿إِذَا﴾ لا «إن»؟","answer":"في الكلام مضاف محذوف؛ أي فُتح سد يأجوج ومأجوج أو جهتهم، ولما حذف المضاف روعي معنى القبيلتين فجاء التأنيث. واختيرت «إذا» لأن الفتح متحقق الوقوع، بخلاف «إن» التي تلائم الأمر المحتمل.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 228–229، مبحث «حتى إذا فتحت يأجوج ومأجوج».","url":""}]},{"id":"s21-198","number":198,"surah":21,"verses":[100],"references":[{"surah":21,"verses":[100]}],"verseLabel":"الأنبياء: 100","question":"ما سر الاقتصار على الزفير هنا، وجمع الزفير والشهيق في سورة هود؟","answer":"الزفير إخراج النفس مع الغم والأنين، وهو الملائم لقوله هنا ﴿وَهُمْ فِيهَا لَا يَسْمَعُونَ﴾؛ فالمشهد يركز على الصوت الخارج منهم مع انقطاع السماع. أما موضع هود فبسط أحوال أهل النار وطول مكثهم، فجمع حركتي النفس: الزفير والشهيق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 238، مبحث «لهم فيها زفير».","url":""}]},{"id":"s21-199","number":199,"surah":21,"verses":[109],"references":[{"surah":21,"verses":[109]}],"verseLabel":"الأنبياء: 109","question":"ما دلالة قوله: ﴿آذَنْتُكُمْ عَلَى سَوَاءٍ﴾، ولم قيل: ﴿أَقَرِيبٌ أَمْ بَعِيدٌ﴾؟","answer":"﴿آذَنْتُكُمْ﴾ ليست مجرد إعلام، بل إعلام يتضمن التحذير والإنذار، و﴿عَلَى سَوَاءٍ﴾ تعني أنه بلّغهم جميعًا بلا استثناء ولا خفاء. أما مقابلة القريب بالبعيد فتنفي علم الرسول بموعد الوعيد مع تأكيد وقوعه؛ فخفاء الزمن لا يعني الشك في الحدث.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 257–259، مبحث «آذنتكم على سواء».","url":""}]},{"id":"s21-200","number":200,"surah":21,"verses":[110],"references":[{"surah":21,"verses":[110]}],"verseLabel":"الأنبياء: 110","question":"ما سر تقييد الجهر بالقول، وإسناد الكتمان إليهم دون الجهر؟","answer":"الجهر قد يكون بالبصر أو السمع، فقيّده بالقول لأن السياق سياق تبليغ وإنذار مسموع. ولم يقل «يعلم ما تجهرون» لأن الجهر لم يختص بالكافرين؛ فالرسول جهر بالبلاغ أيضًا، أما الكتمان فهو فعلهم الخاص، لذلك أسنده إليهم: ﴿مَا تَكْتُمُونَ﴾.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 259–261، مبحث «يعلم الجهر من القول».","url":""}]},{"id":"s22-1","number":1,"surah":22,"verses":[1],"references":[{"surah":22,"verses":[1]}],"verseLabel":"الحج: 1","question":"ما دلالة عموم النداء بـ﴿يَا أَيُّهَا النَّاسُ﴾ في مطلع سورة الحج؟","answer":"يتناول الخطاب المكلفين جميعًا، لا المؤمنين وحدهم؛ فالتنبيه إلى التقوى وأهوال الساعة موجه إلى الناس كافة. ويدخل من يأتي بعد زمن النزول في حكم الخطاب، كما يدخل الذكور والإناث، على ما بيّنه المبحث من التغليب وعموم الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص213، تحت عنوان «بيان المقصودين بالنداء في مطلع السورة»","url":""}]},{"id":"s22-2","number":2,"surah":22,"verses":[1],"references":[{"surah":22,"verses":[1]}],"verseLabel":"الحج: 1","question":"ما نكتة تنكير ﴿شَيْءٌ﴾ في وصف زلزلة الساعة؟","answer":"التنكير للتهويل؛ فالزلزلة شيء لا يحيط السامع بكنه شدته ولا يقاس بما ألفه من الحوادث.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص217، تحت عنوان «نكتة تنكير لفظ ﴿شَيْءٌ﴾»","url":""}]},{"id":"s22-108","number":108,"surah":22,"verses":[1],"references":[{"surah":22,"verses":[1]}],"verseLabel":"الحج: 1","question":"ما بلاغة وصف زلزلة الساعة بأنها ﴿عَظِيمٌ﴾؟","answer":"نقل الوصف معنى الضخامة الحسية إلى عظم الشأن والأثر، فزاد تهويل الحدث في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص217، تحت عنوان «بلاغة الاستعارة في وصف الشيء بـ﴿عَظِيمٌ﴾»","url":""}]},{"id":"s22-3","number":3,"surah":22,"verses":[2],"references":[{"surah":22,"verses":[2]}],"verseLabel":"الحج: 2","question":"ما سرّ العدول من ﴿تَرَوْنَهَا﴾ إلى ﴿وَتَرَى النَّاسَ سُكَارَى﴾؟","answer":"تعلقت الرؤية أولًا بالزلزلة، فجُعل الناس جميعًا رائين لها. ثم تعلقت بحال الناس، فجُعل كل واحد صالحًا لأن يكون رائيًا لسائرهم. وفي إفراد الخطاب إبراز لشدة ظهور تلك الحال حتى لا تكاد تخفى على أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص228، تحت عنوان «نكتة العدول من ﴿ترونها﴾ إلى ﴿وترى﴾»","url":""}]},{"id":"s22-4","number":4,"surah":22,"verses":[2],"references":[{"surah":22,"verses":[2]}],"verseLabel":"الحج: 2","question":"ما وجه البلاغة في التشبيه البليغ في حالة الرؤية القلبية في قوله تعالى: ﴿وَتَرَى النَّاسَ سُكَارَى وَمَا هُمْ بِسُكَارَى﴾؟","answer":"شبه اضطراب الناس وذهولهم بهيئة السكارى تشبيهًا بليغًا، ثم نفى السكر الحقيقي ليظهر أن الهول وحده أحدث هذه الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص229، تحت عنوان «بلاغة التشبيه البليغ في حالة الرؤية القلبية»","url":""}]},{"id":"s22-109","number":109,"surah":22,"verses":[2],"references":[{"surah":22,"verses":[2]}],"verseLabel":"الحج: 2","question":"ما دلالة الواو في قوله: ﴿وَلَكِنَّ عَذَابَ اللَّهِ شَدِيدٌ﴾؟","answer":"وصلت الجملة بما قبلها لتوضح سبب الهيئة المنفية عن الخمر: إنما أذهلهم وأفقدهم توازنهم شدة عذاب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص230، تحت عنوان «دلالة الواو في جملة توضيح سبب الحال»","url":""}]},{"id":"s22-5","number":5,"surah":22,"verses":[3],"references":[{"surah":22,"verses":[3]}],"verseLabel":"الحج: 3","question":"ما فائدة تقييد الجدال بقوله: ﴿بِغَيْرِ عِلْمٍ﴾؟","answer":"ذم القيد الجدال المجرد من الدليل، وأخرج المجادلة بالحق القائمة على العلم؛ فالمذموم خصومة الجهل لا مطلق الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص240، تحت عنوان «فائدة التقييد بقوله: ﴿بِغَيْرِ عِلْمٍ﴾»","url":""}]},{"id":"s22-110","number":110,"surah":22,"verses":[3],"references":[{"surah":22,"verses":[3]}],"verseLabel":"الحج: 3","question":"ما دلالة عطف قوله: ﴿وَيَتَّبِعُ كُلَّ شَيْطَانٍ مَرِيدٍ﴾؟","answer":"كشف العطف منشأ الجدال بغير علم: اتباع الشيطان والهوى والتقليد بدل البرهان، فجمع فساد القول وفساد مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص240، تحت عنوان «معنى الواو في جملة ﴿وَيَتَّبِعُ﴾»","url":""}]},{"id":"s22-6","number":6,"surah":22,"verses":[4],"references":[{"surah":22,"verses":[4]}],"verseLabel":"الحج: 4","question":"ما سرّ التعبير بالهداية في ﴿وَيَهْدِيهِ إِلَى عَذَابِ السَّعِيرِ﴾؟","answer":"استُعيرت الهداية للسوق إلى العذاب على سبيل التهكم؛ فالهداية المنتظرة توصل إلى الخير، أما اتباع الشيطان فينتهي إلى النار. وبذلك ينكشف بطلان ما يتوهمه تابعه من نفع تلك الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص246–247، تحت عنوان «بلاغة الاستعارة في الهداية إلى عذاب السعير»","url":""}]},{"id":"s22-7","number":7,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما دلالة تفصيل مراحل الخلق في سياق الاستدلال على البعث؟","answer":"تفصل ﴿ثم﴾ مراحل الخلق وتبرز التراخي والانتقال من حال إلى حال، فيتجلى تنوع القدرة الإلهية ويقوى الاستدلال بالإنشاء الأول على البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص258، تحت عنوان «نكتة التعبير بـ﴿ثُمَّ﴾ في مراحل الخلق»","url":""}]},{"id":"s22-8","number":8,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما سرّ تقديم ﴿مُخَلَّقَةٍ﴾ على ﴿غَيْرِ مُخَلَّقَةٍ﴾؟","answer":"قُدمت المخلقة لأنها أدخل في الاستدلال على القدرة، ثم ذُكرت غير المخلقة إكمالًا للدليل وتنبيهًا إلى أن التخليق نفسه إنشاء من عدم. فالحالتان تشهدان للقدرة، وإن اختلف موقعهما في قوة الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص258، تحت عنوان «غرض التقديم والتأخير في ﴿مخلقة وغير مخلقة﴾»","url":""}]},{"id":"s22-9","number":9,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما دلالة اللام في قوله: ﴿لِكَيْلَا يَعْلَمَ مِنْ بَعْدِ عِلْمٍ﴾؟","answer":"تفيد اللام الغاية والعاقبة، فتصور ما ينتهي إليه من يرد إلى أرذل العمر من انتكاس العلم والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص266، تحت عنوان «معنى اللام في قوله: ﴿لِكَيْلَا يَعْلَمَ﴾»","url":""}]},{"id":"s22-111","number":111,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما نكتة تنكير ﴿شَيْئًا﴾ في قوله: ﴿لِكَيْلَا يَعْلَمَ مِنْ بَعْدِ عِلْمٍ شَيْئًا﴾؟","answer":"وقع التنكير في سياق النفي فعمم فقد الإدراك مبالغة في تصوير الضعف؛ حتى ينسى ما علم ويعجز عما كان يقدر عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص268، تحت عنوان «نكتة تنكير لفظ ﴿شَيْئًا﴾ في السياق»","url":""}]},{"id":"s22-10","number":10,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما دلالة وصف الأرض بـ﴿هَامِدَةً﴾ في دليل البعث؟","answer":"يصور الهمود خلو الأرض من مظاهر الحياة، وما يبدو عليها من اليبس والجمود. ثم انتقالها بالماء إلى النمو والعطاء دليل محسوس على قدرة الله على إحياء الموتى؛ فالتحول من حال إلى حال هو موضع الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص272، تحت عنوان «الموقع الإعرابي لقوله: ﴿هامدة﴾»","url":""}]},{"id":"s22-11","number":11,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما بلاغة إسناد الإنبات إلى الأرض في قوله: ﴿وَأَنْبَتَتْ﴾؟","answer":"أُسند الإنبات إلى الأرض مجازًا عقليًا لأنها محل النبات وسببه الظاهر بعد نزول الماء، أما المنبت حقيقة فهو الله؛ فقرّبت الصورة مشهد الحياة المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص273، تحت عنوان «نكتة المجاز في إسناد الإنبات إلى الأرض»","url":""}]},{"id":"s22-12","number":12,"surah":22,"verses":[6],"references":[{"surah":22,"verses":[6]}],"verseLabel":"الحج: 6","question":"ما سرّ تكرار ﴿أَنَّ﴾ في نتائج الاستدلال على البعث؟","answer":"يبرز التكرار العناية بكل حقيقة مذكورة، فيجعل كل جملة مستقلة ومصدرة بالتوكيد. وهذا يناسب مقام الرد على الجاحدين وإثبات الوحدانية والبعث وسائر ما قررته الآيتان.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص285–286، تحت عنوان «نكتة تكرار (أنّ) في الآيتين»","url":""}]},{"id":"s22-13","number":13,"surah":22,"verses":[7],"references":[{"surah":22,"verses":[7]}],"verseLabel":"الحج: 7","question":"ما دلالة ﴿لَا رَيْبَ فِيهَا﴾ بعد الإخبار بأن الساعة آتية؟","answer":"نفت ﴿لا﴾ جنس الريب توكيدًا لوقوع الساعة ووضوح دلائلها. وليس المراد انتفاء شك الناس فعلًا، بل أنه لا موجب صحيح للشك وإن جحد الجاحدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص290، تحت عنوان «بلاغة النفي بالحرف ﴿لَا﴾ النافية للجنس»","url":""}]},{"id":"s22-14","number":14,"surah":22,"verses":[8],"references":[{"surah":22,"verses":[8]}],"verseLabel":"الحج: 8","question":"ما سر تكرار حرف النفي في قوله: ﴿وَلَا هُدًى وَلَا كِتَابٍ مُنِيرٍ﴾؟","answer":"قرر التكرار استقلال نفي كل مصدر من مصادر الحجة، فلا يملك المجادل واحدًا منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص303، تحت عنوان «سر تكرار حرف النفي في ﴿وَلَا هُدًى وَلَا كِتَابٍ﴾»","url":""}]},{"id":"s22-112","number":112,"surah":22,"verses":[8],"references":[{"surah":22,"verses":[8]}],"verseLabel":"الحج: 8","question":"ما نكتة الجمع بين العلم والهدى والكتاب المنير؟","answer":"استوعب الجمع وجوه الاستناد إلى الحق: العلم، والنظر الهادي، والوحي؛ فنفى عن جدالهم سند العقل والنقل معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص304، تحت عنوان «نكتة الجمع بين العلم والهدى والكتاب المنير»","url":""}]},{"id":"s22-15","number":15,"surah":22,"verses":[9],"references":[{"surah":22,"verses":[9]}],"verseLabel":"الحج: 9","question":"ما دلالة ﴿ثَانِيَ عِطْفِهِ﴾؟","answer":"ثني العطف كناية عن التكبر والإعراض؛ لأن المعرض يلوي جانبه عمن يخاطبه، فجسدت العبارة هيئة من يرد الحق بكبريائه حين يعجز عن الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص305، تحت عنوان «بلاغة الكناية في قوله: ﴿ثَانِيَ عِطْفِهِ﴾»","url":""}]},{"id":"s22-16","number":16,"surah":22,"verses":[10],"references":[{"surah":22,"verses":[10]}],"verseLabel":"الحج: 10","question":"ما بلاغة المجاز في قوله: ﴿بِمَا قَدَّمَتْ يَدَاكَ﴾؟","answer":"عُبر باليدين، وهما آلتا الكسب، عن عمل الإنسان كله؛ فنسب الجزاء إلى ما باشره واختاره بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص318، تحت عنوان «بلاغة المجاز في جملة ﴿بِمَا قَدَّمَتْ يَدَاكَ﴾»","url":""}]},{"id":"s22-113","number":113,"surah":22,"verses":[10],"references":[{"surah":22,"verses":[10]}],"verseLabel":"الحج: 10","question":"ما علة تثنية اليد في قوله: ﴿يَدَاكَ﴾؟","answer":"تثنيتهما تبالغ في نسبة العمل إليه وتبكيته بما جناه بكامل قدرته، لا بما وقع عليه من خارج.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص319، تحت عنوان «علة تثنية اليد في قوله: ﴿يَدَاكَ﴾»","url":""}]},{"id":"s22-17","number":17,"surah":22,"verses":[11],"references":[{"surah":22,"verses":[11]}],"verseLabel":"الحج: 11","question":"ما دلالة الصورة في ﴿يَعْبُدُ اللَّهَ عَلَى حَرْفٍ﴾؟","answer":"تمثل اضطرابه في الدين بمن يقف على طرف لا في موضع ثابت مطمئن؛ كمن يكون على طرف الجيش، فإن وجد الظفر ثبت وإلا هرب، أو من يقف على حرف جبل مهيأ للسقوط. فالصورة تكشف تعلق عبادته بما يصيبه من منفعة دنيوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص330، تحت عنوان «بلاغة الاستعارة في عبادة الله على حرف»","url":""}]},{"id":"s22-18","number":18,"surah":22,"verses":[11],"references":[{"surah":22,"verses":[11]}],"verseLabel":"الحج: 11","question":"ما دلالة ﴿انْقَلَبَ عَلَى وَجْهِهِ﴾ عند إصابة الفتنة؟","answer":"يمثل التعبير الانتكاس بصورة من سقط وانكب على وجهه، وهو تصوير يلائم حال من كان أصلًا على حرف مهدد بالسقوط. وذُكر أيضًا توجيهه بالرجوع إلى ما كان عليه من الكفر أو الشك، مع ترجيح المبحث ملاءمة صورة الانكباب للفظ ﴿على وجهه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص334، تحت عنوان «بلاغة التركيب في جملة ﴿انقلب على وجهه﴾»","url":""}]},{"id":"s22-19","number":19,"surah":22,"verses":[12],"references":[{"surah":22,"verses":[12]}],"verseLabel":"الحج: 12","question":"ما وجه نفي الضر والنفع عن الأصنام مع عدم تصوره منهما؟","answer":"كشف النفي عجزها ووبخ عابدها: لا تضر من تركها ولا تنفع من عبدها، فانتفى أصل استحقاقها للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص344، تحت عنوان «وجه نفي الضر والنفع عن الأصنام مع عدم تصوره منها»","url":""}]},{"id":"s22-114","number":114,"surah":22,"verses":[12],"references":[{"surah":22,"verses":[12]}],"verseLabel":"الحج: 12","question":"ما سر تكرار ﴿مَا﴾ في قوله: ﴿مَا لَا يَضُرُّهُ وَمَا لَا يَنْفَعُهُ﴾؟","answer":"قرر التكرار نفي كل جهة على استقلال، وأكد أن المعبودات ليست أهلًا لضر ولا نفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص345، تحت عنوان «سر تكرير ما مع نفي الضر ونفي النفع»","url":""}]},{"id":"s22-20","number":20,"surah":22,"verses":[13],"references":[{"surah":22,"verses":[13]}],"verseLabel":"الحج: 13","question":"كيف جاءت صيغة التفضيل في قوله: ﴿ضَرُّهُ أَقْرَبُ مِنْ نَفْعِهِ﴾ مع نفي النفع؟","answer":"لا تثبت نفعًا حقيقيًا، بل تفيد التهكم وتقرر تمحض العبادة للضر؛ فجاءت المقارنة على حسب زعم العابد أو لتغليب الضر المحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص349–350، تحت عنوان «وجه إيثار من على ما وصيغة التفضيل»","url":""}]},{"id":"s22-115","number":115,"surah":22,"verses":[13],"references":[{"surah":22,"verses":[13]}],"verseLabel":"الحج: 13","question":"لماذا أضيف الضر إلى الصنم ولم يُسند إليه فعل الإضرار؟","answer":"لأن الضر ملازم لعبادته وليس فعلًا يصدر عن الصنم العاجز؛ فالإضافة تناسب هذه الملابسة وتكني عن خلو العبادة من النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص350، تحت عنوان «علة إيثار الإضافة للضمير على الإسناد»","url":""}]},{"id":"s22-21","number":21,"surah":22,"verses":[15],"references":[{"surah":22,"verses":[15]}],"verseLabel":"الحج: 15","question":"ما غرض الأمر في قوله: ﴿فَلْيَمْدُدْ بِسَبَبٍ إِلَى السَّمَاءِ﴾؟","answer":"الأمر للتعجيز أو الإهانة، إذ لا تنفع الحيلة الساخط على نصر الله ولا تمكنه من قطع سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص368–369، تحت عنوان «غرض الأمر في قوله سبحانه: ﴿فَلْيَمْدُدْ﴾»","url":""}]},{"id":"s22-116","number":116,"surah":22,"verses":[15],"references":[{"surah":22,"verses":[15]}],"verseLabel":"الحج: 15","question":"ما غرض الاستفهام في قوله: ﴿هَلْ يُذْهِبَنَّ كَيْدُهُ مَا يَغِيظُ﴾؟","answer":"الاستفهام إنكاري يقرر عجز كيده عن إزالة ما يغيظه من نصر الله، مهما بالغ في حيلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص370، تحت عنوان «غرض الاستفهام في قوله: ﴿هَلْ يُذْهِبَنَّ﴾»","url":""}]},{"id":"s22-22","number":22,"surah":22,"verses":[16],"references":[{"surah":22,"verses":[16]}],"verseLabel":"الحج: 16","question":"ما دلالة وصف القرآن بأنه ﴿آيَاتٍ بَيِّنَاتٍ﴾؟","answer":"وصف القرآن بآيات بينات يجمع كونه دلائل وعلامات على الحق مع ظهور حججها ووضوح بيانها، فهي جديرة بالإيمان لا أدلة خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص378، تحت عنوان «بلاغة وصف الآيات بالبينات»","url":""}]},{"id":"s22-23","number":23,"surah":22,"verses":[17],"references":[{"surah":22,"verses":[17]}],"verseLabel":"الحج: 17","question":"ما دلالة اختيار لفظ ﴿يَفْصِلُ﴾ بعد تعداد أهل الملل؟","answer":"يتضمن الفصل الحكم وتمييز المحق من المبطل، لا مجرد إنهاء الخصومة؛ فرد مصير الفرق كلها إلى حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص393–394، تحت عنوان «دلالة اختيار مفردة الفصل دون مرادفاتها»","url":""}]},{"id":"s22-117","number":117,"surah":22,"verses":[17],"references":[{"surah":22,"verses":[17]}],"verseLabel":"الحج: 17","question":"ما نكتة تحديد الفصل بيوم القيامة؟","answer":"فيه تسلية لأهل الحق وتهديد لأهل الباطل؛ فالإمهال في الدنيا لا يعني إهمال الحكم والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص395، تحت عنوان «نكتة ذكر زمان الفصل»","url":""}]},{"id":"s22-24","number":24,"surah":22,"verses":[18],"references":[{"surah":22,"verses":[18]}],"verseLabel":"الحج: 18","question":"ما دلالة إسناد السجود إلى المخلوقات، ومنها الشمس والقمر والجبال والشجر والدواب؟","answer":"يبرز السجود كمال الخضوع والانقياد لله. وبيّن المبحث أن لكل ساجد هيئة تخصه، وأن حمل اللفظ على معناه اللغوي الأوسع يجمع المخلوقات كلها في الانقياد؛ فلا يلزم أن تكون هيئة سجودها كهيئة سجود الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص408–409، تحت عنوان «لفظ ﴿يسجد﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s22-25","number":25,"surah":22,"verses":[18],"references":[{"surah":22,"verses":[18]}],"verseLabel":"الحج: 18","question":"ما بلاغة الاحتراس بلفظ ﴿كَثِيرٌ﴾ دون الأكثر؟","answer":"يمنع اللفظ توهم أن أحد الفريقين هو الأكثر على وجه الحصر أو أن العددين متساويان؛ فكل منهما كثير من جهة معتبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص415، تحت عنوان «بلاغة الاحتراس بذكر الكثير دون الأكثر»","url":""}]},{"id":"s22-118","number":118,"surah":22,"verses":[18],"references":[{"surah":22,"verses":[18]}],"verseLabel":"الحج: 18","question":"ما بلاغة التقابل بين الساجدين ومن حق عليهم العذاب؟","answer":"أظهر التقابل افتراق الناس أمام آيات الله إلى أهل خضوع وعبادة وأهل استحقاق للعذاب، فبرز تفاوت العاقبتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص416، تحت عنوان «بلاغة التقابل بين الجمل»","url":""}]},{"id":"s22-26","number":26,"surah":22,"verses":[19],"references":[{"surah":22,"verses":[19]}],"verseLabel":"الحج: 19","question":"ما سرّ الجمع في ﴿هَذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ﴾ بعد التثنية؟","answer":"التثنية باعتبار الفريقين، والجمع باعتبار الأفراد الذين يضمهم كل فريق. فالخصم يصدق على الواحد والجماعة، وجاء ﴿اختصموا﴾ حملًا على المعنى؛ فلا تعارض بين تثنية الفريقين وجمع المتخاصمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص431، تحت عنوان «بلاغة العدول إلى الجمع والمرجع مثنى»","url":""}]},{"id":"s22-27","number":27,"surah":22,"verses":[19,20,21,22],"references":[{"surah":22,"verses":[19,20,21,22]}],"verseLabel":"الحج: 19-22","question":"ما بلاغة التتميم في تفصيل عذاب أهل النار؟","answer":"تمم التصوير بإحاطة الثياب بالظاهر ونفوذ الحميم إلى الباطن وإضافة المقامع، فاستوعب ألوان الإيلام ولم يترك منفذًا لتوهم خفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص452، تحت عنوان «بلاغة فن التتميم»","url":""}]},{"id":"s22-119","number":119,"surah":22,"verses":[19,20,21,22],"references":[{"surah":22,"verses":[19,20,21,22]}],"verseLabel":"الحج: 19-22","question":"ما فصاحة التعبير بلفظ ﴿مَقَامِعُ﴾؟","answer":"المقامع أدوات تضرب بها الرؤوس وتقمع أصحابها، فجمع اللفظ الألم والإذلال والرد العنيف إلى النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص447، تحت عنوان «فصاحة التعبير بلفظ ﴿مَقَامِعُ﴾»","url":""}]},{"id":"s22-28","number":28,"surah":22,"verses":[20],"references":[{"surah":22,"verses":[20]}],"verseLabel":"الحج: 20","question":"ما بلاغة جملة الحال في وصف صب الحميم؟","answer":"بينت الحال أثر الحميم الملازم لصبه: نفاذه إلى البطون والجلود، حتى لا يتوهم اقتصار العذاب على ظاهر الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص442–443، تحت عنوان «بلاغة جملة الحال»","url":""}]},{"id":"s22-120","number":120,"surah":22,"verses":[20],"references":[{"surah":22,"verses":[20]}],"verseLabel":"الحج: 20","question":"ما فصاحة اختيار ﴿يُصْهَرُ﴾ دون «يذاب»؟","answer":"الصهر أبلغ في تصوير الإذابة بحر شديد يبلغ الباطن ويخلط ما فيه، فزاد المشهد عنفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص443، تحت عنوان «فصاحة اختيار مفردة الصهر دون الإذابة»","url":""}]},{"id":"s22-121","number":121,"surah":22,"verses":[20],"references":[{"surah":22,"verses":[20]}],"verseLabel":"الحج: 20","question":"ما نكتة التعبير بالموصول ﴿مَا فِي بُطُونِهِمْ﴾؟","answer":"عمم الموصول كل ما في البطون بدل تسمية عضو بعينه، فشمل الأمعاء والأحشاء وسائر الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص444، تحت عنوان «نكتة مجيء نائب الفاعل اسمًا موصولًا»","url":""}]},{"id":"s22-29","number":29,"surah":22,"verses":[22],"references":[{"surah":22,"verses":[22]}],"verseLabel":"الحج: 22","question":"ما سرّ التعبير بـ﴿أُعِيدُوا فِيهَا﴾ لا «أُدخلوا فيها»؟","answer":"لأنهم لم يخرجوا من النار أصلًا، وإنما يُردون داخلها إلى الموضع الذي تحركوا منه طلبًا للخروج. فالإعادة هنا لا تستلزم خروجًا تامًا، بخلاف الإدخال الذي يوهم تحقق الخروج أولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص450، تحت عنوان «فصاحة استعمال الإعادة دون الإدخال»","url":""}]},{"id":"s22-30","number":30,"surah":22,"verses":[23],"references":[{"surah":22,"verses":[23]}],"verseLabel":"الحج: 23","question":"ما وجه اختيار جمع ﴿أَسَاوِرَ﴾ في نعيم أهل الجنة؟","answer":"يبرز الجمع كثرة الحلي وتنوع أجناسها وأشكالها، فيزيد تصوير الإكرام والزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص462، تحت عنوان «وجه اختيار صيغة جمع ﴿أَسَاوِرَ﴾»","url":""}]},{"id":"s22-122","number":122,"surah":22,"verses":[23],"references":[{"surah":22,"verses":[23]}],"verseLabel":"الحج: 23","question":"ما نكتة الجملة الاسمية في قوله: ﴿وَلِبَاسُهُمْ فِيهَا حَرِيرٌ﴾؟","answer":"تدل الجملة الاسمية على ثبات لباس الحرير ودوامه لهم، لا تحلٍّ عارض ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص464، تحت عنوان «نكتة التعبير بصيغة الجملة الاسمية في ﴿وَلِبَاسُهُمْ فِيهَا حَرِيرٌ﴾»","url":""}]},{"id":"s22-31","number":31,"surah":22,"verses":[24],"references":[{"surah":22,"verses":[24]}],"verseLabel":"الحج: 24","question":"ما موقع قوله: ﴿وَهُدُوا إِلَى صِرَاطِ الْحَمِيدِ﴾ مما قبله؟","answer":"عطف هداية العمل والطريق على هداية القول، وتكرار هدوا رفع منزلتيهما وربطهما في نعيم المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص474، تحت عنوان «موقع جملة ﴿وَهُدُوا إِلَى صِرَاطِ الْحَمِيدِ﴾ مما قبلها»","url":""}]},{"id":"s22-123","number":123,"surah":22,"verses":[24],"references":[{"surah":22,"verses":[24]}],"verseLabel":"الحج: 24","question":"ما نكتة ترتيب القول الطيب ثم صراط الحميد؟","answer":"قدم القول على العمل، ثم ختم بالصراط لأنه الطريق الجامع الذي يفضي إليه القول الطيب والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص476، تحت عنوان «نكتة ترتيب قسمي المعنى في الآية»","url":""}]},{"id":"s22-32","number":32,"surah":22,"verses":[25],"references":[{"surah":22,"verses":[25]}],"verseLabel":"الحج: 25","question":"ما غرض تنكير ﴿سَوَاءً﴾ وحذف جهة التسوية؟","answer":"عمم الحذف وجوه التسوية المناسبة، وعلى رأسها استواء المقيم والقادم في حق العبادة والمناسك، بلا مزية لأحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص484، تحت عنوان «غرض تنكير ﴿سَوَاءً﴾ وحذف جهة التسوية»","url":""}]},{"id":"s22-124","number":124,"surah":22,"verses":[25],"references":[{"surah":22,"verses":[25]}],"verseLabel":"الحج: 25","question":"ما نكتة تقديم العاكف والطباق بينه وبين البادي؟","answer":"قدم المقيم لأنه مظنة دعوى الاختصاص، ثم قابله بالقادم تعريضًا بمن يمنع الوافدين متذرعًا بإقامته عند البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص486، تحت عنوان «نكتة التقديم والطباق في العاكف والبادي»","url":""}]},{"id":"s22-33","number":33,"surah":22,"verses":[25],"references":[{"surah":22,"verses":[25]}],"verseLabel":"الحج: 25","question":"ما معنى الباء في قوله: ﴿بِإِلْحَادٍ﴾؟","answer":"تحتمل الملابسة أو السببية أو التوكيد، فتربط الإرادة بميل ظالم عن الحق من غير حصر المعنى في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص488، تحت عنوان «معنى الباء في ﴿بِإِلْحَادٍ﴾»","url":""}]},{"id":"s22-125","number":125,"surah":22,"verses":[25],"references":[{"surah":22,"verses":[25]}],"verseLabel":"الحج: 25","question":"ما فائدة تقييد الإلحاد بقوله: ﴿بِظُلْمٍ﴾؟","answer":"يخرج القيد ما كان بحق ومأذونًا فيه، ويقرر أن الوعيد على الميل المتلبس بالظلم أو الناشئ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص489، تحت عنوان «فائدة التقييد بقوله: ﴿بِظُلْمٍ﴾»","url":""}]},{"id":"s22-34","number":34,"surah":22,"verses":[26],"references":[{"surah":22,"verses":[26]}],"verseLabel":"الحج: 26","question":"ما سرّ تقديم ﴿لَا تُشْرِكْ بِي شَيْئًا﴾ على الأمر بتطهير البيت؟","answer":"جمع النظم بين طهارة الحال وطهارة المحل، وقدم النهي عن الشرك لأنه الأصل الذي يتفرع عليه ما بعده. فالأمر بتطهير البيت تابع لتحقيق الإخلاص، لا منفصل عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص497، تحت عنوان «موقع جملة: ﴿وطهر﴾ مما قبلها وسر ترتيبهما»","url":""}]},{"id":"s22-35","number":35,"surah":22,"verses":[26],"references":[{"surah":22,"verses":[26]}],"verseLabel":"الحج: 26","question":"ما علة ترتيب ﴿الطَّائِفِينَ وَالْقَائِمِينَ﴾؟","answer":"قدم الطائفين لأن الطواف أخص بالبيت وأشد اتصالًا به، ثم القيام المشترك بينه وبين سائر المساجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص499، تحت عنوان «علة الترتيب في ﴿الطَّائِفِينَ وَالْقَائِمِينَ﴾»","url":""}]},{"id":"s22-126","number":126,"surah":22,"verses":[26],"references":[{"surah":22,"verses":[26]}],"verseLabel":"الحج: 26","question":"ما نكتة ترك العطف بين ﴿الرُّكَّعِ السُّجُودِ﴾؟","answer":"دل ترك العطف على شدة اتصال الركوع والسجود وكونهما كهيئة واحدة متتابعة في الصلاة والخضوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص499–500، تحت عنوان «نكتة ترك العطف بين الركوع والسجود»","url":""}]},{"id":"s22-36","number":36,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما دلالة صيغة التضعيف في قوله: ﴿وَأَذِّنْ فِي النَّاسِ بِالْحَجِّ﴾؟","answer":"تفيد صيغة التفعيل قوة إسماع النداء وتكريره وتبليغه؛ فليس المراد مجرد نداء خافت، بل إعلان الحج في الناس إعلانًا يبلغهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص505، تحت عنوان «دلالة التضعيف في: ﴿وَأَذِّنْ﴾»","url":""}]},{"id":"s22-127","number":127,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما دلالة ﴿أل﴾ في قوله: ﴿وَأَذِّنْ فِي النَّاسِ بِالْحَجِّ﴾؟","answer":"هي للجنس والاستغراق، فتتجه الدعوة إلى الناس عامة في الأجيال المتعاقبة، لا إلى جماعة حاضرة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص506، تحت عنوان «معنى (أل) في ﴿النَّاسِ﴾»","url":""}]},{"id":"s22-37","number":37,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"لماذا وُصف الفج بأنه ﴿عَمِيقٍ﴾ لا بعيد؟","answer":"العمق أنسب بالفج؛ لأنه طريق منخفض بين جبلين، ويستلزم امتداد المسافة مع تصوير انخفاض الطريق ووعورته، بخلاف البعد الذي يذكر المسافة مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص511–512، تحت عنوان «نكتة الوصف بالعمق دون البعد»","url":""}]},{"id":"s22-128","number":128,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما بلاغة تعليق الإتيان بقوله: ﴿مِنْ كُلِّ فَجٍّ عَمِيقٍ﴾؟","answer":"هو كناية عن بُعد بلاد الحجاج وشدة ما يقطعونه للوصول؛ فعلّق الإتيان بالطريق العميق ليجسد طول الرحلة ومشقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص512، تحت عنوان «بلاغة الكناية في تعليق الإتيان بالفج العميق»","url":""}]},{"id":"s22-38","number":38,"surah":22,"verses":[28],"references":[{"surah":22,"verses":[28]}],"verseLabel":"الحج: 28","question":"ما دلالة تنكير ﴿مَنَافِعَ﴾ في ﴿لِيَشْهَدُوا مَنَافِعَ لَهُمْ﴾؟","answer":"يفيد إبهام أنواع المنافع وعدم حصرها في منفعة معينة، مع التكثير والتفخيم؛ فهي منافع كثيرة تختص بهذه الشعائر. وجمع الكثرة يزيد الترغيب في شهودها ونيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص515–516، تحت عنوان «دلالة تنكير كلمة: ﴿منافع﴾»","url":""}]},{"id":"s22-39","number":39,"surah":22,"verses":[29],"references":[{"surah":22,"verses":[29]}],"verseLabel":"الحج: 29","question":"ما دلالة ﴿ثُمَّ﴾ في ﴿ثُمَّ لْيَقْضُوا تَفَثَهُمْ﴾؟","answer":"وجهها المبحث بالتراخي الرتبي: فقضاء المناسك والوفاء بالنذور والطواف بالبيت أهم في مقصد الخطاب مما سبق من شهود المنافع وذبح الهدايا. فهي تنقل الاهتمام إلى إتمام الواجبات، ولا يقتصر وجهها على مجرد الترتيب الزمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص526، تحت عنوان «موقع جملة: ﴿ثم ليقضوا﴾ ونكتة العطف بـ﴿ثم﴾»","url":""}]},{"id":"s22-40","number":40,"surah":22,"verses":[30],"references":[{"surah":22,"verses":[30]}],"verseLabel":"الحج: 30","question":"ما سر عطف ﴿وَاجْتَنِبُوا قَوْلَ الزُّورِ﴾ على اجتناب رجس الأوثان؟","answer":"عطف العام على الخاص؛ فعبادة الأوثان من أعظم الزور، ثم عم النهي كل قول زور. ويجعل الترتيب الانتقال من أصل الشرك إلى ما يتفرع عنه من الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص539، تحت عنوان «دلالة الواو في: ﴿وَاجْتَنِبُوا﴾ وسر ترتيب جملتي الأمرين والإضافة في ﴿قَوْلَ الزُّورِ﴾»","url":""}]},{"id":"s22-129","number":129,"surah":22,"verses":[30],"references":[{"surah":22,"verses":[30]}],"verseLabel":"الحج: 30","question":"ما سر تكرار فعل الأمر ﴿اجْتَنِبُوا﴾ مع قرب ذكره؟","answer":"جدد الأمر ليجعل قول الزور مطلوب الاجتناب استقلالًا، ويزيد العناية بالنهي عنه والتنفير منه بدل أن يأتي تابعًا خفيًا لما قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص539، تحت عنوان «سر تكرار فعل الأمر رغم قرب ذكره»","url":""}]},{"id":"s22-41","number":41,"surah":22,"verses":[31],"references":[{"surah":22,"verses":[31]}],"verseLabel":"الحج: 31","question":"ما دلالة تشبيه المشرك بمن خرّ من السماء فتخطفه الطير أو تهوي به الريح؟","answer":"تمثل الصورة هلاكه وتبدد أمره بعد مفارقة الإيمان، كمن سقط من علو فلا يستقر ولا ينجو. وذكر المبحث إمكان تفريق عناصر التشبيه أيضًا: فالإيمان في علوه كالسماء، والأهواء الممزقة كخطف الطير، والشيطان المضل كالريح التي تقذف إلى المهالك.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص557، تحت عنوان «بلاغة التشبيه في الآية»","url":""}]},{"id":"s22-42","number":42,"surah":22,"verses":[32],"references":[{"surah":22,"verses":[32]}],"verseLabel":"الحج: 32","question":"ما دلالة إضافة التقوى إلى القلوب في ﴿فَإِنَّهَا مِنْ تَقْوَى الْقُلُوبِ﴾؟","answer":"القلوب محل حقيقة التقوى؛ فإذا ثبتت فيها ظهر أثرها في سائر الأعضاء. فتعظيم الشعائر ليس مظهرًا منفصلًا عن الباطن، بل علامة على ما في القلب من التقوى والإجلال لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص566، تحت عنوان «دلالة الإضافة في: ﴿تقوى القلوب﴾»","url":""}]},{"id":"s22-43","number":43,"surah":22,"verses":[34],"references":[{"surah":22,"verses":[34]}],"verseLabel":"الحج: 34","question":"ما دلالة استعمال ﴿كُلِّ﴾؟","answer":"يفيد ﴿كل﴾ عموم الأمم ذات الشرائع، وأن أصل النسك والتقرب إلى الله مشروع فيها، وإن اختلفت تفاصيل المناسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص576–577، تحت عنوان «دلالة استعمال ﴿كُلِّ﴾»","url":""}]},{"id":"s22-130","number":130,"surah":22,"verses":[34],"references":[{"surah":22,"verses":[34]}],"verseLabel":"الحج: 34","question":"ما دلالة اللام في قوله: ﴿لِيَذْكُرُوا اسْمَ اللَّهِ﴾؟","answer":"هي لام التعليل؛ تبين أن الغاية من تشريع النسك ذكر اسم الله وتوحيده، لا مجرد عادة الذبح أو صورته المادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص579، تحت عنوان «نوع اللام ودلالتها»","url":""}]},{"id":"s22-44","number":44,"surah":22,"verses":[35],"references":[{"surah":22,"verses":[35]}],"verseLabel":"الحج: 35","question":"لماذا وُصف المخبتون بالوجل في قوله: ﴿وَجِلَتْ قُلُوبُهُمْ﴾؟","answer":"الوجل خوف داخلي رقيق ينشأ من تعظيم الله واستشعار جلاله، فاختير لتصوير أثر ذكره في قلوب المخبتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص590، تحت عنوان «نكتة استعمال الوجل دون مرادفاته»","url":""}]},{"id":"s22-131","number":131,"surah":22,"verses":[35],"references":[{"surah":22,"verses":[35]}],"verseLabel":"الحج: 35","question":"ما دلالة جمع الصبر والصلاة والإنفاق في صفات المخبتين وترتيبها؟","answer":"جمع صفات القلب والعمل والمال: الصبر عند البلاء، وإقامة الصلاة في حق الله، والإنفاق في حق الخلق. وترتيبها ينتقل من احتمال المشقة إلى العبادة البدنية ثم البذل المالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص591–592، تحت عنوان «بلاغة ذكر الصبر والصلاة والإنفاق وترتيبها»","url":""}]},{"id":"s22-45","number":45,"surah":22,"verses":[36],"references":[{"surah":22,"verses":[36]}],"verseLabel":"الحج: 36","question":"ما دلالة التعبير بالجعل في قوله: ﴿جَعَلْنَاهَا لَكُمْ مِنْ شَعَائِرِ اللَّهِ﴾؟","answer":"يفيد الجعل أن الله هو الذي صيّر البدن شعارًا تعبديًا ظاهرًا وقرر لها هذه المنزلة الشرعية، لا أنها اكتسبتها بذاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص604، تحت عنوان «نكتة التعبير بالجعل ﴿جَعَلْنَاهَا﴾»","url":""}]},{"id":"s22-46","number":46,"surah":22,"verses":[36],"references":[{"surah":22,"verses":[36]}],"verseLabel":"الحج: 36","question":"ما سرّ التعبير بـ﴿فَإِذَا وَجَبَتْ جُنُوبُهَا﴾؟","answer":"وجوب الجنوب سقوطها إلى الأرض؛ وهو كناية عن موت البدن وزوال أرواحها بعد النحر. فذكر العلامة المشاهدة الدالة على الموت بدل التصريح به.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص610، تحت عنوان «بلاغة الكناية في ﴿وجبت جنوبها﴾»","url":""}]},{"id":"s22-47","number":47,"surah":22,"verses":[37],"references":[{"surah":22,"verses":[37]}],"verseLabel":"الحج: 37","question":"ما دلالة المقابلة بين ﴿لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا﴾ و﴿وَلَكِنْ يَنَالُهُ التَّقْوَى مِنْكُمْ﴾؟","answer":"تنفي الآية أن يصل إلى الله نفع من اللحوم والدماء، وتقرر أن المقبول من العبد هو التقوى والإخلاص. وصُوّر تعلق القبول بالتقوى بوصول شيء إلى متلقيه، مع مشاكلة التعبير السابق بالنيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص619، تحت عنوان «بلاغة التعبير بقوله: ﴿يَنَالُهُ﴾»","url":""}]},{"id":"s22-48","number":48,"surah":22,"verses":[38],"references":[{"surah":22,"verses":[38]}],"verseLabel":"الحج: 38","question":"ما دلالة صيغة ﴿يُدَافِعُ﴾ في ﴿إِنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا﴾؟","answer":"المضارع يصور دفاع الله عن المؤمنين متجددًا مستمرًا، وصيغة المفاعلة تقوي معنى رد العدوان مرة بعد مرة بحسب تجدده، مع كمال قدرة الله على المدافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص631، تحت عنوان «براعة التعبير بالمضارع ﴿يُدَافِعُ﴾»","url":""}]},{"id":"s22-49","number":49,"surah":22,"verses":[39],"references":[{"surah":22,"verses":[39]}],"verseLabel":"الحج: 39","question":"ما دلالة الباء في قوله: ﴿بِأَنَّهُمْ ظُلِمُوا﴾؟","answer":"الباء سببية، فتجعل وقوع الظلم عليهم علة الإذن لهم بالقتال، وتظهر أن القتال دفع للعدوان لا ابتداء له.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص643، تحت عنوان «دلالة الباء في جملة ﴿بِأَنَّهُمْ ظُلِمُوا﴾»","url":""}]},{"id":"s22-132","number":132,"surah":22,"verses":[39],"references":[{"surah":22,"verses":[39]}],"verseLabel":"الحج: 39","question":"ما سر التوكيد في قوله: ﴿بِأَنَّهُمْ ظُلِمُوا﴾؟","answer":"أكدت الجملة تحقق الظلم ووقوعه عليهم، فثبت استحقاقهم الإذن بالدفاع وقطع توهم أن دعواهم مجرد زعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص644، تحت عنوان «سر التوكيد في جملة ﴿بِأَنَّهُمْ ظُلِمُوا﴾»","url":""}]},{"id":"s22-50","number":50,"surah":22,"verses":[40],"references":[{"surah":22,"verses":[40]}],"verseLabel":"الحج: 40","question":"ما دلالة تعداد ﴿صَوَامِعُ وَبِيَعٌ وَصَلَوَاتٌ وَمَسَاجِدُ﴾؟","answer":"يفصّل النظم دور العبادة تعظيمًا لشأنها وإبرازًا لما يتهددها من الهدم عند غياب الدفع. فالتعداد يزيد الاهتمام بها ويصور اتساع الخراب الذي ينال مواضع العبادة، بدل الاكتفاء بذكرها إجمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص667، تحت عنوان «نكتة تعداد دور العبادة المذكورة»","url":""}]},{"id":"s22-51","number":51,"surah":22,"verses":[40],"references":[{"surah":22,"verses":[40]}],"verseLabel":"الحج: 40","question":"لماذا أُخرت المساجد في تعداد دور العبادة مع جدارتها بالتقديم؟","answer":"راعى الترتيب الزمني فذكر الأقدم فالأحدث، ثم أخر المساجد مع شرفها ليكون ختام التعداد بأشرف دور العبادة وأكثرها قيامًا بالتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص669، تحت عنوان «سر تأخير المساجد مع جدارتها بالتقديم»","url":""}]},{"id":"s22-133","number":133,"surah":22,"verses":[40],"references":[{"surah":22,"verses":[40]}],"verseLabel":"الحج: 40","question":"ما دلالة التعبير بالذكر في قوله: ﴿يُذْكَرُ فِيهَا اسْمُ اللَّهِ كَثِيرًا﴾؟","answer":"اختير الذكر لأنه اسم جامع لعبادات دور العبادة من صلاة وتلاوة ودعاء وتسبيح، ولأن المقصود إبراز قيامها بتوحيد الله مقابل مواضع الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص670، تحت عنوان «دلالة التعبير بمفردة الذكر دون غيره من أنواع العبادة»","url":""}]},{"id":"s22-52","number":52,"surah":22,"verses":[41],"references":[{"surah":22,"verses":[41]}],"verseLabel":"الحج: 41","question":"ما سرّ تقديم إقامة الصلاة وإيتاء الزكاة على الأمر بالمعروف والنهي عن المنكر؟","answer":"بدأ بما يقيم صلة العبد بربه، ثم بما يظهر صدق الإيمان في بذل المال وإصلاح العلاقة بالمجتمع، ثم بالأمر والنهي اللذين يحفظان صلاحه. فالترتيب يصل عبادة الله والإحسان إلى الناس بإقامة المعروف ودفع المنكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص693–694، تحت عنوان «براعة ترتيب الأفعال في الآية»","url":""}]},{"id":"s22-53","number":53,"surah":22,"verses":[42,43,44],"references":[{"surah":22,"verses":[42,43,44]}],"verseLabel":"الحج: 42-44","question":"ما دلالة ﴿قَدْ﴾ في قوله بعد تعداد الأمم: ﴿فَقَدْ كَذَّبَتْ قَبْلَهُمْ﴾؟","answer":"تفيد التحقيق والتأكيد، فتقرر أن التكذيب سنة واقعة من الأمم السابقة، وفي استحضار نظائرهم تثبيت للرسول ووعيد لقومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص702، تحت عنوان «دلالة (قد) في ﴿فَقَدْ كَذَّبَتْ﴾»","url":""}]},{"id":"s22-134","number":134,"surah":22,"verses":[42,43,44],"references":[{"surah":22,"verses":[42,43,44]}],"verseLabel":"الحج: 42-44","question":"ما سر التعبير بالإملاء في قوله: ﴿فَأَمْلَيْتُ لِلْكَافِرِينَ﴾؟","answer":"الإملاء إمهال المذنب وتركه مدة قبل العقوبة، فيبين أن تأخير الأخذ ليس رضا ولا عجزًا، بل مهلة يعقبها الجزاء إن أصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص711، تحت عنوان «سر التعبير بلفظ الإملاء»","url":""}]},{"id":"s22-55","number":55,"surah":22,"verses":[46],"references":[{"surah":22,"verses":[46]}],"verseLabel":"الحج: 46","question":"ما سرّ نفي العمى عن الأبصار وإثباته للقلوب؟","answer":"المقصود بيان أن العمى المذموم هنا هو فقد الفقه والاعتبار، لا فقد البصر الحسي. فقد تبصر العين الآثار ولا ينتفع صاحبها بها إذا عميت بصيرته؛ لذلك نُقل الاهتمام من سلامة الأبصار إلى سلامة القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص748، تحت عنوان «نكتة إثبات العمى للقلوب»","url":""}]},{"id":"s22-56","number":56,"surah":22,"verses":[47],"references":[{"surah":22,"verses":[47]}],"verseLabel":"الحج: 47","question":"ما دلالة التعبير بالعندية في قوله: ﴿وَإِنَّ يَوْمًا عِنْدَ رَبِّكَ﴾؟","answer":"العندية تبين أن تقدير الزمن راجع إلى حكم الله وتدبيره، لا إلى استعجال البشر ومقاييسهم المحدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص763، تحت عنوان «دلالة التعبير بالعندية ظرفًا»","url":""}]},{"id":"s22-135","number":135,"surah":22,"verses":[47],"references":[{"surah":22,"verses":[47]}],"verseLabel":"الحج: 47","question":"ما بلاغة تشبيه يوم عند الله بألف سنة مما يعد الناس؟","answer":"يقرب التشبيه تفاوت مقاييس الزمن، ويقرر أن ما يراه الناس بعيدًا يسير في تقدير الله؛ فليس المقصود معادلة حسابية مجردة، بل إبطال استعجال العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص764–765، تحت عنوان «بلاغة التشبيه ووجهه»","url":""}]},{"id":"s22-57","number":57,"surah":22,"verses":[48],"references":[{"surah":22,"verses":[48]}],"verseLabel":"الحج: 48","question":"ما دلالة الجملة الحالية في قوله: ﴿أَمْلَيْتُ لَهَا وَهِيَ ظَالِمَةٌ﴾؟","answer":"تبين الحال أن الإمهال وقع مع استمرار القرى في الظلم، فلا يدل طول المهلة على براءتها أو رضا الله عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص776، تحت عنوان «دلالة الجملة الحالية»","url":""}]},{"id":"s22-136","number":136,"surah":22,"verses":[48],"references":[{"surah":22,"verses":[48]}],"verseLabel":"الحج: 48","question":"ما دلالة ﴿ثُمَّ﴾ في قوله: ﴿ثُمَّ أَخَذْتُهَا﴾؟","answer":"تفيد التراخي بين الإملاء والأخذ، فتصور مهلة ممتدة أعقبتها العقوبة، وتقرر أن تأخر الجزاء لا يمنع وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص776–777، تحت عنوان «إيثار العطف بحرف التراخي ﴿ثُمَّ﴾»","url":""}]},{"id":"s22-58","number":58,"surah":22,"verses":[50,51],"references":[{"surah":22,"verses":[50,51]}],"verseLabel":"الحج: 50-51","question":"ما سر وصف رزق المؤمنين بأنه ﴿كَرِيمٌ﴾؟","answer":"الكريم رزق نفيس حسن كثير دائم، ووصفه بالكرم يشعر بأنه إكرام من الله لا مجرد منفعة مادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص794–795، تحت عنوان «سر وصف الرزق بـ﴿كَرِيمٌ﴾»","url":""}]},{"id":"s22-59","number":59,"surah":22,"verses":[52],"references":[{"surah":22,"verses":[52]}],"verseLabel":"الحج: 52","question":"ما دلالة الفاء في قوله ﴿فَيَنْسَخُ اللَّهُ مَا يُلْقِي الشَّيْطَانُ﴾؟","answer":"تفيد الفاء سرعة التعقيب مع السببية؛ فيزيل الله ما يلقيه الشيطان دون إبطاء، حماية للأنبياء وعصمة لهم في تبليغ الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص30، تحت عنوان «دلالة التعقيب بالفاء في الجملة الكريمة»","url":""}]},{"id":"s22-84","number":84,"surah":22,"verses":[52],"references":[{"surah":22,"verses":[52]}],"verseLabel":"الحج: 52","question":"لماذا عُطف إحكام الآيات بـ﴿ثُمَّ﴾ في قوله ﴿ثُمَّ يُحْكِمُ اللَّهُ آيَاتِهِ﴾؟","answer":"التراخي هنا في الرتبة؛ فإحكام الآيات وتقريرها مرتبة أعلى من إزالة ما ألقاه الشيطان. لذلك لا يلزم من «ثم» في هذا الموضع تأخر الإحكام زمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص31، تحت عنوان «إيثار العطف بأداة التراخي ﴿ثم﴾»","url":""}]},{"id":"s22-60","number":60,"surah":22,"verses":[53],"references":[{"surah":22,"verses":[53]}],"verseLabel":"الحج: 53","question":"ما المقصود بالمرض في قوله ﴿لِلَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ﴾؟","answer":"المراد هنا مرض الشك والشبهة والنفاق، لا المرض الجسدي. وجاء «مرض» نكرة لبيان نوعه ولتهويل ضرره على القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص40، تحت عنوان «معنى المرض المذكور ووجه تنكيره»","url":""}]},{"id":"s22-90","number":90,"surah":22,"verses":[53],"references":[{"surah":22,"verses":[53]}],"verseLabel":"الحج: 53","question":"لماذا ذُكرت ﴿الْقَاسِيَةِ قُلُوبُهُمْ﴾ بعد ﴿الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ﴾؟","answer":"لتمييز حالين: مرض الشك والنفاق، وقسوة قلوب المشركين عن قبول الحق. فالفتنة تصيب الصنفين، مع اختلاف حال الكفر الخفي عن الكفر المعلن.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص40–41، تحت عنوان «دلالة إتباع وصف القسوة بعد وصف المرض»","url":""}]},{"id":"s22-61","number":61,"surah":22,"verses":[54],"references":[{"surah":22,"verses":[54]}],"verseLabel":"الحج: 54","question":"ما سرّ التعبير عن خضوع قلوب أهل العلم بالإخبات؟","answer":"أصل الخبت المكان المنخفض المطمئن، فاستعير الإخبات لتواضع القلوب وخضوعها وسكونها إلى الحق؛ فيصوّر إيمانًا راسخًا يورث الطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص53، تحت عنوان «بلاغة الاستعارة في التعبير عن التواضع بالإخبات»","url":""}]},{"id":"s22-85","number":85,"surah":22,"verses":[54],"references":[{"surah":22,"verses":[54]}],"verseLabel":"الحج: 54","question":"ما دلالة الفاء في قوله ﴿فَيُؤْمِنُوا بِهِ فَتُخْبِتَ لَهُ قُلُوبُهُمْ﴾؟","answer":"الفاء في «فتخبت» تربط الإخبات بالإيمان على جهة السببية؛ فمعرفة الحق والتصديق به يثمران تواضع القلوب وخشوعها وسكونها إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص52–53، تحت عنوان «معنى العطف بالفاء في ﴿فتخبت﴾»","url":""}]},{"id":"s22-62","number":62,"surah":22,"verses":[55],"references":[{"surah":22,"verses":[55]}],"verseLabel":"الحج: 55","question":"ما دلالة ﴿حَتَّى﴾ في قوله ﴿حَتَّى تَأْتِيَهُمُ السَّاعَةُ بَغْتَةً﴾؟","answer":"تجعل مجيء الساعة أو العذاب غاية لاستمرارهم في المرية؛ فيتمادون في شكهم حتى يعاينوا الأمر الذي كانوا يجادلون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص62، تحت عنوان «معنى ﴿حتى﴾ وموقعها في الجملة الكريمة»","url":""}]},{"id":"s22-91","number":91,"surah":22,"verses":[55],"references":[{"surah":22,"verses":[55]}],"verseLabel":"الحج: 55","question":"أيّ يوم أُريد بقوله ﴿عَذَابُ يَوْمٍ عَقِيمٍ﴾؟","answer":"ذُكر أنه يوم بدر، وقيل يوم القيامة. وتميل الموسوعة إلى إرادة القيامة؛ لأنه يوم لا يعقبه يوم آخر، ولأنه لا يأتي المعذَّبين فيه بخير أو فرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص63–64، تحت عنوان «نكتة وصف لفظ ﴿يوم﴾ بالعقيم»","url":""}]},{"id":"s22-92","number":92,"surah":22,"verses":[55],"references":[{"surah":22,"verses":[55]}],"verseLabel":"الحج: 55","question":"كيف وُصف اليوم بأنه ﴿عَقِيمٍ﴾؟","answer":"شُبّه اليوم الذي لا ينتج للمعذَّبين خيرًا بالمرأة التي لا تلد؛ فالعقم يصوّر انقطاع الخير والراحة عنهم وشدة العذاب، لا عقمًا حقيقيًا لليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص64، تحت عنوان «بلاغة الاستعارة في لفظ ﴿يوم عقيم﴾»","url":""}]},{"id":"s22-63","number":63,"surah":22,"verses":[58],"references":[{"surah":22,"verses":[58]}],"verseLabel":"الحج: 58","question":"ما دلالة ﴿أَوْ﴾ في وعد المهاجرين الذين ﴿قُتِلُوا أَوْ مَاتُوا﴾ بالرزق الحسن؟","answer":"تجمع الحالين في أصل الوعد: من قُتل من المهاجرين ومن مات دون قتل، لاشتراكهم في الهجرة والقصد الصادق. فلا يختص حسن الوعد بمن وقع عليه القتل، ولا تدل الآية بمجرد ذلك على تساوي جميع درجات الأجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص96، تحت عنوان «معنى ﴿أو﴾ في ﴿أو ماتوا﴾»","url":""}]},{"id":"s22-64","number":64,"surah":22,"verses":[59],"references":[{"surah":22,"verses":[59]}],"verseLabel":"الحج: 59","question":"لماذا جاء ﴿مُدْخَلًا﴾ نكرة في قوله ﴿لَيُدْخِلَنَّهُمْ مُدْخَلًا يَرْضَوْنَهُ﴾؟","answer":"جاء التنكير للتفخيم والتعظيم في سياق الامتنان؛ فهو مدخل عظيم يليق بكرم الله، يفوق ما تبلغه تصورات البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص102، تحت عنوان «نكتة تنكير ﴿مدخلًا﴾»","url":""}]},{"id":"s22-86","number":86,"surah":22,"verses":[59],"references":[{"surah":22,"verses":[59]}],"verseLabel":"الحج: 59","question":"لماذا وُصف المدخل بأنه ﴿يَرْضَوْنَهُ﴾ بدل أن يوصف بالحسن كما وُصف الرزق؟","answer":"لأن رضاهم عنه يدل على اشتماله على ما يسرهم ويحقق تمام كرامتهم؛ فالتعبير بالرضا يجمع الحسن وزيادة، ويبلغ في وصف الإكرام ما لا يبلغه وصف المدخل بالحسن وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص103، تحت عنوان «نكتة ترك وصف المدخل بالحسن، كما وصف الرزق»","url":""}]},{"id":"s22-87","number":87,"surah":22,"verses":[59],"references":[{"surah":22,"verses":[59]}],"verseLabel":"الحج: 59","question":"ما دلالة المضارع في قوله ﴿مُدْخَلًا يَرْضَوْنَهُ﴾؟","answer":"يصور المضارع استمرار رضاهم بالنعيم وتجدد سرورهم به؛ فنعيمهم مستمر، وتفكّههم بخيره متجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص103، تحت عنوان «دلالة التعبير بالفعل المضارع ﴿يرضونه﴾»","url":""}]},{"id":"s22-65","number":65,"surah":22,"verses":[60],"references":[{"surah":22,"verses":[60]}],"verseLabel":"الحج: 60","question":"ما دلالة التذييل بـ﴿إِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ﴾ بعد ذكر المعاقبة بالمثل؟","answer":"يوجه التذييل النفس إلى العفو والمغفرة مع ذكر حق المقابلة بالمثل؛ فلا تتحول الرخصة في الانتصار إلى استرسال في الانتقام. وفي استحضار عفو الله وغفرانه ترغيب في الصفح وضبط ما يثور في النفس عند طلب حقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص123، تحت عنوان «نكتة التذييل بـ﴿لعفو غفور﴾»","url":""}]},{"id":"s22-66","number":66,"surah":22,"verses":[61],"references":[{"surah":22,"verses":[61]},{"surah":31,"verses":[29]},{"surah":57,"verses":[6]}],"verseLabel":"الحج: 61؛ لقمان: 29؛ الحديد: 6","question":"ما مناسبة تصوير إيلاج الليل والنهار لاستمرار نصرة المؤمنين في سياق الحج؟","answer":"جعل تعاقب الليل والنهار وإيلاج أحدهما في الآخر سنة كونية متجددة يشاهدها الناس؛ وفي السياق تشبيه ضمني لاستمرار نصرة الله للمؤمنين بهذه السنة المطردة، مع تصوير إحكام القدرة والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص133، تحت عنوان «بلاغة الاستعارة ﴿يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ﴾»","url":""}]},{"id":"s22-67","number":67,"surah":22,"verses":[63],"references":[{"surah":22,"verses":[63]}],"verseLabel":"الحج: 63","question":"لماذا انتقل التعبير من الماضي ﴿أَنْزَلَ﴾ إلى المضارع ﴿فَتُصْبِحُ﴾ في وصف اخضرار الأرض؟","answer":"يستحضر المضارع صورة اخضرار الأرض كأنها تُرى أمام السامع، ويشير إلى استمرار أثر المطر وتجدد نفعه؛ فقد مضى الإنزال وبقي أثره في حياة الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص170–171، تحت عنوان «نكتة التعبير عن مصير الأرض بالفعل المضارع ﴿فتصبح﴾»","url":""}]},{"id":"s22-88","number":88,"surah":22,"verses":[63],"references":[{"surah":22,"verses":[63]}],"verseLabel":"الحج: 63","question":"ما دلالة وصف الأرض بـ﴿مُخْضَرَّةً﴾ بعد نزول الماء؟","answer":"يبرز الوصف جمال الأرض وحياتها بعد اليبس؛ فالخضرة ممتعة للنظر ودالة على النبات النامي. وجاء «مخضرة» اسم فاعل ليدل على ثبوت هذا الوصف ولزومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص173، تحت عنوان «نكتة التعبير بـ﴿مخضرة﴾ مادة وصيغة»","url":""}]},{"id":"s22-68","number":68,"surah":22,"verses":[65],"references":[{"surah":22,"verses":[65]}],"verseLabel":"الحج: 65","question":"ما دلالة فعل الإمساك وصيغته في ﴿وَيُمْسِكُ السَّمَاءَ أَنْ تَقَعَ عَلَى الْأَرْضِ﴾؟","answer":"الإمساك يتضمن الحفظ والمنع؛ فيصور حفظ السماء ومنع وقوعها على الأرض بقدرة الله. وجاء بالمضارع ليدل على استمرار هذا الحفظ وتجدد تعلقه، لا على حدث انقضى وانتهى أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص205، تحت عنوان «دلالة التعبير بفعل الإمساك مادة وصيغة»","url":""}]},{"id":"s22-69","number":69,"surah":22,"verses":[66],"references":[{"surah":22,"verses":[66]}],"verseLabel":"الحج: 66","question":"لماذا جاءت ﴿إِنَّ الْإِنْسَانَ لَكَفُورٌ﴾ دون عطف على ما قبلها؟","answer":"جاءت استئنافًا يصوّر جحود الإنسان بعد ذكر نعم الله؛ فقطعها عما قبلها يلفت السامع إلى شناعة الكفران ويوقظه لشكر المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص225، تحت عنوان «نكتة الفصل في: ﴿إن الإنسان لكفور﴾»","url":""}]},{"id":"s22-93","number":93,"surah":22,"verses":[66],"references":[{"surah":22,"verses":[66]}],"verseLabel":"الحج: 66","question":"ما مناسبة ختم تعداد نعم الإحياء والإماتة والإحياء بقوله ﴿إِنَّ الْإِنْسَانَ لَكَفُورٌ﴾؟","answer":"يجمع الختام مقصد تعداد النعم: أن المنعم بها مستحق للشكر والعبادة وحده. وفي وصف الإنسان بالكفور توبيخ لمن يتقلب في هذه النعم ثم يجحد خالقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص225، تحت عنوان «فائدة تذييل الآية بوصف ﴿الإنسان﴾ بأنه ﴿لكفور﴾»","url":""}]},{"id":"s22-70","number":70,"surah":22,"verses":[67],"references":[{"surah":22,"verses":[67]}],"verseLabel":"الحج: 67","question":"ما دلالة النهي في ﴿فَلَا يُنَازِعُنَّكَ فِي الْأَمْرِ﴾؟","answer":"ذكر المبحث أن ظاهره نهي المعارضين عن المنازعة، وفيه إرشاد للنبي ﷺ ألا يلتفت إلى مرائهم أو يمكنهم من إشغاله عن الدعوة. فالحجة قد اتضحت، وليس المقصود الدخول في جدل لا يريد أصحابه معرفة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص239–240، تحت عنوان «دلالة النهي في قوله: ﴿فلا ينازعنك﴾»","url":""}]},{"id":"s22-71","number":71,"surah":22,"verses":[68,69],"references":[{"surah":22,"verses":[68,69]}],"verseLabel":"الحج: 68-69","question":"كيف يكون قوله ﴿اللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ﴾ جوابًا للمجادلين؟","answer":"هو كناية عن قطع الجدال مع المعاند وتفويض أمره إلى الله؛ فالجدل ينفع من يطلب الحق، أما من يصر على الضلال فيُردّ أمره إلى علم الله وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص253، تحت عنوان «بلاغة الكناية في قوله تعالى: ﴿الله أعلم﴾»","url":""}]},{"id":"s22-94","number":94,"surah":22,"verses":[68,69],"references":[{"surah":22,"verses":[68,69]}],"verseLabel":"الحج: 68-69","question":"ما الوعيد الذي يتضمنه قوله ﴿اللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ﴾؟","answer":"يتضمن تحذيرًا بأن أعمالهم الظاهرة والباطنة معلومة لله، وأنه سيتولى حسابهم وجزاءهم؛ فأُدرج الوعيد في صيغة تصلح لمخاطبة من يظهر طلب الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص253–254، تحت عنوان «نكتة الإدماج في قوله تعالى: ﴿الله أعلم﴾»","url":""}]},{"id":"s22-95","number":95,"surah":22,"verses":[68,69],"references":[{"surah":22,"verses":[68,69]}],"verseLabel":"الحج: 68-69","question":"لماذا أعقب الرد على المجادلين بقوله ﴿اللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ الْقِيَامَةِ﴾؟","answer":"جاء الكلام استئنافًا يثبّت الرسول والمؤمنين ويهدد المجادلين؛ فترك مجادلتهم لا يضيع الحق، إذ يتولى الله الفصل بينهم يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص256، تحت عنوان «نكتة الفصل في قوله تعالى: ﴿الله يحكم﴾»","url":""}]},{"id":"s22-72","number":72,"surah":22,"verses":[70],"references":[{"surah":22,"verses":[70]}],"verseLabel":"الحج: 70","question":"لماذا ذُكر الكتاب بعد تقرير علم الله بكل ما في السماء والأرض؟","answer":"خوطب الناس بما يعرفونه من حفظ الأمور في الكتب وإثباتها؛ فالكتاب يجعل الحجة في الحساب ظاهرة، مع أن علم الله لا يحتاج إلى ما يعين عليه أو يمنع عنه النسيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص276، تحت عنوان «فائدة ذكر الكتاب بعد ذكر تمام العلم»","url":""}]},{"id":"s22-96","number":96,"surah":22,"verses":[70],"references":[{"surah":22,"verses":[70]}],"verseLabel":"الحج: 70","question":"ما الذي يصوّره قوله ﴿إِنَّ ذَلِكَ فِي كِتَابٍ﴾ عن حفظ الأعمال؟","answer":"هو كناية عن الضبط وعدم النسيان أو الخلط؛ فأعمال العباد محفوظة مسجلة، يطمئن المحسن إلى أن أجره لا يضيع، ويحذر المسيء من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص277، تحت عنوان «بلاغة الكناية في: ﴿إن ذلك في كتاب﴾»","url":""}]},{"id":"s22-73","number":73,"surah":22,"verses":[71],"references":[{"surah":22,"verses":[71]}],"verseLabel":"الحج: 71","question":"ما دلالة عطف ﴿وَمَا لَيْسَ لَهُمْ بِهِ عِلْمٌ﴾ على نفي السلطان المنزل؟","answer":"ينفي الأول الحجة السمعية المنزلة من عند الله، ثم ينفي الثاني الحجة العقلية أيضًا؛ لأن انتفاء الدليل السمعي وحده لا يستلزم انتفاء الدليل العقلي. فاجتمع النفيان لإبطال كل مستند لعبادتهم، وقدم السمعي لأنه الأصل في باب العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص288، تحت عنوان «فائدة العطف في: ﴿وما ليس لهم به علم﴾»","url":""}]},{"id":"s22-74","number":74,"surah":22,"verses":[72],"references":[{"surah":22,"verses":[72]}],"verseLabel":"الحج: 72","question":"ما الذي تفيده ﴿يَكَادُونَ﴾ في قوله ﴿يَكَادُونَ يَسْطُونَ بِالَّذِينَ يَتْلُونَ عَلَيْهِمْ آيَاتِنَا﴾؟","answer":"تفيد مقاربة وقوع السطو من شدة الغيظ عند سماع الآيات. ووصف حالهم بالمقاربة لا ينفي وقوع الاعتداء من بعضهم، ولا يعني أنه وقع من جميعهم مع كل تلاوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص304، تحت عنوان «دلالة التعبير بـ﴿يكادون﴾ مادة وصيغة»","url":""}]},{"id":"s22-89","number":89,"surah":22,"verses":[72],"references":[{"surah":22,"verses":[72]}],"verseLabel":"الحج: 72","question":"لماذا عبّر عن اعتداء الكافرين بلفظ ﴿يَسْطُونَ﴾؟","answer":"لما في السطو من معنى البطش والقهر والعلو؛ فاللفظ يصور شدة غضبهم من سماع القرآن، حتى يقاربوا الوثوب على من يتلوه والبطش به.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص304–305، تحت عنوان «دلالة التعبير بـ﴿يسطون﴾ مادة وصيغة»","url":""}]},{"id":"s22-75","number":75,"surah":22,"verses":[73],"references":[{"surah":22,"verses":[73]}],"verseLabel":"الحج: 73","question":"لماذا اختير الذباب مثالًا في بيان عجز المعبودات؟","answer":"لأنه من أضعف المخلوقات المشاهدة؛ فعجز تلك المعبودات عن خلقه ولو اجتمعت يبالغ في إظهار ضعفها، وينقض استحقاقها للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص327، تحت عنوان «بلاغة التمثيل بالذباب»","url":""}]},{"id":"s22-97","number":97,"surah":22,"verses":[73],"references":[{"surah":22,"verses":[73]}],"verseLabel":"الحج: 73","question":"لماذا أُضيف عجز المعبودات عن استنقاذ ما يسلبه الذباب إلى عجزها عن خلقه؟","answer":"للتدرج إلى حجة أوضح: فقد يستعظم المعترض شأن الخلق، لكن المعبودات عاجزة حتى عن استرداد شيء أخذه الذباب؛ فإذا عجزت عن الأهون كان عجزها عن الأعظم أظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص329، تحت عنوان «معنى العطف وبلاغته»","url":""}]},{"id":"s22-98","number":98,"surah":22,"verses":[73],"references":[{"surah":22,"verses":[73]}],"verseLabel":"الحج: 73","question":"لماذا خُتم مثل الذباب بقوله ﴿ضَعُفَ الطَّالِبُ وَالْمَطْلُوبُ﴾؟","answer":"لبيان أن المقصود إظهار ضعف الطرفين، لا إثبات قوة للذباب تستحق التعظيم؛ فالجملة تؤكد المثل وتمنع هذا الفهم الخاطئ، وإن كانت الأصنام أشد عجزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص333، تحت عنوان «علة الفصل وبلاغته»","url":""}]},{"id":"s22-76","number":76,"surah":22,"verses":[74],"references":[{"surah":22,"verses":[74]}],"verseLabel":"الحج: 74","question":"ما صلة قوله ﴿مَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ﴾ بمثل الذباب قبله؟","answer":"جاء نتيجة للمثل وتأكيدًا لمعناه؛ فمن ساوى بالخالق معبودات عاجزة عن أضعف الأشياء لم يعظّم الله حق تعظيمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص339، تحت عنوان «علة الفصل وبلاغته»","url":""}]},{"id":"s22-99","number":99,"surah":22,"verses":[74],"references":[{"surah":22,"verses":[74]}],"verseLabel":"الحج: 74","question":"ما الذي تضيفه ﴿حَقَّ قَدْرِهِ﴾ إلى قوله ﴿مَا قَدَرُوا اللَّهَ﴾؟","answer":"تؤكد نفي التعظيم اللائق بالله؛ فقد جعلوا الأصنام شريكة له في العبادة، فلم يعرفوا له قدره الحق. فالتعبير يؤكد موضع التقصير في تعظيمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص341، تحت عنوان «غرض التعبير بالمفعول المطلق»","url":""}]},{"id":"s22-77","number":77,"surah":22,"verses":[75],"references":[{"surah":22,"verses":[75]}],"verseLabel":"الحج: 75","question":"لماذا قُدّم اسم الله في قوله ﴿اللَّهُ يَصْطَفِي مِنَ الْمَلَائِكَةِ رُسُلًا وَمِنَ النَّاسِ﴾؟","answer":"لإبراز اختصاص الله باصطفاء الرسل؛ فهو الذي يختارهم، ولا يملك المعترضون أن يختاروا له أو يقترحوا من تلقاء أنفسهم من يستحق الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص345، تحت عنوان «غرض الابتداء بالمسند إليه»","url":""}]},{"id":"s22-100","number":100,"surah":22,"verses":[75],"references":[{"surah":22,"verses":[75]}],"verseLabel":"الحج: 75","question":"ما الذي يضيفه لفظ ﴿يَصْطَفِي﴾ إلى معنى اختيار الرسل؟","answer":"الاصطفاء اختيار فيه تنقية وتهيئة؛ فالله يختار رسله صافين من الشوائب، ويهيئهم لتلقي الرسالة وأدائها، لا اختيارًا مجردًا عن التأهيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص345، تحت عنوان «نكتة إيثار مفردة الاصطفاء»","url":""}]},{"id":"s22-101","number":101,"surah":22,"verses":[75],"references":[{"surah":22,"verses":[75]}],"verseLabel":"الحج: 75","question":"ما دلالة ﴿مِنَ﴾ في قوله ﴿مِنَ الْمَلَائِكَةِ رُسُلًا﴾؟","answer":"تدل على التبعيض؛ فالمراد اختيار بعض الملائكة للرسالة، لا أن جميع الملائكة رسل إلى البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص346، تحت عنوان «نوع حرف ﴿من﴾ ودلالته»","url":""}]},{"id":"s22-78","number":78,"surah":22,"verses":[77],"references":[{"surah":22,"verses":[77]}],"verseLabel":"الحج: 77","question":"ما دلالة ترتيب ﴿ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمْ وَافْعَلُوا الْخَيْرَ﴾؟","answer":"بدأ بالصلاة ممثلة في الركوع والسجود، ثم عمم العبادة لتشمل سائر الطاعات، ثم عمم فعل الخير. فهو تدرج من الأخص إلى الأعم، ومن الخير اللازم إلى الخير المتعدي إلى الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص365، تحت عنوان «بلاغة ترتيب الأوامر»","url":""}]},{"id":"s22-79","number":79,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"ما دلالة ﴿فِي اللَّهِ﴾ في قوله ﴿وَجَاهِدُوا فِي اللَّهِ﴾؟","answer":"المعنى أن يكون الجهد لأجل الله وابتغاء مرضاته. وفي التعبير بـ«في» تصوير لإحاطة الإخلاص بهذا الجهد، حتى يكون كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص374، تحت عنوان «معنى حرف الجر ودلالته»","url":""}]},{"id":"s22-102","number":102,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"ما الذي تضيفه ﴿حَقَّ جِهَادِهِ﴾ إلى الأمر بالجهاد؟","answer":"تؤكد أداءه خالصًا مستوفيًا ما يجب فيه بقدر الوسع والطاقة، بعيدًا عن الرياء والنقص؛ فليس المراد مجرد بذل جهد مع فساد القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص375، تحت عنوان «بلاغة المركب الإضافي ﴿حق جهاده﴾»","url":""}]},{"id":"s22-80","number":80,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"لماذا جاء قوله ﴿هُوَ اجْتَبَاكُمْ﴾ بعد أوامر العبادة والطاعة؟","answer":"جاء تعليلًا لها؛ فاختيار الله لهم نعمة تدعوهم إلى شكره بطاعته. لذلك اتصل المعنى بما قبله من غير حاجة إلى حرف عطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص376، تحت عنوان «توجيه فصل جملة ﴿هو اجتباكم﴾»","url":""}]},{"id":"s22-103","number":103,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"ما المراد بـ﴿الدِّينِ﴾ في قوله ﴿وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ﴾؟","answer":"التعريف للعهد، والمراد دين الإسلام؛ فتصف الآية هذا الدين باليسر ورفع الحرج، لا بتكليف يقصد به التضييق على أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص379، تحت عنوان «معنى تعريف لفظ ﴿الدين﴾»","url":""}]},{"id":"s22-104","number":104,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"ما الذي تضيفه ﴿مِنْ﴾ في قوله ﴿مِنْ حَرَجٍ﴾؟","answer":"تؤكد عموم النفي وتبالغ فيه، كأن المعنى: ما جعل عليكم أدنى حرج. فليست حشوًا، بل تقوّي بيان التيسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص379، تحت عنوان «فائدة حرف ﴿من﴾»","url":""}]},{"id":"s22-81","number":81,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"ما وجه التشريف في قوله ﴿هُوَ سَمَّاكُمُ الْمُسْلِمِينَ﴾؟","answer":"إسناد التسمية إلى ضمير المخاطبين يُظهر تكريمهم واجتباءهم والاختصاص بالفضل؛ وهي نعمة تستدعي شكر الله بالعبادة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص383، تحت عنوان «دلالة إضافة الفعل إلى الضمير»","url":""}]},{"id":"s22-105","number":105,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"لماذا قيل ﴿مِنْ قَبْلُ﴾ في تسمية الأمة بالمسلمين؟","answer":"لبيان أن هذه التسمية ثابتة قبل نزول القرآن، في الكتب المتقدمة؛ فليست اسمًا مستحدثًا عند نزول الآية، وفي ذلك تنويه بذكر الأمة من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص384، تحت عنوان «فائدة ذكر شبه الجملة»","url":""}]},{"id":"s22-106","number":106,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"لماذا أُشير إلى القرآن بـ﴿هَذَا﴾ في قوله ﴿مِنْ قَبْلُ وَفِي هَذَا﴾؟","answer":"لأن القرآن حاضر بين أيديهم معلوم لهم، فاسم الإشارة القريب يستحضره في الذهن، ويشعر بقربه من المسلم ووضوح ما فيه من هذه التسمية.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص385، تحت عنوان «براعة الإشارة بالقرب»","url":""}]},{"id":"s22-82","number":82,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"ما دلالة صيغة المدح في قوله ﴿فَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ﴾؟","answer":"هي إنشاء ثناء على الله بأنه أحسن مولى وأحسن نصير؛ فتبرز كمال ولايته ونصرته بصيغة صريحة في المدح.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص395، تحت عنوان «بلاغة صيغة المدح»","url":""}]},{"id":"s22-107","number":107,"surah":22,"verses":[78],"references":[{"surah":22,"verses":[78]}],"verseLabel":"الحج: 78","question":"كيف يتصل ختام سورة الحج بـ﴿نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ﴾ بمطلعها؟","answer":"بدأت السورة بالأمر بالتقوى، وخُتمت بما يثبت قلوب المؤمنين ويدعوهم إلى الاعتصام بالله؛ فالتقوى والطاعة تثمران حسن ولايته ونصره، وبذلك يلتقي الختام بالمطلع.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص396، تحت عنوان «براعة ختام السورة بجملة آخر آية»","url":""}]},{"id":"s22-137","number":137,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما دلالة زيادة ﴿مِنْ﴾ في قوله: ﴿مِنْ بَعْدِ عِلْمٍ﴾، وحذفها في نظيرتها من سورة النحل: ﴿بَعْدَ عِلْمٍ﴾؟","answer":"تفيد ﴿مِنْ﴾ ابتداء الغاية، فتُصوّر بدء التحول من العلم إلى عدمه واتصاله به من غير فاصل معتبر. وجاء هذا التفصيل في سورة الحج موافقًا لتفصيل أطوار الخلق قبل العبارة، بينما جاء التعبير في النحل على الإجمال، فناسبه حذف ﴿مِنْ﴾.","sources":[{"label":"فاضل السامرائي، لمسات بيانية، ج1، ص840، مبحث «﴿من بعد علم﴾ و﴿بعد علم﴾».","url":""}]},{"id":"s22-138","number":138,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما سر إفراد ﴿طِفْلًا﴾ مع أن الخطاب لجماعة في قوله: ﴿ثُمَّ نُخْرِجُكُمْ طِفْلًا﴾؟","answer":"بُني الكلام على خلق جنس الإنسان لا على تعداد أفراده؛ فجاءت مراحل الخلق مفردة: نطفة، ثم علقة، ثم مضغة، فناسبها ﴿طِفْلًا﴾ الدالة على الجنس. أما حيث يكون الحكم متعلقًا بالأفراد وأحوال كل واحد منهم، فيأتي الجمع مثل ﴿وَإِذَا بَلَغَ الْأَطْفَالُ مِنْكُمُ الْحُلُمَ﴾.","sources":[{"label":"فاضل السامرائي، «ما سر مجيء كلمة طفل مفردة؟»، عنوان فرعي: «خلق الجنس لا خلق الأفراد».","url":""}]},{"id":"s22-139","number":139,"surah":22,"verses":[17],"references":[{"surah":22,"verses":[17]}],"verseLabel":"الحج: 17","question":"ما سر اختيار ﴿يَفْصِلُ بَيْنَهُمْ﴾ بدل التعبير بالحكم بينهم؟","answer":"الفصل أبلغ هنا من مجرد الحكم؛ لأن المذكورين طوائف متباينة المصائر، والفصل يقتضي تمييز بعضها من بعض وإبعاد فريق عن فريق. أما الحكم فقد يقع بين أفراد ملة واحدة مع بقائهم في جهة واحدة؛ فاختير ﴿يفصل﴾ لمشهد القيامة الذي تنتهي فيه الطوائف إلى مصائر متباعدة.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين الحكم والفصل في القرآن الكريم؟»، عنوان فرعي: «﴿إن الله يفصل بينهم يوم القيامة﴾».","url":""}]},{"id":"s22-140","number":140,"surah":22,"verses":[19,20],"references":[{"surah":22,"verses":[19,20]}],"verseLabel":"الحج: 19، 20","question":"ما دلالة دخول ﴿مِنْ﴾ في قوله: ﴿يُصَبُّ مِنْ فَوْقِ رُءُوسِهِمُ الْحَمِيمُ﴾؟","answer":"﴿مِنْ﴾ تفيد ابتداء الغاية، فجعلت ابتداء الصب من النقطة الملاصقة لفوق رؤوسهم، وكأن الحميم يباشرهم بلا فاصل. أما لفظ ﴿فوق﴾ وحده فيحتمل القرب والبعد؛ ولذلك زادت ﴿مِنْ﴾ صورة العذاب شدة ومباشرة، ووافقت ما بعده من صهر البطون والجلود.","sources":[{"label":"فاضل السامرائي، «الفرق بين ﴿يصب من فوق رؤوسهم﴾ و﴿صبوا فوق رأسه﴾»، عنوان فرعي: «من لابتداء الغاية وزيادة العذاب».","url":""}]},{"id":"s22-141","number":141,"surah":22,"verses":[24],"references":[{"surah":22,"verses":[24]}],"verseLabel":"الحج: 24","question":"ما سر بناء الفعل للمجهول في ﴿وَهُدُوا إِلَى الطَّيِّبِ مِنَ الْقَوْلِ﴾، بدل ﴿اهتدوا﴾ أو التصريح بالفاعل؟","answer":"السياق في دخول الجنة؛ فهم يُدخلون ويُحلَّون ثم يُرشَدون إلى مواطن يسمعون فيها القول الطيب وإلى طريق الجنة. لذلك عبّر بـ﴿هُدُوا﴾ ليدل على أن الهداية واقعة عليهم من خارجهم، تتولاها الملائكة بأمر الله، لا على مجرد اهتداء نشأ من أنفسهم كما يفيده ﴿اهتدوا﴾.","sources":[{"label":"فاضل السامرائي، «لِمَ قال ﴿هُدوا﴾ ولم يقل اهتدوا أو هداهم الله؟»، عنوان فرعي: «الهداية إلى منازل الجنة».","url":""}]},{"id":"s22-142","number":142,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما دلالة قوله لإبراهيم: ﴿يَأْتُوكَ﴾، لا التعبير بالإتيان إلى البيت؟","answer":"الخطاب موجَّه إلى إبراهيم عليه السلام: ﴿وَأَذِّنْ فِي النَّاسِ بِالْحَجِّ يَأْتُوكَ﴾، فناسب ضمير الخطاب لحظة التكليف الأولى. والتعبير يربط استجابة الحجيج عبر الأجيال بنداء إبراهيم نفسه، فيجعل وفودهم كأنه جواب متجدد لذلك النداء القديم.","sources":[{"label":"فاضل السامرائي، «﴿يأتوك رجالًا وعلى كل ضامر﴾»، عنوان فرعي: «الخطاب لإبراهيم: يأتوك لا يأتوه».","url":""}]},{"id":"s22-143","number":143,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما سر الاقتصار على المشاة والضوامر في قوله: ﴿يَأْتُوكَ رِجَالًا وَعَلَى كُلِّ ضَامِرٍ﴾؟","answer":"الآية تحكي وسائل المجيء المعهودة زمن خطاب إبراهيم عليه السلام، فكان الناس يأتون مشاة أو ركبانًا على الإبل. وليست الآية تعدادًا استباقيًا لكل وسيلة ستظهر، بل تصوير لاستجابة المخاطَبين الأولين بما عرفوه؛ ولذلك جاء التعبير صادقًا على مقامه من غير تكلّف لإقحام وسائل الأزمنة اللاحقة.","sources":[{"label":"فاضل السامرائي، «لماذا لم تُذكر وسائل النقل الأخرى؟»، عنوان فرعي: «مراعاة زمن خطاب إبراهيم».","url":""}]},{"id":"s22-144","number":144,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما سر وصف الراحلة بـ﴿ضَامِرٍ﴾ في مشهد الوفود إلى الحج؟","answer":"الضامر هو الذي هزل من طول السفر ومشقته، فاختارت الآية الصفة التي تحمل أثر الطريق على جسد الراحلة. ولم تقل مجرد بعير أو راحلة؛ لأن المقام يريد أن يُري القارئ بُعد الشقة وقوة الشوق اللذين أنهكا المركوب حتى بلغ البيت.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص130، مبحث «ضامر وفج عميق».","url":""}]},{"id":"s22-145","number":145,"surah":22,"verses":[46],"references":[{"surah":22,"verses":[46]}],"verseLabel":"الحج: 46","question":"ما سر تقييد القلوب بقوله: ﴿الْقُلُوبُ الَّتِي فِي الصُّدُورِ﴾ مع أن موضع القلب معلوم؟","answer":"ليس المقصود مجرد المعرفة الذهنية؛ فالإنسان قد يفهم الحجة ثم لا يتحرك بموجبها. القلب هنا مناط اليقظة والدافع إلى العمل بما عُقل، ولذلك نُصّ على القلوب التي في الصدور لإبراز أن العمى الحقيقي أصاب مركز الاستجابة الداخلية، لا أبصار الوجوه التي ترى الآثار ولا تعتبر.","sources":[{"label":"فاضل السامرائي، «﴿ولكن تعمى القلوب التي في الصدور﴾: بين القلب والعقل»، عنوان فرعي: «العقل يدرك والقلب يدفع إلى العمل».","url":""}]},{"id":"s22-146","number":146,"surah":22,"verses":[46],"references":[{"surah":22,"verses":[46]}],"verseLabel":"الحج: 46","question":"ما سر مجيء ﴿أَفَلَمْ يَسِيرُوا﴾ بالفاء، في حين يأتي في مواضع أخرى ﴿أَوَلَمْ يَسِيرُوا﴾ بالواو؟","answer":"الفاء تدل هنا على أن ما قبلها يفضي إلى ما بعدها؛ فقد ذُكرت القرى الهالكة والبئر المعطلة والقصر المشيد، فكان ذلك سببًا مباشرًا يدعوهم إلى السير والاعتبار، فقيل ﴿أفلم﴾. أما الواو فتجيء حين يكون ما قبلها خبرًا مجموعًا إلى ما بعده من غير هذه السببية المباشرة.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية 182: الفرق بين أولم يسيروا وأفلم يسيروا»، عنوان فرعي: «الفاء للسببية ومناسبة ما قبلها لما بعدها».","url":""}]},{"id":"s22-147","number":147,"surah":22,"verses":[72],"references":[{"surah":22,"verses":[72]}],"verseLabel":"الحج: 72","question":"ما سر اختيار الهمزة في ﴿قُلْ أَفَأُنَبِّئُكُمْ بِشَرٍّ مِنْ ذَلِكُمُ﴾، واختيار ﴿هَلْ﴾ في نظيرتها من سورة المائدة؟","answer":"﴿هل﴾ أقوى في الاستفهام وأشد توكيدًا من الهمزة، بدليل اختصاصها بمصاحبة ﴿مِنْ﴾ الاستغراقية في نحو ﴿هل من خالق﴾. وسياق المائدة أشد؛ فقد وصف اتخاذ الدين والصلاة هزوًا ولعبًا، والفسق، واللعن والمسخ وعبادة الطاغوت، فناسبه الاستفهام الأقوى. أما سياق الحج فذكر أنهم يكادون يسطون ولم يقع منهم الفعل، فناسبته الهمزة.","sources":[{"label":"فاضل السامرائي، «الفرق بين ﴿هل أنبئكم بشر من ذلك﴾ و﴿أفأنبئكم بشر من ذلكم﴾»، عنوان فرعي: «هل أقوى من الهمزة ومناسبة كل منهما لسياقها».","url":""}]},{"id":"s22-148","number":148,"surah":22,"verses":[73],"references":[{"surah":22,"verses":[73]}],"verseLabel":"الحج: 73","question":"ما دلالة اختيار ﴿لَا يَسْتَنْقِذُوهُ مِنْهُ﴾ بدل قول أقصر مثل: لا يأخذوه منه؟","answer":"الاستنقاذ ليس مجرد الأخذ، بل تخليص الشيء ممن استولى عليه بقوة؛ وصيغة الاستفعال توحي بمحاولة وبذل جهد. فجاءت الكلمة لتبلغ غاية التهكم بعجز المعبودات: لا تخلق ذبابًا ولو اجتمعت، بل إذا سلبها الذباب شيئًا حاولت استرداده فلم تستطع؛ فصار الضعف واقعًا في الخلق والدفع والاسترجاع جميعًا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص66، مبحث «دلالة يستنقذوه في سورة الحج».","url":""}]},{"id":"s22-149","number":149,"surah":22,"verses":[77,78],"references":[{"surah":22,"verses":[77,78]}],"verseLabel":"الحج: 77، 78","question":"ما سر أن تختم سورة الحج بقوله: ﴿لَعَلَّكُمْ تُفْلِحُونَ﴾ وبالصلاة والزكاة، ثم تفتتح السورة التالية بـ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾؟","answer":"ختمت سورة الحج بأسباب الفلاح: الركوع والسجود والعبادة وفعل الخير، ثم أكدت إقامة الصلاة وإيتاء الزكاة. وجاء مطلع المؤمنون جوابًا محققًا لذلك الرجاء: ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾، ثم أعاد الصلاة والزكاة ضمن صفاتهم؛ فكأن خاتمة الحج تضع طريق الفلاح، ومطلع المؤمنون يعلن تحقق الفلاح لمن سلكه.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص2، مبحث «التناسب بين خاتمة سورة الحج ومفتتح سورة المؤمنون».","url":""}]},{"id":"s22-150","number":150,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما سر وصل ﴿كَيْ﴾ بـ﴿لَا﴾ في رسم ﴿لِكَيْلَا يَعْلَمَ مِنْ بَعْدِ عِلْمٍ﴾، وفصلهما في سورة النحل: ﴿لِكَيْ لَا يَعْلَمَ بَعْدَ عِلْمٍ﴾؟","answer":"وافق اتصال الرسم اتصال المعنى؛ فوجود ﴿مِنْ﴾ في آية الحج أفاد ابتداء التحول مباشرة من العلم، فجاء ﴿لِكَيْلَا﴾ موصولًا. أما آية النحل فليس فيها ﴿مِنْ﴾ الدالة على ابتداء الغاية، فجاء الرسم بالفصل ﴿لِكَيْ لَا﴾؛ فصار رسم الكلمتين ظلًّا للفرق الدلالي بين السياقين.","sources":[{"label":"فاضل السامرائي، «ما سر وصل لكيلا في الحج وفصل لكي لا في النحل؟»، عنوان فرعي: «اتصال الرسم لاتصال المعنى».","url":""}]},{"id":"s22-151","number":151,"surah":22,"verses":[18],"references":[{"surah":22,"verses":[18]}],"verseLabel":"الحج: 18","question":"ما سر التعبير بـ﴿مَنْ﴾ في قوله: ﴿يَسْجُدُ لَهُ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ﴾، ثم عطف الشمس والقمر والجبال والشجر؟","answer":"الأصل في ﴿مَنْ﴾ أن تستعمل للعاقل، والسياق هنا يبرز السجود والخضوع، وهما مما يناسب إسناده إلى من يعقل. ثم عُطفت الموجودات غير العاقلة لتدخل في موكب السجود الكوني تبعًا، فجمع النظم بين تشريف العقلاء في صدر المشهد واستيعاب المخلوقات كلها بعد ذلك.","sources":[{"label":"فاضل السامرائي، «الفرق بين استعمال مَن وما في آيات السجود»، عنوان فرعي: «﴿يسجد له من في السماوات ومن في الأرض﴾».","url":""}]},{"id":"s22-152","number":152,"surah":22,"verses":[19,22],"references":[{"surah":22,"verses":[19,22]}],"verseLabel":"الحج: 19، 22","question":"ما سر أن جاء تصوير العذاب في سورة الحج أشد من نظيره في قوله في الدخان: ﴿ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ﴾؟","answer":"سياق الحج أوسع في تفصيل العذاب: ثياب من نار، وحميم يصهر البطون والجلود، ومقامع من حديد، وإعادة إلى النار كلما أرادوا الخروج. أما سياق الدخان فمحوره طعام الأثيم ولم يذكر أثر الحميم بهذا التفصيل؛ لذلك ناسب الأشدَّ في الحج التعبيرُ الأشد ﴿مِنْ فَوْقِ رُءُوسِهِمْ﴾.","sources":[{"label":"فاضل السامرائي، «الفرق بين عذاب الحميم في الحج والدخان»، عنوان فرعي: «مناسبة زيادة المبنى لزيادة شدة السياق».","url":""}]},{"id":"s22-153","number":153,"surah":22,"verses":[30],"references":[{"surah":22,"verses":[30]}],"verseLabel":"الحج: 30","question":"ما دلالة ﴿مِنْ﴾ في قوله: ﴿فَاجْتَنِبُوا الرِّجْسَ مِنَ الْأَوْثَانِ﴾؟","answer":"تحتمل ﴿مِنْ﴾ البيان، فتكون الأوثان بيانًا لجنس الرجس المقصود، مثل قولك: اجتنبوا الخواتم من الذهب. وتحتمل ابتداء الغاية، فتجعل عبادة الأوثان منشأ الرجس ومبدأه؛ فهي تجمع الشرور والفساد. وكلا الوجهين يزيد التحذير قوة: فهي رجس في ذاتها ومنبع لغيره.","sources":[{"label":"فاضل السامرائي، «﴿فاجتنبوا الرجس من الأوثان﴾: معنى مِن»، عنوان فرعي: «البيانية وابتداء الغاية».","url":""}]},{"id":"s22-154","number":154,"surah":22,"verses":[31],"references":[{"surah":22,"verses":[31]}],"verseLabel":"الحج: 31","question":"ما سر إفراد ﴿الرِّيحُ﴾ في تصوير مصير المشرك: ﴿أَوْ تَهْوِي بِهِ الرِّيحُ فِي مَكَانٍ سَحِيقٍ﴾؟","answer":"يغلب في الاستعمال القرآني مجيء الريح المفردة في سياق الشدة والشر، بينما تأتي ﴿الرياح﴾ مجموعة في مواطن الرحمة والبشارة غالبًا. فناسب الإفراد هنا صورة القوة الواحدة العاصفة التي تستولي على الساقط وتقذفه بعيدًا؛ وهو مشهد يناسب ضياع المشرك وانقطاعه عن أسباب النجاة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص14، مبحث «الريح والرياح في الاستعمال القرآني».","url":""}]},{"id":"s22-155","number":155,"surah":22,"verses":[64],"references":[{"surah":22,"verses":[64]}],"verseLabel":"الحج: 64","question":"ما دلالة زيادة اللام في قوله: ﴿وَإِنَّ اللَّهَ لَهُوَ الْغَنِيُّ الْحَمِيدُ﴾؟","answer":"اجتمع في الآية أكثر من مؤكد: ﴿إنَّ﴾، واللام، وضمير الفصل ﴿هو﴾، وتعريف الوصفين ﴿الغني الحميد﴾. وجاء هذا التوكيد الأبلغ بعد التصريح بملكه ما في السماوات وما في الأرض، ليثبت أن غناه ذاتي مطلق، وأن ملك الخلق جميعًا لا يزيده غنى ولا يفتقر معه إلى أحد.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص14، مبحث «غني حميد، هو الغني الحميد، لهو الغني الحميد».","url":""}]},{"id":"s23-1","number":1,"surah":23,"verses":[1],"references":[{"surah":23,"verses":[1]}],"verseLabel":"المؤمنون: 1","question":"ما مناسبة افتتاح سورة المؤمنون بالبشارة ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾؟","answer":"الفلاح غاية يسعى إليها العامل؛ فافتتاح السورة به يبشر المؤمنين بخير الدنيا والآخرة، ويجمع مقصدها قبل تفصيل الصفات التي يستحقون بها هذا الفلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص419، تحت عنوان «براعة الاستهلال في السورة الكريمة»","url":""}]},{"id":"s23-100","number":100,"surah":23,"verses":[1],"references":[{"surah":23,"verses":[1]}],"verseLabel":"المؤمنون: 1","question":"لماذا قيل ﴿قَدْ أَفْلَحَ﴾ بصيغة الماضي؟","answer":"تؤكد «قد» الخبر وتقرّب الماضي من الحال؛ فيُعرض فلاح المؤمنين في صورة الأمر الثابت المحقق، وفي ذلك تقوية للبشارة وتشويق إلى صفاتهم والاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص419–420، تحت عنوان «معنى ﴿قد﴾ ونكتة دخولها على الفعل الماضي»","url":""}]},{"id":"s23-2","number":2,"surah":23,"verses":[2],"references":[{"surah":23,"verses":[2]}],"verseLabel":"المؤمنون: 2","question":"ما سرّ بدء صفات المؤمنين بالخشوع في الصلاة؟","answer":"الخشوع روح الصلاة، وبه تقوى مراقبة الله في القلب فتثمر امتثال أمره واجتناب نهيه. فبدء الصفات به مناسب لبناء الصفات العملية التالية على أصل قلبي يمدها ويقويها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص458–459، تحت عنوان «بلاغة الترتيب بين صفات المؤمنين المذكورة»","url":""}]},{"id":"s23-3","number":3,"surah":23,"verses":[2],"references":[{"surah":23,"verses":[2]}],"verseLabel":"المؤمنون: 2","question":"لماذا وُصف المؤمنون بالخشوع في جملة اسمية: ﴿هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ﴾؟","answer":"لتدل على ثبات الخشوع وملازمته لهم في الصلاة؛ فهو وصف مستقر ناشئ عن تعلق قلوبهم بالله، لا حالة عارضة تزول سريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص422، تحت عنوان «نكتة التعبير في الخشوع بالجملة الاسمية»","url":""}]},{"id":"s23-101","number":101,"surah":23,"verses":[2],"references":[{"surah":23,"verses":[2]}],"verseLabel":"المؤمنون: 2","question":"ما الذي يصوّره حرف ﴿فِي﴾ في قوله ﴿فِي صَلَاتِهِمْ خَاشِعُونَ﴾؟","answer":"يصوّر استغراقهم في الصلاة، كأنهم انغمسوا فيها وصارت محيطة بهم؛ فيقوّي معنى التعلق بها والخشوع فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص422، تحت عنوان «فائدة التعبير بالظرفية ﴿في﴾»","url":""}]},{"id":"s23-102","number":102,"surah":23,"verses":[2],"references":[{"surah":23,"verses":[2]}],"verseLabel":"المؤمنون: 2","question":"لماذا قُدّم ﴿فِي صَلَاتِهِمْ﴾ على ﴿خَاشِعُونَ﴾؟","answer":"للاهتمام بشأن الصلاة وإبراز قوة تعلقهم بها، مع ملاءمة الفاصلة. فالمقدَّم هو موضع العناية في هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص422–423، تحت عنوان «فائدة تقديم شبه الجملة ﴿في صلاتهم﴾»","url":""}]},{"id":"s23-4","number":4,"surah":23,"verses":[3],"references":[{"surah":23,"verses":[3]}],"verseLabel":"المؤمنون: 3","question":"ما سرّ وصف المؤمنين بالإعراض عن اللغو لا بمجرد تركه؟","answer":"الإعراض أبلغ من الترك؛ فهو تباعد عن اللغو مباشرة وتسببًا وميلًا وحضورًا. واسم الفاعل يصور هذا الاجتناب وصفًا مستمرًا لهم، حتى يصير الانصراف عنه سجية لا موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص426، تحت عنوان «نكتة التعبير بالإعراض مادة وصيغة»","url":""}]},{"id":"s23-5","number":5,"surah":23,"verses":[4],"references":[{"surah":23,"verses":[4]}],"verseLabel":"المؤمنون: 4","question":"كيف يُفهم وصف المؤمنين بأنهم ﴿لِلزَّكَاةِ فَاعِلُونَ﴾ مع أن الزكاة مال يُخرج؟","answer":"الزكاة تطلق على المال المخرج وعلى فعل المزكّي الذي هو التزكية؛ وباعتبار هذا الفعل صح التعبير بـ«فاعلون»، كما يقال لفاعل الضرب: ضارب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص429–430، تحت عنوان «نكتة التعبير بالفعل مادة وصيغة»","url":""}]},{"id":"s23-103","number":103,"surah":23,"verses":[4],"references":[{"surah":23,"verses":[4]}],"verseLabel":"المؤمنون: 4","question":"ما مزية لفظ ﴿فَاعِلُونَ﴾ في الزكاة على مجرد الإيتاء أو الأداء؟","answer":"يشمل الفعل إيصال الزكاة إلى مستحقيها، وفي مادته معنى إسداء المعروف؛ فناسب سياق مدح المؤمنين والثناء على إحسانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص430، تحت عنوان «نكتة التعبير عن الزكاة بالفعل دون الإيتاء أو الأداء»","url":""}]},{"id":"s23-6","number":6,"surah":23,"verses":[5,6,7],"references":[{"surah":23,"verses":[5,6,7]}],"verseLabel":"المؤمنون: 5-7","question":"ما الذي يضيفه التعبير بـ﴿حَافِظُونَ﴾ في وصف المؤمنين بأنهم ﴿لِفُرُوجِهِمْ حَافِظُونَ﴾؟","answer":"يدل الحفظ على صيانة الفروج عن الحرام والتعفف، وضبط الشهوة والتقيد بالحلال؛ فهو يصور عناية المؤمن بحماية عفته وصونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص434–435، تحت عنوان «غرض التعبير عن الفروج بالحفظ»","url":""}]},{"id":"s23-98","number":98,"surah":23,"verses":[5,6,7],"references":[{"surah":23,"verses":[5,6,7]}],"verseLabel":"المؤمنون: 5-7","question":"لماذا قيل ﴿هُمْ لِفُرُوجِهِمْ حَافِظُونَ﴾ بالجملة الاسمية، ولم يُكتفَ بقول «حفظوا فروجهم»؟","answer":"لأن الجملة الاسمية تفيد ثبات هذا الوصف وملازمته لهم؛ فحفظ الفروج صفة مستقرة في حياتهم، لا فعلًا وقع منهم ثم انقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص432، تحت عنوان «فائدة التعبير بالجملة الاسمية ﴿هم لفروجهم حافظون﴾»","url":""}]},{"id":"s23-99","number":99,"surah":23,"verses":[5,6,7],"references":[{"surah":23,"verses":[5,6,7]}],"verseLabel":"المؤمنون: 5-7","question":"كيف يجتمع حفظ الفروج مع الاستثناء في قوله ﴿إِلَّا عَلَى أَزْوَاجِهِمْ﴾؟","answer":"الاستثناء يبيّن حدود الحفظ: فهم يصونون فروجهم عما حُرّم عليهم، ولا يدخل في المنع ما أحله الله لهم مما ذكرته الآية؛ فالعفة التزام بحدود الحلال والحرام، وليست امتناعًا مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص435، تحت عنوان «معنى الاستثناء في قوله: ﴿إلا على أزواجهم﴾»","url":""}]},{"id":"s23-7","number":7,"surah":23,"verses":[8],"references":[{"surah":23,"verses":[8]}],"verseLabel":"المؤمنون: 8","question":"لماذا ذُكر العهد بعد الأمانات مع أنه من جملتها؟","answer":"الأمانات تشمل حقوق الله وحقوق العباد، والعهد فرد عظيم منها؛ فخُص بالذكر بعد العام لإبراز أهميته والتنبيه إلى وجوب الوفاء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص453، تحت عنوان «غرض تقديم الأمانات على العهود»","url":""}]},{"id":"s23-104","number":104,"surah":23,"verses":[8],"references":[{"surah":23,"verses":[8]}],"verseLabel":"المؤمنون: 8","question":"لماذا جُمعت ﴿أَمَانَاتِهِمْ﴾ وأُفرد ﴿عَهْدِهِمْ﴾؟","answer":"يناسب جمع الأمانات تنوع أنواعها وتعدد ما يؤتمن عليه الإنسان، أما العهد فذُكر مفردًا بوصفه فردًا مهمًا من هذه الأمانات خُص بمزيد عناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص453، تحت عنوان «فائدة جمع الأمانات وإفراد العهود»","url":""}]},{"id":"s23-8","number":8,"surah":23,"verses":[9],"references":[{"surah":23,"verses":[9]}],"verseLabel":"المؤمنون: 9","question":"لماذا فُصل بين الخشوع في الصلاة والمحافظة عليها بصفات أخرى؟","answer":"لبيان أنهما فضيلتان مستقلتان: الخشوع روح الصلاة، والمحافظة تعاهد أدائها. ولو قُرنا مباشرة لتُوهم أنهما وصف واحد، مع أن المحافظة لا تُغني عن الخشوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص458، تحت عنوان «نكتة الفصل بين الخشوع والمحافظة على الصلاة»","url":""}]},{"id":"s23-105","number":105,"surah":23,"verses":[9],"references":[{"surah":23,"verses":[9]}],"verseLabel":"المؤمنون: 9","question":"لماذا بدأت صفات المؤمنين بالصلاة وخُتمت بها؟","answer":"تعظيمًا لشأنها؛ فالخشوع فيها أصل تنبني عليه سائر الصفات، والعودة إلى الصلاة في الختام تؤكد مكانتها وتحفز إلى رعاية جميع تلك الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص459، تحت عنوان «بلاغة الترتيب بين صفات المؤمنين المذكورة»","url":""}]},{"id":"s23-106","number":106,"surah":23,"verses":[9],"references":[{"surah":23,"verses":[9]}],"verseLabel":"المؤمنون: 9","question":"ما الذي تضيفه صيغة ﴿يُحَافِظُونَ﴾ إلى مجرد أداء الصلاة؟","answer":"تصوّر التنبّه لها وتعاهدها حتى لا تضيع أو يُغفل عنها؛ والمضارع يدل على دوام هذه العناية وتجددها، لا أداء يقع مرة ثم يُترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص457، تحت عنوان «نكتة التعبير بـ﴿يحافظون﴾ مادة وصيغة»","url":""}]},{"id":"s23-9","number":9,"surah":23,"verses":[10,11],"references":[{"surah":23,"verses":[10,11]}],"verseLabel":"المؤمنون: 10-11","question":"كيف فسّرت الموسوعة وصف المؤمنين بأنهم ﴿الْوَارِثُونَ﴾؟","answer":"ذكرت أنهم أحق بهذا الجزاء، وقيل إنهم يرثون منازل من فوّت على نفسه الإيمان وما يؤهله لها. والوصف يقرر تحقق هذه الوراثة وثباتها لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص461، تحت عنوان «دلالة التعبير بـ﴿الوارثون﴾ مادة وصيغة»","url":""}]},{"id":"s23-107","number":107,"surah":23,"verses":[10,11],"references":[{"surah":23,"verses":[10,11]}],"verseLabel":"المؤمنون: 10-11","question":"لماذا صُوّر استحقاق الفردوس بالإرث؟","answer":"استُعير الإرث للاستحقاق الثابت؛ لأنه من أقوى أسباب الملك، فيؤكد التعبير تمكن المؤمنين من هذا الجزاء واستقرار حقهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص461، تحت عنوان «بلاغة الاستعارة في التعبير عن الاستحقاق بالإرث»","url":""}]},{"id":"s23-108","number":108,"surah":23,"verses":[10,11],"references":[{"surah":23,"verses":[10,11]}],"verseLabel":"المؤمنون: 10-11","question":"لماذا أعيد فعل الإرث في ﴿الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ﴾ بعد ﴿الْوَارِثُونَ﴾؟","answer":"لبيان الموروث بعد إجماله وتشويق السامع إليه، وتعظيم هذه الوراثة وتأكيدها. وجاء المضارع ليصوّر استمرارها وتجدد نعيم أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص462، تحت عنوان «نكتة التعبير بالفعل المضارع ﴿يرثون﴾ وإعادة ذكره»","url":""}]},{"id":"s23-10","number":10,"surah":23,"verses":[12],"references":[{"surah":23,"verses":[12]}],"verseLabel":"المؤمنون: 12","question":"هل المراد بـ﴿الْإِنْسَانَ﴾ في ﴿خَلَقْنَا الْإِنْسَانَ مِنْ سُلَالَةٍ مِنْ طِينٍ﴾ فرد واحد؟","answer":"المراد جنس الإنسان: بدأ خلقه بآدم، ثم جاء نسله من السلالة البشرية؛ فالتعريف يجمع الجنس ويرده إلى أصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص472، تحت عنوان «معنى (أل) في الإنسان»","url":""}]},{"id":"s23-109","number":109,"surah":23,"verses":[12],"references":[{"surah":23,"verses":[12]}],"verseLabel":"المؤمنون: 12","question":"ما دلالة ﴿مِنْ سُلَالَةٍ﴾ في بيان أصل خلق الإنسان؟","answer":"تفيد «من» ابتداء الخلق من السلالة، وهي خلاصة تُستخرج من شيء؛ فالتعبير يرد ابتداء الخلق إلى خلاصة الطين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص472، تحت عنوان «معنى ﴿من﴾ في قوله: ﴿من سلالة﴾»","url":""}]},{"id":"s23-110","number":110,"surah":23,"verses":[12],"references":[{"surah":23,"verses":[12]}],"verseLabel":"المؤمنون: 12","question":"ما الذي تبينه ﴿مِنْ طِينٍ﴾ بعد ﴿مِنْ سُلَالَةٍ﴾؟","answer":"تبيّن أصل السلالة وصلتها بالطين. وتذكر الموسوعة أن «من» تحتمل ابتداء الغاية، أو التبعيض، أو البيان؛ فيلتقي ذلك في بيان أن هذه السلالة من طين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص473، تحت عنوان «معنى ﴿من﴾ في قوله: ﴿من طين﴾»","url":""}]},{"id":"s23-11","number":11,"surah":23,"verses":[13],"references":[{"surah":23,"verses":[13]}],"verseLabel":"المؤمنون: 13","question":"ما الذي يصوّره حرف ﴿فِي﴾ في قوله ﴿فِي قَرَارٍ مَكِينٍ﴾؟","answer":"يصوّر ثبوت النطفة واستقرارها في موضع يحويها ويحفظها؛ فالقرار مكان الاستقرار، والمكين يدل على الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص475، تحت عنوان «دلالة التعبير بالظرفية ﴿في﴾»","url":""}]},{"id":"s23-111","number":111,"surah":23,"verses":[13],"references":[{"surah":23,"verses":[13]}],"verseLabel":"المؤمنون: 13","question":"لماذا وُصف موضع النطفة بأنه ﴿قَرَارٍ مَكِينٍ﴾؟","answer":"أُطلق القرار على المكان الذي تستقر فيه النطفة، ووُصف بالتمكن المتعلق بما يحل فيه؛ فزاد هذا التصوير معنى الحفظ والثبات قوة، وهو من المجاز العقلي بحسب المبحث.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص475، تحت عنوان «بلاغة المجاز في قوله: ﴿قرار﴾»","url":""}]},{"id":"s23-12","number":12,"surah":23,"verses":[14],"references":[{"surah":23,"verses":[14]}],"verseLabel":"المؤمنون: 14","question":"لماذا تكرر فعل الخلق عند وصف انتقال الجنين من طور إلى طور؟","answer":"لإبراز أن كل تحول إنشاء بقدرة الله وأمره؛ فكأن كل مرحلة خلق مستقل جدير بالتأمل، لا انتقال يحصل خارج تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص478، تحت عنوان «معنى الخلق هنا»","url":""}]},{"id":"s23-112","number":112,"surah":23,"verses":[14],"references":[{"surah":23,"verses":[14]}],"verseLabel":"المؤمنون: 14","question":"لماذا استُعملت الفاء بين بعض أطوار الجنين بدل ﴿ثُمَّ﴾؟","answer":"لتفريع الطور اللاحق على السابق وبيان تعقبه له وتقاربهما بحسب المقام؛ ولا يلزم من ذلك أن كل طور لا يستغرق مدة في نموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص477، تحت عنوان «نكتة العدول عن العطف بـ﴿ثم﴾ إلى الفاء في المراحل الباقية»","url":""}]},{"id":"s23-13","number":13,"surah":23,"verses":[14],"references":[{"surah":23,"verses":[14]}],"verseLabel":"المؤمنون: 14","question":"ما دلالة ﴿ثُمَّ﴾ في قوله ﴿ثُمَّ أَنْشَأْنَاهُ خَلْقًا آخَرَ﴾؟","answer":"تفيد التراخي المناسب لتعاقب أطوار الخلق؛ فالانتقال إلى هذا الخلق جاء بعد مراحل تتفاوت مددها بحسب الحكمة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص483، تحت عنوان «معنى ﴿ثم﴾ في قوله: ﴿ثم أنشأناه خلقًا آخر﴾»","url":""}]},{"id":"s23-113","number":113,"surah":23,"verses":[14],"references":[{"surah":23,"verses":[14]}],"verseLabel":"المؤمنون: 14","question":"ما الذي يضيفه ﴿أَنْشَأْنَاهُ﴾ إلى وصف تكوّن الإنسان؟","answer":"الإنشاء ابتداء الشيء وإحداثه وتربيته؛ ويفسر المبحث هذا الموضع بنفخ الروح وما يتبعه من الارتقاء في خصائص الإنسان، فناسب لفظ الإنشاء هذا التحول.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص483–484، تحت عنوان «دلالة التعبير بـ﴿أنشأناه﴾ مادة وصيغة»","url":""}]},{"id":"s23-114","number":114,"surah":23,"verses":[14],"references":[{"surah":23,"verses":[14]}],"verseLabel":"المؤمنون: 14","question":"لماذا وُصف هذا الخلق بأنه ﴿آخَرَ﴾؟","answer":"لإبراز مباينته لما سبقه؛ فقد صار ذا حياة وسمع وبصر ونطق وخصائص لم تكن له في أطواره السابقة. فـ«آخر» لا تعني مجرد مرحلة مماثلة لما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص484، تحت عنوان «دلالة وصف الخلق بـ﴿آخر﴾»","url":""}]},{"id":"s23-14","number":14,"surah":23,"verses":[14],"references":[{"surah":23,"verses":[14]}],"verseLabel":"المؤمنون: 14","question":"ما دلالة الفاء في قوله ﴿فَتَبَارَكَ اللَّهُ﴾ بعد ذكر أطوار الخلق؟","answer":"تربط الثناء بما سبق؛ فتفاصيل الخلق تقود إلى تعظيم الخالق، وكأن المعنى: إذا كان الله هو الذي أبدع هذا الخلق فتبارك الله أحسن الخالقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص484–485، تحت عنوان «معنى الفاء في قوله: ﴿فتبارك﴾»","url":""}]},{"id":"s23-115","number":115,"surah":23,"verses":[14],"references":[{"surah":23,"verses":[14]}],"verseLabel":"المؤمنون: 14","question":"ما الذي يراد بوصف الله بـ﴿أَحْسَنُ الْخَالِقِينَ﴾؟","answer":"يبين بلوغ خلقه أعلى درجات الحسن والكمال، بما لا يضاهيه حسن؛ فالغرض تعظيم بديع صنعه، لا مجرد مفاضلة محدودة بين مصنوعات.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص487، تحت عنوان «دلالة التعبير بـ﴿أحسن﴾، وخروجها عن الظاهر»","url":""}]},{"id":"s23-15","number":15,"surah":23,"verses":[15,16],"references":[{"surah":23,"verses":[15,16]}],"verseLabel":"المؤمنون: 15-16","question":"لماذا قيل ﴿ثُمَّ إِنَّكُمْ بَعْدَ ذَلِكَ لَمَيِّتُونَ﴾ بـ﴿ثُمَّ﴾؟","answer":"لأن الموت يأتي بعد أطوار الخلق والحياة وأجلها؛ فتناسب «ثم» هذا التراخي، ويأتي التذكير بالموت تمهيدًا لذكر البعث بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص494، تحت عنوان «معنى ﴿ثم﴾ وإيثارها دون الفاء»","url":""}]},{"id":"s23-116","number":116,"surah":23,"verses":[15,16],"references":[{"surah":23,"verses":[15,16]}],"verseLabel":"المؤمنون: 15-16","question":"لماذا أُكد الموت مع أن المخاطبين لا ينكرونه؟","answer":"لأن إعراضهم عن الاستعداد لما بعد الحياة جعل حالهم كحال من ينكر الموت؛ فجاء التوكيد ليوقظهم من الاغترار بالدنيا والتغافل عن نهايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص495، تحت عنوان «غرض تتابع المؤكدات»","url":""}]},{"id":"s23-117","number":117,"surah":23,"verses":[15,16],"references":[{"surah":23,"verses":[15,16]}],"verseLabel":"المؤمنون: 15-16","question":"ما دلالة ﴿ثُمَّ﴾ في قوله ﴿ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ تُبْعَثُونَ﴾؟","answer":"تفيد تراخي البعث عن الموت وحياة البرزخ؛ فبين الموت والبعث مدة يعلمها الله، وليسا حدثين متصلين بلا فاصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص496، تحت عنوان «معنى ﴿ثم﴾ في قوله: ﴿ثم إنكم﴾»","url":""}]},{"id":"s23-118","number":118,"surah":23,"verses":[15,16],"references":[{"surah":23,"verses":[15,16]}],"verseLabel":"المؤمنون: 15-16","question":"لماذا أُكد خبر البعث بـ﴿إِنَّ﴾ والجملة الاسمية؟","answer":"ردًا على إنكار المخاطبين للبعث، وتقريرًا أنهم لم يُخلقوا عبثًا؛ فالذي أبدع الخلق قادر على إعادته، ولذلك عُرض الخبر مؤكدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص496–497، تحت عنوان «غرض تتابع المؤكدات بـ(إنّ) والجملة الاسمية»","url":""}]},{"id":"s23-16","number":16,"surah":23,"verses":[17],"references":[{"surah":23,"verses":[17]}],"verseLabel":"المؤمنون: 17","question":"ما دلالة وصف السماوات بـ﴿سَبْعَ طَرَائِقَ﴾؟","answer":"ذكر المبحث أنها سماوات طباق، بعضها فوق بعض، وذكر وجهًا آخر يتصل بطرائق سير الكواكب. فالتعبير يدعو إلى تأمل الخلق العلوي واتخاذه دليلًا على القدرة، ولا يقتصر على مجرد ذكر العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص499–500، تحت عنوان «دلالة التعبير بـ﴿طرائق﴾ مادة وصيغة»","url":""}]},{"id":"s23-17","number":17,"surah":23,"verses":[18],"references":[{"surah":23,"verses":[18]}],"verseLabel":"المؤمنون: 18","question":"ما سرّ التعبير عن حفظ الماء بـ﴿فَأَسْكَنَّاهُ فِي الْأَرْضِ﴾؟","answer":"استعير الإسكان لإقرار الماء في الأرض، فشبه حفظه فيها بالسكن والاستقرار. ويشمل ذلك بقاءه القريب الذي تنتفع به النباتات، وتسربه إلى داخل الأرض ثم ظهوره في العيون والآبار؛ فتمام النعمة ليس في إنزاله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص514، تحت عنوان «بلاغة الاستعارة في قوله: ﴿فأسكناه﴾»","url":""}]},{"id":"s23-18","number":18,"surah":23,"verses":[18],"references":[{"surah":23,"verses":[18]}],"verseLabel":"المؤمنون: 18","question":"لماذا أعقب إسكان الماء في الأرض بقوله ﴿وَإِنَّا عَلَى ذَهَابٍ بِهِ لَقَادِرُونَ﴾؟","answer":"ليبين أن إبقاءه نعمة مع القدرة على سلبه؛ فالذي أنزله وأسكنه قادر على إزالته أو تغيير حاله بما يذهب نفعه. فلا ينبغي أن يُغفل عن المنعم لبقاء الماء قريبًا متاحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص515، تحت عنوان «دلالة إعراب جملة ﴿وإنا﴾ و﴿لقادرون﴾»","url":""}]},{"id":"s23-119","number":119,"surah":23,"verses":[18],"references":[{"surah":23,"verses":[18]}],"verseLabel":"المؤمنون: 18","question":"لماذا توالت المؤكدات في ﴿وَإِنَّا عَلَى ذَهَابٍ بِهِ لَقَادِرُونَ﴾؟","answer":"لتقوية التحذير من سلب النعمة واستدعاء شكرها؛ فجاءت الجملة الاسمية و«إن» واللام وسائر وسائل التوكيد مناسبة لعظم القدرة على إعدام الماء بعد إنزاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص515–516، تحت عنوان «علة توالي المؤكدات في السياق»","url":""}]},{"id":"s23-120","number":120,"surah":23,"verses":[18],"references":[{"surah":23,"verses":[18]}],"verseLabel":"المؤمنون: 18","question":"لماذا جاء لفظ ﴿ذَهَابٍ﴾ نكرة؟","answer":"لتعظيم شأن الذهاب وعدم حصره في طريق واحد؛ فقد يقع بما يزيل الماء أو يفسده أو يمنع الوصول إليه. فالتنكير يوسّع التصور ويقوّي التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص516–517، تحت عنوان «نكتة تنكير لفظ ﴿ذهاب﴾ في السياق»","url":""}]},{"id":"s23-19","number":19,"surah":23,"verses":[19],"references":[{"surah":23,"verses":[19]}],"verseLabel":"المؤمنون: 19","question":"ما علة وصف ﴿فَوَاكِهُ﴾ بالكثرة في قوله: ﴿لَكُمْ فِيهَا فَوَاكِهُ كَثِيرَةٌ﴾؟","answer":"يبرز الوصف وفرة الثمار وتعدد أنواعها وتجددها في الجنات، فيجمع متعة التنوع وكثرة النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص525–526، تحت عنوان «علة وصف الفواكه بالكثرة»","url":""}]},{"id":"s23-137","number":137,"surah":23,"verses":[19],"references":[{"surah":23,"verses":[19]}],"verseLabel":"المؤمنون: 19","question":"ما دلالة قوله: ﴿وَمِنْهَا تَأْكُلُونَ﴾ بعد ذكر الفواكه؟","answer":"يفيد التقديم والجار أن بعض ثمار الجنات للأكل والاقتيات، مع بقاء منافع أخرى فيها؛ فجمع السياق التفكه والمنفعة الغذائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص526، تحت عنوان «دلالة إعراب جملة ﴿وَمِنْهَا تَأْكُلُونَ﴾»","url":""}]},{"id":"s23-138","number":138,"surah":23,"verses":[19],"references":[{"surah":23,"verses":[19]}],"verseLabel":"المؤمنون: 19","question":"ما دلالة وصف ﴿فَاكِهَةٌ﴾ بأنها ﴿كَثِيرَةٌ﴾ في الزخرف؟","answer":"لا يراد فرد واحد؛ بل جنس كثير الأنواع والأفراد متجدد اللذات، يناسب نعيم الجنة الذي يقصد به التلذذ لا دفع الجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص263، تحت عنوان «دلالة وصف ﴿فَاكِهَةٌ﴾ بأنها ﴿كَثِيرَةٌ﴾»","url":""}]},{"id":"s23-20","number":20,"surah":23,"verses":[20],"references":[{"surah":23,"verses":[20]}],"verseLabel":"المؤمنون: 20","question":"لماذا خُصّت شجرة الزيتون بالذكر بين الأشجار؟","answer":"لما تتميز به من كثرة المنافع؛ فثمرتها وزيتها مما ينتفع الناس به، فإفرادها بالذكر يزيد إظهار النعمة والامتنان.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص528، تحت عنوان «سر التخصيص لشجرة الزيتون»","url":""}]},{"id":"s23-121","number":121,"surah":23,"verses":[20],"references":[{"surah":23,"verses":[20]}],"verseLabel":"المؤمنون: 20","question":"لماذا نُسبت شجرة الزيتون إلى طور سيناء مع وجودها في غيره؟","answer":"ذُكرت لذلك وجوه، منها منشؤها أو كثرتها فيه، ومنها تعظيمها بذكر موضع مبارك كلّم الله فيه موسى. وتستحسن الموسوعة هذا الوجه الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص528–529، تحت عنوان «علة نسبة شجرة الزيتون إلى طور سيناء»","url":""}]},{"id":"s23-122","number":122,"surah":23,"verses":[20],"references":[{"surah":23,"verses":[20]}],"verseLabel":"المؤمنون: 20","question":"لماذا عُطف ﴿صِبْغٍ لِلْآكِلِينَ﴾ على ﴿الدُّهْنِ﴾؟","answer":"لإبراز تعدد وجوه الانتفاع بثمرة الزيتون وزيتها؛ فتؤكل الثمرة ويُنتفع بزيتها، ويؤتدم به الطعام. وهذا التفصيل يزيد الامتنان بالنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص532، تحت عنوان «فائدة عطف الصبغ على الدهن»","url":""}]},{"id":"s23-123","number":123,"surah":23,"verses":[20],"references":[{"surah":23,"verses":[20]}],"verseLabel":"المؤمنون: 20","question":"لماذا سُمّي ما يؤتدم به من الزيت ﴿صِبْغًا﴾؟","answer":"لأن الخبز إذا غُمس في الزيت تلوّن به؛ فشُبّه الزيت بما يُصبغ به واستعير له اسم الصبغ، تصويرًا لطريقة الانتفاع به في الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص532، تحت عنوان «بلاغة الاستعارة في لفظ الصبغ»","url":""}]},{"id":"s23-21","number":21,"surah":23,"verses":[21],"references":[{"surah":23,"verses":[21]}],"verseLabel":"المؤمنون: 21","question":"لماذا جاء ﴿نُسْقِيكُمْ﴾ بالمضارع في الحديث عن ألبان الأنعام؟","answer":"لاستحضار صورة الإسقاء كأنها تُشاهد، وللدلالة على استمرار هذه النعمة وتجددها؛ فالناس لا يزالون ينتفعون بما في بطون الأنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص542، تحت عنوان «دلالة التعبير بالمضارع ﴿نسقيكم﴾»","url":""}]},{"id":"s23-124","number":124,"surah":23,"verses":[21],"references":[{"surah":23,"verses":[21]}],"verseLabel":"المؤمنون: 21","question":"لماذا أُسند الإسقاء إلى ضمير العظمة في ﴿نُسْقِيكُمْ﴾؟","answer":"تعظيمًا لشأن النعمة ودلالتها على القدرة؛ فالله يخرج من بطون الأنعام لبنًا خالصًا سائغًا ينتفع به الناس، فيلفت الإسناد إلى المنعم بهذا الإسقاء العجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص542، تحت عنوان «نكتة إسناد الإسقاء إلى ضمير العظمة»","url":""}]},{"id":"s23-22","number":22,"surah":23,"verses":[22],"references":[{"surah":23,"verses":[22]}],"verseLabel":"المؤمنون: 22","question":"لماذا جُمع بين الأنعام والفلك في قوله ﴿وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ﴾؟","answer":"استكمالًا للامتنان؛ فبعد وسيلة الحمل في البر ذُكرت وسيلته في البحر، واجتمعت الوسيلتان في منفعة حمل الناس ومتاعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص551، تحت عنوان «معنى الواو في قوله تعالى: ﴿وعلى الفلك﴾»","url":""}]},{"id":"s23-125","number":125,"surah":23,"verses":[22],"references":[{"surah":23,"verses":[22]}],"verseLabel":"المؤمنون: 22","question":"لماذا قُدّم الحمل على الأنعام على الحمل في الفلك؟","answer":"لأن الانتفاع بالأنعام في الحمل أغلب وأكثر، ولأن الحديث قبل ذلك في منافعها؛ فناسب تقديمها حسن ترتيب الكلام واتصاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص552، تحت عنوان «نكتة تقديم الأنعام على الفلك في الحمل»","url":""}]},{"id":"s23-23","number":23,"surah":23,"verses":[23],"references":[{"surah":23,"verses":[23]}],"verseLabel":"المؤمنون: 23","question":"لماذا جاء ﴿مَا لَكُمْ مِنْ إِلَهٍ غَيْرُهُ﴾ بعد الأمر بعبادة الله دون عطف؟","answer":"لأنه يعلّل الأمر ويجيب عما قد يسأل عنه السامع: لِمَ نعبده وحده؟ فالجواب أنه لا إله لهم غيره، فلا يستحق العبادة سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص560، تحت عنوان «نكتة الفصل بين أجزاء الآية الكريمة»","url":""}]},{"id":"s23-126","number":126,"surah":23,"verses":[23],"references":[{"surah":23,"verses":[23]}],"verseLabel":"المؤمنون: 23","question":"ما الذي تضيفه ﴿مِنْ﴾ في قوله ﴿مَا لَكُمْ مِنْ إِلَهٍ غَيْرُهُ﴾؟","answer":"تؤكد استغراق النفي؛ فلا يخرج عن هذا النفي شيء يُدّعى له وصف الألوهية غير الله. وبذلك يقوى تقرير إفراده بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص561، تحت عنوان «علة الإتيان بـ﴿من﴾ في ﴿من إله﴾»","url":""}]},{"id":"s23-127","number":127,"surah":23,"verses":[23],"references":[{"surah":23,"verses":[23]}],"verseLabel":"المؤمنون: 23","question":"ما الغرض من الاستفهام في قوله ﴿أَفَلَا تَتَّقُونَ﴾؟","answer":"هو إنكار وتوبيخ على الإعراض مع وضوح دلائل التوحيد، ويتضمن تحذيرًا من العقوبة ودعوة إلى اتقاء الله بإفراده بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص562، تحت عنوان «بلاغة الاستفهام في قوله: ﴿أفلا تتقون﴾»","url":""}]},{"id":"s23-24","number":24,"surah":23,"verses":[24,33],"references":[{"surah":23,"verses":[24,33]}],"verseLabel":"المؤمنون: 24، 33","question":"لماذا قُدّم ﴿الَّذِينَ كَفَرُوا﴾ على ﴿مِنْ قَوْمِهِ﴾ في وصف ملأ قوم نوح في الآية ٢٤؟","answer":"لأن تقديم وصف الكفر أبلغ في التسلية ببيان سبب تكذيبهم. وصلة الموصول هنا قصيرة، فلا ينشأ من تقديمها لبس أو ضعف في ترتيب الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص566، تحت عنوان «علة التقديم والتأخير بين الصفات»","url":""}]},{"id":"s23-128","number":128,"surah":23,"verses":[24,33],"references":[{"surah":23,"verses":[24,33]}],"verseLabel":"المؤمنون: 24، 33","question":"لماذا قُدّم ﴿مِنْ قَوْمِهِ﴾ على ﴿الَّذِينَ كَفَرُوا﴾ في الآية ٣٣ من المؤمنون؟","answer":"لأن الصلة طالت بما عُطف عليها؛ فلو أُخر «من قومه» لطال الفصل أو تُوهم تعلقه بـ«الدنيا». وجاء تقديمه أيضًا للعناية بكون المعارضين من قوم الرسول العارفين بحاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص634، تحت عنوان «دلالة تقديم الجار والمجرور في السياق»","url":""}]},{"id":"s23-25","number":25,"surah":23,"verses":[24],"references":[{"surah":23,"verses":[24]}],"verseLabel":"المؤمنون: 24","question":"ما الذي أراده الملأ بقولهم عن نوح ﴿بَشَرٌ مِثْلُكُمْ﴾؟","answer":"أرادوا تكذيب دعواه الرسالة؛ إذ أوهموا أن مساواته لهم في البشرية تمنع اختياره رسولًا، فجعلوا الوصف بالبشرية وسيلة إلى نفي الرسالة عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص567، تحت عنوان «بلاغة الكناية في الوصف بالبشرية»","url":""}]},{"id":"s23-129","number":129,"surah":23,"verses":[24],"references":[{"surah":23,"verses":[24]}],"verseLabel":"المؤمنون: 24","question":"ما الذي أراده الملأ بقولهم ﴿يُرِيدُ أَنْ يَتَفَضَّلَ عَلَيْكُمْ﴾؟","answer":"اتهموه بطلب السيادة والرياسة عليهم؛ فصوّروا دعوته طموحًا شخصيًا، ليصرفوا الناس عن اتباعه ويثيروا عداوتهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص568، تحت عنوان «بلاغة الكناية في معنى التفضل عليهم»","url":""}]},{"id":"s23-26","number":26,"surah":23,"verses":[24],"references":[{"surah":23,"verses":[24]}],"verseLabel":"المؤمنون: 24","question":"ما نكتة التعبير بلفظ الجلالة في قول الملأ: ﴿وَلَوْ شَاءَ اللَّهُ لَأَنْزَلَ مَلَائِكَةً﴾؟","answer":"ناسب اسم الله احتجاجهم المزعوم بقدرته على إنزال الملائكة، لما يدل عليه الاسم من صفات الجلال والكمال؛ لكنهم جعلوا ذلك تعللًا لرفض الرسول البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص570، تحت عنوان «نكتة التعبير بلفظ الجلالة ﴿اللَّهُ﴾»","url":""}]},{"id":"s23-27","number":27,"surah":23,"verses":[25],"references":[{"surah":23,"verses":[25]}],"verseLabel":"المؤمنون: 25","question":"ما غرض القصر في زعمهم ﴿إِنْ هُوَ إِلَّا رَجُلٌ بِهِ جِنَّةٌ﴾؟","answer":"أرادوا حصر نوح في الوصف الذي افتروه عليه ونفي الرسالة عنه؛ فهذا قصر إضافي بحسب دعواهم، لا حجة على صحة اتهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص574، تحت عنوان «بلاغة القصر في الآية الكريمة»","url":""}]},{"id":"s23-130","number":130,"surah":23,"verses":[25],"references":[{"surah":23,"verses":[25]}],"verseLabel":"المؤمنون: 25","question":"ما الذي تفيده الباء في قولهم ﴿بِهِ جِنَّةٌ﴾؟","answer":"تفيد الملابسة؛ فقد صوّروه في زعمهم متلبسًا بالجنون. وهذا وصف ادعوه بلا حجة ليصرفوا الناس عن دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص575، تحت عنوان «سر استعمال الباء في قوله: ﴿به جنة﴾»","url":""}]},{"id":"s23-131","number":131,"surah":23,"verses":[25],"references":[{"surah":23,"verses":[25]}],"verseLabel":"المؤمنون: 25","question":"لماذا فُرّع ﴿فَتَرَبَّصُوا بِهِ﴾ بالفاء على اتهامهم نوحًا؟","answer":"جعلوا انتظار ما ينكشف من أمره نتيجة لاتهامهم؛ فزعموا أن الزمن سيظهر رجوعه إلى الرشد أو زيادة ما ادعوه عليه. لذلك لا ينحصر التربص هنا في انتظار موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص575، تحت عنوان «دلالة الفاء في قوله: ﴿فتربصوا﴾»","url":""}]},{"id":"s23-28","number":28,"surah":23,"verses":[26],"references":[{"surah":23,"verses":[26]}],"verseLabel":"المؤمنون: 26","question":"لماذا دعا نوح بـ﴿انْصُرْنِي﴾ ولم يصرّح بطلب إهلاك المكذبين؟","answer":"لأن النصر عليهم يستلزم إهلاكهم في هذا المقام؛ فسأل ما يدل على ذلك بطريق غير مباشر، وهو أدب في الدعاء كما يقرره المبحث.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص583، تحت عنوان «بلاغة الدعاء في قوله: ﴿انصرني﴾»","url":""}]},{"id":"s23-132","number":132,"surah":23,"verses":[26],"references":[{"surah":23,"verses":[26]}],"verseLabel":"المؤمنون: 26","question":"ما دلالة الباء في ﴿بِمَا كَذَّبُونِ﴾؟","answer":"تحتمل السببية: انصرني بسبب تكذيبهم، وتحتمل البدل: اجعل لي النصر عوض ما لقيته من غم التكذيب. وكلاهما يربط طلب النصر بما واجهته الرسالة من جحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص583، تحت عنوان «معنى الباء في قوله: ﴿بما كذبون﴾»","url":""}]},{"id":"s23-29","number":29,"surah":23,"verses":[27],"references":[{"surah":23,"verses":[27]}],"verseLabel":"المؤمنون: 27","question":"ما دلالة جعل فوران التنور علامة لبدء الطوفان؟","answer":"على حمل التنور على موضع الخبز، يكون خروج الماء من موضع الحرارة آية عجيبة أبلغ في الإنذار والاعتبار. وذكر المبحث أيضًا حمل العبارة على الكناية عن شدة الأمر أو بلوغه غايته؛ فلا يسوغ إغفال هذه الوجوه والجزم بتفسير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص589، تحت عنوان «علة جعل فوران التنور أمارة بداية الطوفان»","url":""}]},{"id":"s23-31","number":31,"surah":23,"verses":[28],"references":[{"surah":23,"verses":[28]}],"verseLabel":"المؤمنون: 28","question":"لماذا قيل لنوح ﴿فَقُلِ الْحَمْدُ لِلَّهِ﴾ بدل الاكتفاء بالأمر بالحمد؟","answer":"لإظهار الاعتراف بالنعمة وإقرارها على اللسان؛ فلا يبقى الحمد معنى في النفس وحدها، بل يجري قولًا يستتبع الشكر والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص603–604، تحت عنوان «دلالة فعل الأمر ﴿قل﴾ في السياق»","url":""}]},{"id":"s23-133","number":133,"surah":23,"verses":[28],"references":[{"surah":23,"verses":[28]}],"verseLabel":"المؤمنون: 28","question":"لماذا تعلّق الحمد بالنجاة في ﴿الَّذِي نَجَّانَا﴾ لا بإهلاك الظالمين؟","answer":"لأن الحمد يتعلق بالنعمة الواصلة إلى الحامد، وذكر النجاة يجمع حصول الخير وزوال الضرر. وفيه أيضًا أدب الثناء والإعراض عن الشماتة والتلذذ بمصيبة الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص604، تحت عنوان «دلالة ﴿الحمد﴾ على (الإنجاء) دون (الإهلاك)»","url":""}]},{"id":"s23-32","number":32,"surah":23,"verses":[29],"references":[{"surah":23,"verses":[29]}],"verseLabel":"المؤمنون: 29","question":"ما دلالة وصف المنزل بالبركة في دعاء نوح: ﴿رَبِّ أَنْزِلْنِي مُنْزَلًا مُبَارَكًا﴾؟","answer":"يدل وصف المنزل بأنه مبارك على ثبوت الخير ودوامه وإحاطته بهم حيث نزلوا؛ فالبركة تشمل السفينة التي كانت محل نجاتهم، ومرساها وما ينزلون إليه بعدها. فالمطلوب تمام النجاة مع دوام الخير، لا مجرد الوصول إلى مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص613، تحت عنوان «دلالة استعمال لفظ ﴿مباركا﴾ صفة للمنزل»","url":""}]},{"id":"s23-33","number":33,"surah":23,"verses":[30],"references":[{"surah":23,"verses":[30]}],"verseLabel":"المؤمنون: 30","question":"لماذا جُمع بين الآيات والابتلاء في ختام قصة نوح؟","answer":"لأن القصة تحمل دلائل وعبرًا، وتحمل كذلك اختبارًا يظهر به من يعتبر ويتذكر. فجاء الجمع بينهما لبيان هذين الجانبين من القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص617، تحت عنوان «موقع جملة ﴿وإن كنا لمبتلين﴾ مما قبلها»","url":""}]},{"id":"s23-134","number":134,"surah":23,"verses":[30],"references":[{"surah":23,"verses":[30]}],"verseLabel":"المؤمنون: 30","question":"لماذا قيل ﴿لَمُبْتَلِينَ﴾ باسم الفاعل؟","answer":"ليدل على ثبوت سنة الابتلاء واستمرارها في الماضي والحال والاستقبال، مع ملاءمة فواصل الآيات؛ فلا يقتصر المعنى على اختبار عابر انتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص617–618، تحت عنوان «دلالة التعبير باسم الفاعل في قوله: ﴿لمبتلين﴾»","url":""}]},{"id":"s23-34","number":34,"surah":23,"verses":[31],"references":[{"surah":23,"verses":[31]}],"verseLabel":"المؤمنون: 31","question":"ما سر التعبير بـ﴿أَنْشَأْنَا﴾ في قوله تعالى: ﴿ثُمَّ أَنْشَأْنَا مِنْ بَعْدِهِمْ قَرْنًا آخَرِينَ﴾؟","answer":"الإنشاء يجمع الإحداث والتربية حتى البلوغ والإدراك؛ ففيه تنبيه إلى أن الجيل الجديد قد بلغ أهلية التكليف وسماع بلاغ الرسل، فلا عذر له بغياب الإدراك أو النعم. ويدفع التعبير توهم أنهم مجرد بقايا من الجيل الذي هلك مع نوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص624–625، تحت عنوان «دلالة الفعل ﴿أنشأنا﴾ وإيثاره على غيره»","url":""}]},{"id":"s23-35","number":35,"surah":23,"verses":[33],"references":[{"surah":23,"verses":[33]}],"verseLabel":"المؤمنون: 33","question":"لماذا عُطف التكذيب بلقاء الآخرة على الكفر في وصف الملأ؟","answer":"لتعديد وجوه ذمهم وإبراز هذا الوجه العظيم من الكفر؛ فذكر القبائح متتابعة يزيد كشف حالهم وتقبيح موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص635، تحت عنوان «دلالة العطف بين فعلي ﴿كفروا وكذبوا﴾»","url":""}]},{"id":"s23-135","number":135,"surah":23,"verses":[33],"references":[{"surah":23,"verses":[33]}],"verseLabel":"المؤمنون: 33","question":"ما الذي يضيفه وصف الملأ بالترف إلى تفسير موقفهم من الرسول؟","answer":"يبين ما أورثهم النعيم من البطر والاستغناء والاستكبار؛ فقد توهموا أن كثرة المال والجاه معيار قبول الحق، فصدهم ذلك عن اتباع الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص637، تحت عنوان «دلالة التعبير بمادة (الترف)»","url":""}]},{"id":"s23-136","number":136,"surah":23,"verses":[33],"references":[{"surah":23,"verses":[33]}],"verseLabel":"المؤمنون: 33","question":"لماذا نُسب إترافهم إلى الله في قوله ﴿وَأَتْرَفْنَاهُمْ﴾؟","answer":"لتذكيرهم بمصدر النعمة وتقبيح مقابلتهم لها بالكفر؛ فقد جعلوا ما كان ينبغي أن يعينهم على الطاعة سببًا للاستكبار على المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص637، تحت عنوان «دلالة نسبة إترافهم إلى الله تعالى»","url":""}]},{"id":"s23-36","number":36,"surah":23,"verses":[34],"references":[{"surah":23,"verses":[34]}],"verseLabel":"المؤمنون: 34","question":"ما دلالة المغالطة في قول الملأ: ﴿وَلَئِنْ أَطَعْتُمْ بَشَرًا مِثْلَكُمْ إِنَّكُمْ إِذًا لَخَاسِرُونَ﴾؟","answer":"جعلوا طاعة بشر مثلهم سببًا لازمًا للخسران، مع أن مجرد البشرية لا يقتضي ذلك؛ وإنما تكون الخسارة في طاعة الباطل. أما الرسول فلا يأمر بباطل، فربط الخسران باتباعه تلبيس يراد به صرف الناس عن الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص645، تحت عنوان «دلالة جملة الجواب على المغالطة العقلية»","url":""}]},{"id":"s23-37","number":37,"surah":23,"verses":[35,36],"references":[{"surah":23,"verses":[35,36]}],"verseLabel":"المؤمنون: 35-36","question":"ما دلالة اسم الفعل ﴿هَيْهَاتَ﴾ في إنكار المكذبين للبعث؟","answer":"هو اسم فعل بمعنى بَعُد، يصور اعتقادهم أن البعث بعيد الوقوع ويحول استبعادهم إلى حكم موجز حاسم في زعمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص652، تحت عنوان «دلالة اسم الفعل ﴿هَيْهَاتَ﴾»","url":""}]},{"id":"s23-139","number":139,"surah":23,"verses":[35,36],"references":[{"surah":23,"verses":[35,36]}],"verseLabel":"المؤمنون: 35-36","question":"ما دلالة تكرار لفظ ﴿هَيْهَاتَ﴾؟","answer":"أكد التكرار شدة استبعادهم وبالغ في إنكارهم، فكأنهم يقولون: بَعُد بُعدًا شديدًا؛ وهو حكاية لموقفهم لا برهان على امتناع البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص652، تحت عنوان «دلالة تكرار لفظ ﴿هَيْهَاتَ﴾»","url":""}]},{"id":"s23-38","number":38,"surah":23,"verses":[37],"references":[{"surah":23,"verses":[37]}],"verseLabel":"المؤمنون: 37","question":"ما بلاغة القصر في قول المكذبين: ﴿إِنْ هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا﴾؟","answer":"قصروا جنس الحياة بطريق النفي والاستثناء على الحياة الدنيا، وهو قصر ادعائي كاذب ينكر حياة الآخرة ويعرض باطلهم في صورة الحكم المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص658، تحت عنوان «بلاغة القصر في السياق المحكم»","url":""}]},{"id":"s23-140","number":140,"surah":23,"verses":[37],"references":[{"surah":23,"verses":[37]}],"verseLabel":"المؤمنون: 37","question":"ما موقع جملة ﴿نَمُوتُ وَنَحْيَا﴾ من قولهم: ﴿إِنْ هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا﴾؟","answer":"جاءت بيانًا وتفسيرًا لقصرهم الحياة على الدنيا: يموت بعضهم ويحيا آخرون بالميلاد، فلا يريدون إقرارًا بالبعث بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص659، تحت عنوان «دلالة موقع جملة ﴿نَمُوتُ وَنَحْيَا﴾»","url":""}]},{"id":"s23-39","number":39,"surah":23,"verses":[38],"references":[{"surah":23,"verses":[38]}],"verseLabel":"المؤمنون: 38","question":"ما دلالة تقييد الافتراء بكونه كذبًا في قولهم: ﴿افْتَرَى عَلَى اللَّهِ كَذِبًا﴾؟","answer":"زادوا ﴿كذبًا﴾ لتغليظ تهمتهم للرسول وجمع وجوه الذم والتشهير به، مع أن الافتراء يتضمن الكذب أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص663، تحت عنوان «دلالة تقييد الافتراء بكونه كذبا»","url":""}]},{"id":"s23-141","number":141,"surah":23,"verses":[38],"references":[{"surah":23,"verses":[38]}],"verseLabel":"المؤمنون: 38","question":"ما بلاغة التذييل بقولهم: ﴿وَمَا نَحْنُ لَهُ بِمُؤْمِنِينَ﴾؟","answer":"ذيلوا دعواهم بنفي الإيمان توكيدًا لرفضهم، وجعلوه نتيجة لما زعموه من الافتراء؛ فكشف التذييل إصرارهم بعد اتهامهم الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص663، تحت عنوان «بلاغة التذييل بجملة ﴿وَمَا نَحْنُ لَهُ بِمُؤْمِنِينَ﴾»","url":""}]},{"id":"s23-40","number":40,"surah":23,"verses":[40],"references":[{"surah":23,"verses":[40]}],"verseLabel":"المؤمنون: 40","question":"ما دلالة ﴿مَا﴾ في قوله: ﴿عَمَّا قَلِيلٍ لَيُصْبِحُنَّ نَادِمِينَ﴾؟","answer":"تفصل ﴿ما﴾ بين الجار والمجرور على وجه يزيد معنى قلة الزمن ويؤكد قرب الندم والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص669، تحت عنوان «دلالة الفصل بـ (ما) ومعناها»","url":""}]},{"id":"s23-142","number":142,"surah":23,"verses":[40],"references":[{"surah":23,"verses":[40]}],"verseLabel":"المؤمنون: 40","question":"ما دلالة الفعل الناقص ﴿لَيُصْبِحُنَّ﴾ في قوله: ﴿لَيُصْبِحُنَّ نَادِمِينَ﴾؟","answer":"يصور صيرورتهم من الغطرسة إلى الندم، وقد يستحضر دخول الصباح؛ فالتعبير يجسد تحول حالهم عند معاينة الهلاك بعد فوات التدارك.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص670، تحت عنوان «دلالة الفعل الناقص ﴿لَيُصْبِحُنَّ﴾»","url":""}]},{"id":"s23-41","number":41,"surah":23,"verses":[41],"references":[{"surah":23,"verses":[41]}],"verseLabel":"المؤمنون: 41","question":"ما بلاغة التشبيه البليغ في قوله: ﴿فَجَعَلْنَاهُمْ غُثَاءً﴾؟","answer":"شبه الهالكون بغثاء السيل الذي يذهب جفاء، وحذفت الأداة ووجه الشبه حتى صاروا كأنهم الغثاء نفسه؛ فاشتدت صورة الحقارة والزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص677، تحت عنوان «بلاغة التشبيه البليغ في ﴿فَجَعَلْنَاهُمْ غُثَاءً﴾»","url":""}]},{"id":"s23-143","number":143,"surah":23,"verses":[41],"references":[{"surah":23,"verses":[41]}],"verseLabel":"المؤمنون: 41","question":"ما بلاغة الكناية في قوله: ﴿فَجَعَلْنَاهُمْ غُثَاءً﴾؟","answer":"تكني صورة الغثاء عن استئصالهم وذهاب قوتهم وقيمتهم ونفعهم، فلم يبق من جمعهم إلا ما يطرح ويزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص677، تحت عنوان «بلاغة الكناية في التركيب المحكم»","url":""}]},{"id":"s23-42","number":42,"surah":23,"verses":[42],"references":[{"surah":23,"verses":[42]}],"verseLabel":"المؤمنون: 42","question":"ما دلالة جمع ﴿قُرُونًا﴾ في قوله تعالى: ﴿ثُمَّ أَنْشَأْنَا مِنْ بَعْدِهِمْ قُرُونًا آخَرِينَ﴾، بعد إفراد ﴿قَرْنًا﴾ في الآية السابقة؟","answer":"جاء «قرنًا» مفردًا حين كان الحديث عن قوم معينين، ثم جُمع «قرونًا» لأن الحديث انتقل إلى أمم ورسالات متعددة، متتابعة أو متعاصرة. فالجمع بعد الإفراد إجمال بعد تفصيل، وتعميم بعد تعيين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص679، تحت عنوان «التشابه اللفظي بين آيتي سورة المؤمنون (42)، و(31)»","url":""}]},{"id":"s23-43","number":43,"surah":23,"verses":[43],"references":[{"surah":23,"verses":[43]}],"verseLabel":"المؤمنون: 43","question":"ما دلالة ﴿مِنْ﴾ في قوله: ﴿مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا﴾؟","answer":"زِيدت في سياق النفي لتأكيد الاستغراق، فنفت أن تسبق أي أمة مهما كانت أجلها المقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص685، تحت عنوان «معنى ﴿مِنْ﴾ ودلالتها»","url":""}]},{"id":"s23-44","number":44,"surah":23,"verses":[44],"references":[{"surah":23,"verses":[44]}],"verseLabel":"المؤمنون: 44","question":"ما دلالة تقييد إرسال الرسل بالحال ﴿تَتْرَا﴾؟","answer":"«تترى» أي متواترين يتبع بعضهم بعضًا؛ وهي تبين أن إرسال الرسل كان متعاقبًا مع فترات وانقطاع بين الإرسال والآخر، فالحال كاشفة عن كيفية وقوع هذا التعاقب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص690–691، تحت عنوان «سر القيد بالحال ﴿تترا﴾»","url":""}]},{"id":"s23-45","number":45,"surah":23,"verses":[44],"references":[{"surah":23,"verses":[44]}],"verseLabel":"المؤمنون: 44","question":"ما فائدة عطف قوله: ﴿وَجَعَلْنَاهُمْ أَحَادِيثَ﴾ على ما قبله؟","answer":"عطف أثر الهلاك الباقي على نفس الإهلاك؛ فلم تنته قصتهم بزوالهم، بل صار مصيرهم خبرًا وعظة يتناقلها الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص693–694، تحت عنوان «فائدة عطف جملة ﴿وَجَعَلْنَاهُمْ أَحَادِيثَ﴾ على ما قبلها»","url":""}]},{"id":"s23-144","number":144,"surah":23,"verses":[44],"references":[{"surah":23,"verses":[44]}],"verseLabel":"المؤمنون: 44","question":"ما بلاغة الكناية في قوله: ﴿وَجَعَلْنَاهُمْ أَحَادِيثَ﴾؟","answer":"كنى عن إبادتهم وتلاشي وجودهم حتى لم يبق منهم إلا أخبار تروى، فجمعت العبارة الاستئصال والتحول إلى عظة للمعتبرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص694، تحت عنوان «الغرض من الكناية في ﴿وَجَعَلْنَاهُمْ أَحَادِيثَ﴾ وسر اصطفائها»","url":""}]},{"id":"s23-46","number":46,"surah":23,"verses":[46],"references":[{"surah":23,"verses":[46]}],"verseLabel":"المؤمنون: 46","question":"ما دلالة اختيار فعل ﴿فَاسْتَكْبَرُوا﴾ مادة وصيغة؟","answer":"مادة الكبر تصور تعاظمهم عن قبول الحق، وصيغة الاستفعال تشعر بتكلف طلب الكبر وإظهاره في مواجهة الدعوة والبينات.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص702، تحت عنوان «إيثار فعل الاستكبار مادة وصيغة»","url":""}]},{"id":"s23-145","number":145,"surah":23,"verses":[46],"references":[{"surah":23,"verses":[46]}],"verseLabel":"المؤمنون: 46","question":"ما موقع جملة ﴿وَكَانُوا قَوْمًا عَالِينَ﴾ ودلالتها؟","answer":"جاءت حالًا أو تعليلًا يكشف أن استكبارهم ناشئ عن علو راسخ سابق، وأن رد الدعوة لم يكن موقفًا عابرًا منفصلًا عن طبعهم وسلطانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص703، تحت عنوان «موقع جملة ﴿وَكَانُوا قَوْمًا عَالِينَ﴾ ودلالتها»","url":""}]},{"id":"s23-47","number":47,"surah":23,"verses":[47],"references":[{"surah":23,"verses":[47]}],"verseLabel":"المؤمنون: 47","question":"ما غرض تقديم ﴿لَنَا﴾ على ﴿عَابِدُونَ﴾؟","answer":"يفيد القصر في زعم فرعون وملئه، كأن بني إسرائيل خاضعون لهم وحدهم؛ فاتخذوا ذلك ذريعة لاستكبارهم عن اتباع موسى وهارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص708، تحت عنوان «الغرض من تقديم ﴿لَنَا﴾ على ﴿عَابِدُونَ﴾»","url":""}]},{"id":"s23-146","number":146,"surah":23,"verses":[47],"references":[{"surah":23,"verses":[47]}],"verseLabel":"المؤمنون: 47","question":"ما بلاغة الاستعارة في وصف قوم موسى وهارون بأنهم ﴿عَابِدُونَ﴾؟","answer":"استعيرت العبادة لشدة الخضوع والانقياد السياسي، فبالغوا في تصوير استذلال بني إسرائيل؛ ولا يراد العبادة الدينية على حقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص708، تحت عنوان «الاستعارة في التعبير باسم الفاعل ﴿عَابِدُونَ﴾»","url":""}]},{"id":"s23-48","number":48,"surah":23,"verses":[49],"references":[{"surah":23,"verses":[49]}],"verseLabel":"المؤمنون: 49","question":"ما دلالة ﴿لَعَلَّهُمْ يَهْتَدُونَ﴾ بعد إيتاء موسى الكتاب؟","answer":"جاءت «لعل» هنا للتعليل: أُوتي موسى الكتاب ليكون سببًا لهداية بني إسرائيل. وفي صيغة الترجي إيماء إلى شأن الداعي الذي يرجو هداية المدعوين مع الأخذ بأسبابها؛ فالكتاب المنزل من شأنه أن يهديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص713، تحت عنوان «الغرض من التعبير بأسلوب الترجي (لعل)»","url":""}]},{"id":"s23-49","number":49,"surah":23,"verses":[50],"references":[{"surah":23,"verses":[50]}],"verseLabel":"المؤمنون: 50","question":"ما دلالة إفراد ﴿آيَةً﴾ في قوله تعالى: ﴿وَجَعَلْنَا ابْنَ مَرْيَمَ وَأُمَّهُ آيَةً﴾؟","answer":"من وجوه إفرادها أن عيسى وأمه يشتركان في معجزة واحدة: ولادته منها بلا أب، فلا تتم هذه الآية إلا باجتماعهما. ويحتمل اللفظ إرادة جنس الآية، فتندرج فيه وجوه القدرة المتعددة، لا حصر ما ظهر فيهما من الآيات في عدد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص719–720، تحت عنوان «الغرض من تنكير المفعول به ﴿آية﴾ وسر التعبير به مفردا»","url":""}]},{"id":"s23-50","number":50,"surah":23,"verses":[50],"references":[{"surah":23,"verses":[50]}],"verseLabel":"المؤمنون: 50","question":"ما دلالة وصف الربوة التي آوى الله إليها عيسى وأمه بأنها ﴿ذَاتِ قَرَارٍ وَمَعِينٍ﴾؟","answer":"هو وصف جامع لأسباب الراحة وطيب المكان؛ فهي صالحة للاستقرار، وفيها ما ينتفع به من الزروع والثمار، ومع ذلك ماء ظاهر جارٍ. فالوصف يجمع صلاحية المأوى وتوافر القوت والماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص721، تحت عنوان «سر وصف الربوة بأنها ﴿ذات قرار ومعين﴾»","url":""}]},{"id":"s23-51","number":51,"surah":23,"verses":[51],"references":[{"surah":23,"verses":[51]}],"verseLabel":"المؤمنون: 51","question":"ما سر التعبير بالمنادى جمعًا في قوله: ﴿يَا أَيُّهَا الرُّسُلُ﴾؟","answer":"جمع الرسل مع اختلاف أزمانهم لأن كل رسول خوطب بهذا الأصل في زمانه، فدل الجمع على وحدة منهجهم وشرائعهم في الطيب والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص725، تحت عنوان «سر التعبير بالمنادى جمعا في قوله: ﴿يَا أَيُّهَا الرُّسُلُ﴾»","url":""}]},{"id":"s23-147","number":147,"surah":23,"verses":[51],"references":[{"surah":23,"verses":[51]}],"verseLabel":"المؤمنون: 51","question":"ما سر تقديم جملة النداء ﴿يَا أَيُّهَا الرُّسُلُ﴾ على جملة الأمر؟","answer":"هيأ النداء المخاطبين للعناية بما بعده وشرفهم بوصف الرسالة قبل تكليفهم، فكان أوقع في تلقي الأمر والامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص725، تحت عنوان «سر تقديم جملة النداء على جملة الأمر»","url":""}]},{"id":"s23-148","number":148,"surah":23,"verses":[51],"references":[{"surah":23,"verses":[51]}],"verseLabel":"المؤمنون: 51","question":"لماذا خُص الرسل بالأكل من الطيبات والعمل الصالح؟","answer":"بين أن إباحة الطيبات والعمل الصالح شرع مطرد في الرسل، وأن طيب المطعم يعين على صلاح العمل ولا ينافي الزهد والرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص726، تحت عنوان «سر تخصيص خطاب الرسل جميعا بالأكل من الطيبات والعمل الصالح»","url":""}]},{"id":"s23-52","number":52,"surah":23,"verses":[51],"references":[{"surah":23,"verses":[51]}],"verseLabel":"المؤمنون: 51","question":"ما بلاغة الكناية في ختام آية المؤمنون: ﴿إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ﴾؟","answer":"العلم بالأعمال كناية عن الإحاطة بها ومجازاة أصحابها، فجاء بعد الأمر بالعمل الصالح ترغيبًا في الإحسان وتحذيرًا من التقصير والرياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص727، تحت عنوان «الغرض من التعبير بالكناية في قوله: ﴿إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ﴾»","url":""}]},{"id":"s23-149","number":149,"surah":23,"verses":[51],"references":[{"surah":23,"verses":[51]}],"verseLabel":"المؤمنون: 51","question":"ما مناسبة ختم آية سبأ بصفة البصر في قوله: ﴿إِنِّي بِمَا تَعْمَلُونَ بَصِيرٌ﴾؟","answer":"ناسب البصر مقام العمل الظاهر والمراقبة؛ فهو يذكر بأن الله يرى أعمالهم وأحوالهم، فيحث على صلاحها وإخلاصها ويحذر من التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص779، تحت عنوان «مناسبة ختم الآية الكريمة بصفة البصر»","url":""}]},{"id":"s23-53","number":53,"surah":23,"verses":[52],"references":[{"surah":23,"verses":[52]}],"verseLabel":"المؤمنون: 52","question":"ما موقع قوله: ﴿وَأَنَا رَبُّكُمْ﴾ مما قبله وما دلالته؟","answer":"يعلل وحدة الأمة بوحدة الرب المنعم؛ فانفراد الله بالربوبية والإحسان يقتضي توحيد الوجهة والاجتماع على عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص733، تحت عنوان «موقع قوله ﴿وَأَنَا رَبُّكُمْ﴾ مما قبله ودلالته»","url":""}]},{"id":"s23-150","number":150,"surah":23,"verses":[52],"references":[{"surah":23,"verses":[52]}],"verseLabel":"المؤمنون: 52","question":"ما دلالة اختيار الأمر ﴿فَاتَّقُونِ﴾ مادة وصيغة؟","answer":"اختيرت التقوى لأنها تجمع الطاعة والاحتراز من أسباب العقاب، وجاء الأمر نتيجة للربوبية ووحدة الدين: فمن كان الله ربه لزمه أن يتقيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص734، تحت عنوان «إيثار لفظ ﴿فَاتَّقُونِ﴾ مادة وصيغة»","url":""}]},{"id":"s23-54","number":54,"surah":23,"verses":[53],"references":[{"surah":23,"verses":[53]}],"verseLabel":"المؤمنون: 53","question":"ما دلالة اختيار ﴿فَتَقَطَّعُوا﴾ مادة وصيغة في وصف الأمم؟","answer":"تفيد المادة التفريق بعد الاتصال، وتدل الصيغة على التكلف والمبالغة؛ فصوروا الدين الواحد نحلًا متباعدة بأفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص735–736، تحت عنوان «إيثار الفعل ﴿فَتَقَطَّعُوا﴾ مادة وصيغة»","url":""}]},{"id":"s23-151","number":151,"surah":23,"verses":[53],"references":[{"surah":23,"verses":[53]}],"verseLabel":"المؤمنون: 53","question":"ما بلاغة الاستعارة في قوله: ﴿زُبُرًا﴾؟","answer":"استعيرت الزبر، وهي الكتب، للأديان والفرق المتقطعة تهكمًا؛ كأن كل فريق جعل هواه دينًا مسجلًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص736، تحت عنوان «بلاغة الاستعارة في قوله: ﴿زُبُرًا﴾»","url":""}]},{"id":"s23-55","number":55,"surah":23,"verses":[55,56],"references":[{"surah":23,"verses":[55,56]}],"verseLabel":"المؤمنون: 55-56","question":"ما غرض الاستفهام في قوله: ﴿أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُمْ بِهِ مِنْ مَالٍ وَبَنِينَ﴾؟","answer":"هو إنكاري توبيخي يبطل ظنهم أن الإمداد بالمال والبنين دليل إكرام وتعجيل للثواب؛ فقد يكون استدراجًا وإملاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص746، تحت عنوان «الغرض من التعبير بالاستفهام في ﴿أَيَحْسَبُونَ﴾»","url":""}]},{"id":"s23-152","number":152,"surah":23,"verses":[55,56],"references":[{"surah":23,"verses":[55,56]}],"verseLabel":"المؤمنون: 55-56","question":"ما دلالة ﴿بَلْ﴾ في قوله: ﴿بَلْ لَا يَشْعُرُونَ﴾؟","answer":"أبطلت ظنهم وانتقلت إلى بيان سبب اغترارهم: أنهم لا يشعرون بحقيقة الإمداد ولا بما وراءه من استدراج.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص750، تحت عنوان «دلالة ﴿بَلْ﴾»","url":""}]},{"id":"s23-56","number":56,"surah":23,"verses":[57],"references":[{"surah":23,"verses":[57]}],"verseLabel":"المؤمنون: 57","question":"ما دلالة اختيار لفظ ﴿مُشْفِقُونَ﴾ مادة وصيغة؟","answer":"الإشفاق خوف تصحبه رقة وحذر وعناية، وصيغة اسم الفاعل تثبت ملازمة هذا الشعور للمؤمنين من غير يأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص754، تحت عنوان «إيثار لفظ ﴿مُشْفِقُونَ﴾ مادة وصيغة»","url":""}]},{"id":"s23-153","number":153,"surah":23,"verses":[57],"references":[{"surah":23,"verses":[57]}],"verseLabel":"المؤمنون: 57","question":"ما دلالة الجمع بين الخشية والإشفاق في قوله: ﴿مِنْ خَشْيَةِ رَبِّهِمْ مُشْفِقُونَ﴾؟","answer":"الخشية خوف ناشئ من معرفة جلال الرب، والإشفاق أثرها العملي من الحذر والرقة؛ فجمعهما يبين أنهم لا يغترون بطاعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص755، تحت عنوان «دلالة الجمع بين الخشية والإشفاق»","url":""}]},{"id":"s23-57","number":57,"surah":23,"verses":[60],"references":[{"surah":23,"verses":[60]}],"verseLabel":"المؤمنون: 60","question":"ما نوع ﴿مَا﴾ ودلالتها في قوله: ﴿يُؤْتُونَ مَا آتَوْا﴾؟","answer":"هي موصولة تعم ما يؤتونه من صدقات وطاعات، فتوسع دائرة العمل المبذول ولا تحصره في نوع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص763، تحت عنوان «نوع ﴿مَا﴾ ودلالتها»","url":""}]},{"id":"s23-154","number":154,"surah":23,"verses":[60],"references":[{"surah":23,"verses":[60]}],"verseLabel":"المؤمنون: 60","question":"ما دلالة اختيار مفردة ﴿وَجِلَةٌ﴾ في قوله: ﴿وَقُلُوبُهُمْ وَجِلَةٌ﴾؟","answer":"الوجل خوف يخالطه اضطراب مع تعظيم، فصور خشيتهم من التقصير وعدم القبول رغم بذل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص766، تحت عنوان «دلالة اختيار مفردة ﴿وَجِلَةٌ﴾»","url":""}]},{"id":"s23-155","number":155,"surah":23,"verses":[60],"references":[{"surah":23,"verses":[60]}],"verseLabel":"المؤمنون: 60","question":"ما دلالة حذف حرف التعليل قبل قوله: ﴿أَنَّهُمْ إِلَى رَبِّهِمْ رَاجِعُونَ﴾؟","answer":"حذف اللام وأوصل المعنى مباشرة لتقوية اتصال وجلهم بيقين الرجوع والحساب؛ فكأن هذا اليقين حاضر في قلوبهم بلا واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص766–767، تحت عنوان «حذف حرف التعليل»","url":""}]},{"id":"s23-58","number":58,"surah":23,"verses":[61],"references":[{"surah":23,"verses":[61]}],"verseLabel":"المؤمنون: 61","question":"ما دلالة حرف الظرفية في قوله: ﴿يُسَارِعُونَ فِي الْخَيْرَاتِ﴾؟","answer":"صورتهم ﴿في﴾ منغمسين داخل أعمال الخير ومواظبين عليها، لا خارجين عنها يريدون بلوغها فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص772، تحت عنوان «دلالة استعمال حرف الظرفية»","url":""}]},{"id":"s23-156","number":156,"surah":23,"verses":[61],"references":[{"surah":23,"verses":[61]}],"verseLabel":"المؤمنون: 61","question":"ما براعة التعبير بـ﴿سَابِقُونَ﴾ بعد قوله: ﴿يُسَارِعُونَ﴾؟","answer":"جمع الوصفان المبادرة إلى الطاعات وإحرازها وثمراتها؛ فالمسارعة طريق، والسبق نتيجة تثبت تفوقهم في الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص776، تحت عنوان «براعة التعبير بـ﴿سَابِقُونَ﴾ بعد ذكر ﴿يُسَارِعُونَ﴾»","url":""}]},{"id":"s23-59","number":59,"surah":23,"verses":[62],"references":[{"surah":23,"verses":[62]}],"verseLabel":"المؤمنون: 62","question":"ما بلاغة الاستعارة في وصف كتاب الأعمال بأنه ﴿يَنْطِقُ﴾؟","answer":"استعير النطق لوضوح دلالة الكتاب وحجته القاطعة على الأعمال، كأن المكتوب يتكلم فيكشف تفاصيلها، مع احتمال النطق الحقيقي بقدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص786–787، تحت عنوان «نكتة الاستعارة في ﴿يَنْطِقُ﴾»","url":""}]},{"id":"s23-157","number":157,"surah":23,"verses":[62],"references":[{"surah":23,"verses":[62]}],"verseLabel":"المؤمنون: 62","question":"ما دلالة ﴿بِالْحَقِّ﴾ في قوله: ﴿كِتَابٌ يَنْطِقُ بِالْحَقِّ﴾؟","answer":"جاءت متعلِّقًا بالنطق أو حالًا منه لتقرر أن شهادة الكتاب مطابقة للأعمال لا زيادة فيها ولا ظلم لأصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص787، تحت عنوان «بلاغة المتعلق أو الحال ﴿بِالْحَقِّ﴾ بعد الصفة»","url":""}]},{"id":"s23-60","number":60,"surah":23,"verses":[63],"references":[{"surah":23,"verses":[63]}],"verseLabel":"المؤمنون: 63","question":"ما دلالة تصوير قلوب المشركين بأنها ﴿فِي غَمْرَةٍ﴾؟","answer":"استعيرت الغمرة للغفلة المستحكمة التي تغطي القلوب وتحجبها عن الحق، كما يغمر الماء ما تحته فيخفيه. فالصورة تجسّم شدة انغماسهم في الباطل حتى لا ينتفعوا بالتذكير والموعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص794، تحت عنوان «بلاغة الاستعارة التصريحية باستعمال مفردة ﴿غمرة﴾»","url":""}]},{"id":"s23-61","number":61,"surah":23,"verses":[64],"references":[{"surah":23,"verses":[64]}],"verseLabel":"المؤمنون: 64","question":"ما دلالة التعبير بـ﴿يَجْأَرُونَ﴾ مادة وصيغة؟","answer":"الجؤار رفع الصوت بالاستغاثة والتضرع، والمضارع يستحضر تجدده كلما اشتد العذاب، بعد ما كانوا عليه من بطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص18، تحت عنوان «دلالة التعبير بمفردة ﴿يَجْأَرُونَ﴾ مادة وصيغة»","url":""}]},{"id":"s23-158","number":158,"surah":23,"verses":[64],"references":[{"surah":23,"verses":[64]}],"verseLabel":"المؤمنون: 64","question":"لماذا خُص المترفون بالذكر عند الجؤار من العذاب؟","answer":"لأنهم أشد إحساسًا بالألم لعدم اعتيادهم الشدة، ولأنهم قادة الإغواء غالبًا؛ وليس التخصيص دليلًا على أن العذاب لا يصيب سواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص15، تحت عنوان «توجيه تخصيص المترفين بالذكر»","url":""}]},{"id":"s23-62","number":62,"surah":23,"verses":[66],"references":[{"surah":23,"verses":[66]}],"verseLabel":"المؤمنون: 66","question":"ما دلالة تصوير الإعراض بقوله تعالى: ﴿عَلَى أَعْقَابِكُمْ تَنْكِصُونَ﴾؟","answer":"شُبّه حالهم عند سماع القرآن وإعراض قلوبهم عنه بحال من يرجع القهقرى إلى الخلف. وهي استعارة تمثيلية تصوّر شدة الغفلة والفرار من الحق، وتقبّح صدودهم عن الآيات المقبلة عليهم بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص26، تحت عنوان «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s23-63","number":63,"surah":23,"verses":[67],"references":[{"surah":23,"verses":[67]}],"verseLabel":"المؤمنون: 67","question":"ما دلالة ﴿تَهْجُرُونَ﴾ في وصف سمر المشركين، وكيف تتكامل قراءتاها؟","answer":"تحتمل قراءة فتح التاء معنى هجر القرآن والإعراض عن سماعه، ومعنى الهذيان والقول القبيح. وقراءة ضم التاء وكسر الجيم من الإهجار تؤكد معنى الفحش وسوء القول؛ فتجتمع في وصف سمرهم مجانبة الحق والطعن فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص29–30، تحت عنوان «توجيه القراءات القرآنية في ﴿تهجرون﴾ وبلاغتها»","url":""}]},{"id":"s23-64","number":64,"surah":23,"verses":[68],"references":[{"surah":23,"verses":[68]}],"verseLabel":"المؤمنون: 68","question":"ما غرض الاستفهام في قوله: ﴿أَفَلَمْ يَدَّبَّرُوا الْقَوْلَ﴾؟","answer":"ينكر عليهم ترك تدبر القرآن ويوبخهم على الإعراض عن دلائل صدقه وهدايته مع قدرتهم على التأمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص34–35، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s23-159","number":159,"surah":23,"verses":[68],"references":[{"surah":23,"verses":[68]}],"verseLabel":"المؤمنون: 68","question":"ما بلاغة اختيار مفردة ﴿يَدَّبَّرُوا﴾؟","answer":"التدبر نظر متأن في أوائل الكلام وأواخره وعواقب معانيه؛ فاختير لطلب فهم يتجاوز سماع الألفاظ إلى استنباط الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص35–36، تحت عنوان «بلاغة استعمال مفردة التدبر»","url":""}]},{"id":"s23-65","number":65,"surah":23,"verses":[69],"references":[{"surah":23,"verses":[69]}],"verseLabel":"المؤمنون: 69","question":"ما نوع ﴿أَمْ﴾ ودلالتها في قوله: ﴿أَمْ لَمْ يَعْرِفُوا رَسُولَهُمْ﴾؟","answer":"هي منقطعة للانتقال من توبيخ إلى آخر، ومعناها الإضراب والاستفهام الإنكاري: بل أعجزوا عن معرفة من عرفوا صدقه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص41، تحت عنوان «نوع ﴿أَمْ﴾ ودلالتها»","url":""}]},{"id":"s23-160","number":160,"surah":23,"verses":[69],"references":[{"surah":23,"verses":[69]}],"verseLabel":"المؤمنون: 69","question":"ما دلالة إضافة لفظ الرسول إلى ضميرهم في قوله: ﴿رَسُولَهُمْ﴾؟","answer":"تذكر بأنه من قومهم معروف النسب والسيرة والصدق بينهم، فجعلت معرفتهم به حجة عليهم لا مسوغًا لتكذيبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص42، تحت عنوان «دلالة إضافة لفظ الرسول إلى الضمير»","url":""}]},{"id":"s23-66","number":66,"surah":23,"verses":[70],"references":[{"surah":23,"verses":[70]}],"verseLabel":"المؤمنون: 70","question":"ما سر جمع ﴿أَهْوَاءَهُمْ﴾ وإضافتها إلى ضمير الجمع؟","answer":"أبرز الجمع والإضافة كثرة الأهواء بتعدد أصحابها وتعارض مطالبهم، في مقابل وحدة الحق وثباته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص57، تحت عنوان «سر الجمع والإضافة إلى الجمع»","url":""}]},{"id":"s23-161","number":161,"surah":23,"verses":[70],"references":[{"surah":23,"verses":[70]}],"verseLabel":"المؤمنون: 70","question":"ما بلاغة اختيار مفردة ﴿الْفَسَادِ﴾ في قوله: ﴿لَفَسَدَتِ السَّمَاوَاتُ وَالْأَرْضُ﴾؟","answer":"الفساد لفظ جامع لاختلال النظام وزوال الصلاح، فبين أن تحكيم الأهواء لا يخل بجزء واحد بل يفضي إلى اضطراب الكون كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص57، تحت عنوان «بلاغة استعمال مفردة الفساد»","url":""}]},{"id":"s23-67","number":67,"surah":23,"verses":[72],"references":[{"surah":23,"verses":[72]}],"verseLabel":"المؤمنون: 72","question":"ما نوع الاستفهام في قوله: ﴿أَمْ تَسْأَلُهُمْ خَرْجًا﴾ وما دلالته؟","answer":"هو إنكاري ينفي أن يكون الرسول طلب منهم أجرًا يثقلهم أو يبرر إعراضهم، فيقطع عذرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص66، تحت عنوان «نوع الاستفهام ودلالته»","url":""}]},{"id":"s23-162","number":162,"surah":23,"verses":[72],"references":[{"surah":23,"verses":[72]}],"verseLabel":"المؤمنون: 72","question":"ما دلالة الفاء في قوله: ﴿فَخَرَاجُ رَبِّكَ خَيْرٌ﴾؟","answer":"تفيد التفريع على نفي سؤال الأجر: فإذا لم يطلب منهم خرجًا فما عند ربه من رزق وثواب خير وأغنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص67، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s23-163","number":163,"surah":23,"verses":[72],"references":[{"surah":23,"verses":[72]}],"verseLabel":"المؤمنون: 72","question":"ما بلاغة القراءات في لفظتي ﴿خَرْجًا﴾ و﴿فَخَرَاجُ﴾؟","answer":"توسع القراءات المعنى بين الأجر والخراج المستمر، وتبرز المقابلة بين ما قد يطلب من الناس وما يمنحه الله؛ فعطاؤه أعظم وأدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص68، تحت عنوان «توجيه القراءات القرآنية في لفظتي ﴿خَرْجًا﴾ و﴿فَخَرَاجُ﴾ وبلاغتها»","url":""}]},{"id":"s23-68","number":68,"surah":23,"verses":[73],"references":[{"surah":23,"verses":[73]}],"verseLabel":"المؤمنون: 73","question":"ما دلالة التوكيد في قوله تعالى: ﴿وَإِنَّكَ لَتَدْعُوهُمْ إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"يؤكد بـ«إن» واللام أن دعوة النبي حق مستقيم، ردًّا على من أعرضوا عنها واتهموها. فالخطاب موجه إليه، وفيه تعريض بالمكذبين بعد إزالة الشبه التي تعلقوا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص73، تحت عنوان «غرض توكيد الخطاب»","url":""}]},{"id":"s23-69","number":69,"surah":23,"verses":[74],"references":[{"surah":23,"verses":[74]}],"verseLabel":"المؤمنون: 74","question":"ما دلالة وصف منكري الآخرة بأنهم ﴿عَنِ الصِّرَاطِ لَنَاكِبُونَ﴾؟","answer":"الناكب هو العادل عن الشيء والمُعرض عنه، فالتعبير كناية عن اجتناب طريق الحق والتولي عنه. وجاء اسم الفاعل مع اللام ليؤكد رسوخ هذا الإعراض واستمراره فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص80، تحت عنوان «بلاغة استعمال مفردة ﴿لناكبون﴾»","url":""}]},{"id":"s23-70","number":70,"surah":23,"verses":[75],"references":[{"surah":23,"verses":[75]}],"verseLabel":"المؤمنون: 75","question":"ما دلالة ﴿لَلَجُّوا﴾ في قوله تعالى: ﴿وَلَوْ رَحِمْنَاهُمْ وَكَشَفْنَا مَا بِهِمْ مِنْ ضُرٍّ لَلَجُّوا فِي طُغْيَانِهِمْ يَعْمَهُونَ﴾؟","answer":"اللجاج تمادٍ عنيد في الفعل مع تكراره؛ فهو يصور إقامتهم على الكفر حتى لو زال ما بهم من ضر. فلا يحملهم كشفه على الرجوع، بل يستمرون في طغيانهم وترددهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص89، تحت عنوان «نكتة التعبير بلفظ اللجاج»","url":""}]},{"id":"s23-71","number":71,"surah":23,"verses":[76],"references":[{"surah":23,"verses":[76]}],"verseLabel":"المؤمنون: 76","question":"ما نكتة عطف نفي التضرع على نفي الاستكانة؟","answer":"نُفي خضوعهم أولًا، ثم نفي التضرع الذي كان ينبغي أن يفعلوه عند الشدة، فزاد العطف في تصوير استمرار العناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص97، تحت عنوان «نكتة عطف نفي التضرع على نفي الاستكانة»","url":""}]},{"id":"s23-164","number":164,"surah":23,"verses":[76],"references":[{"surah":23,"verses":[76]}],"verseLabel":"المؤمنون: 76","question":"ما نكتة تكرار حرف النفي ﴿مَا﴾ في قوله: ﴿فَمَا اسْتَكَانُوا... وَمَا يَتَضَرَّعُونَ﴾؟","answer":"استقل كل من الخضوع والتضرع بالنفي، فقرر أنهم لم يجمعوا بينهما ولم يتحقق منهم أحدهما منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص97، تحت عنوان «نكتة تكرار حرف النفي (ما)»","url":""}]},{"id":"s23-72","number":72,"surah":23,"verses":[77],"references":[{"surah":23,"verses":[77]}],"verseLabel":"المؤمنون: 77","question":"ما سر التعبير بـ﴿إِذَا﴾ الفجائية في قوله: ﴿إِذَا هُمْ فِيهِ مُبْلِسُونَ﴾؟","answer":"صورت وقوع الإبلاس مباشرة عند فتح باب العذاب الشديد، على خلاف ما اعتادوه من رجاء انكشاف الشدائد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص105، تحت عنوان «سر التعبير بـ﴿إِذَا﴾ الفجائية جزاء للشرط»","url":""}]},{"id":"s23-73","number":73,"surah":23,"verses":[78],"references":[{"surah":23,"verses":[78]}],"verseLabel":"المؤمنون: 78","question":"لماذا خُص السمع والأبصار والأفئدة بالذكر في سياق الامتنان؟","answer":"لأنها أصول التلقي والتفكر والاستدلال، وبها تعرف المنافع والمضار ويميز الحق من الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص111–112، تحت عنوان «سبب إيثار ذكر ﴿السَّمْعَ﴾ و﴿الْأَبْصَارَ﴾ و﴿الْأَفْئِدَةَ﴾»","url":""}]},{"id":"s23-74","number":74,"surah":23,"verses":[79],"references":[{"surah":23,"verses":[79]}],"verseLabel":"المؤمنون: 79","question":"ما نكتة التعبير بلفظ ﴿ذَرَأَكُمْ﴾؟","answer":"يجمع الذرء معنى الخلق والتكثير والبث في الأرض، فيصور انتشار البشر وتمكينهم من القرار فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص119، تحت عنوان «نكتة التعبير بلفظ ﴿ذَرَأَكُمْ﴾»","url":""}]},{"id":"s23-165","number":165,"surah":23,"verses":[79],"references":[{"surah":23,"verses":[79]}],"verseLabel":"المؤمنون: 79","question":"ما فائدة عطف قوله: ﴿وَإِلَيْهِ تُحْشَرُونَ﴾ على قوله: ﴿ذَرَأَكُمْ فِي الْأَرْضِ﴾؟","answer":"ربط العطف بدء الخلق بإعادته؛ فالذي بث الناس في الأرض قادر على جمعهم للحساب، فلا تكون نعمة الإنشاء منفصلة عن مسؤولية الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص120، تحت عنوان «فائدة العطف في قوله ﴿وَإِلَيْهِ تُحْشَرُونَ﴾»","url":""}]},{"id":"s23-75","number":75,"surah":23,"verses":[80],"references":[{"surah":23,"verses":[80]}],"verseLabel":"المؤمنون: 80","question":"ما نكتة التعبير بلفظ ﴿اخْتِلَافُ﴾ في قوله: ﴿وَلَهُ اخْتِلَافُ اللَّيْلِ وَالنَّهَارِ﴾؟","answer":"يشمل الاختلاف التعاقب وتغاير الظلمة والنور والزيادة والنقصان؛ فجمع اللفظ وجوه التحول المنتظم بين الزمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص128، تحت عنوان «نكتة التعبير بلفظ ﴿اخْتِلَافُ﴾»","url":""}]},{"id":"s23-166","number":166,"surah":23,"verses":[80],"references":[{"surah":23,"verses":[80]}],"verseLabel":"المؤمنون: 80","question":"ما بلاغة تقديم المسند ﴿لَهُ﴾ في قوله: ﴿وَلَهُ اخْتِلَافُ اللَّيْلِ وَالنَّهَارِ﴾؟","answer":"يفيد التقديم اختصاص الله بخلق اختلاف الليل والنهار وتدبيره، وينفي أن يكون هذا النظام لغير قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص128، تحت عنوان «بلاغة تقديم المسند على المسند إليه»","url":""}]},{"id":"s23-76","number":76,"surah":23,"verses":[82],"references":[{"surah":23,"verses":[82]}],"verseLabel":"المؤمنون: 82","question":"ما دلالة قوله تعالى: ﴿بَلْ قَالُوا مِثْلَ مَا قَالَ الْأَوَّلُونَ﴾ في إنكار البعث؟","answer":"يكشف أن إنكارهم ناشئ من تقليد الآباء ومتابعة السابقين بلا هدى، لا من تدبر الحجج الظاهرة. وفيه توبيخ لمن يتبع قولًا لا دليل له سوى أن غيره سبقه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص134–135، تحت عنوان «مناسبة مجيء قوله ﴿قالوا مثل ما قال الأولون﴾»","url":""}]},{"id":"s23-77","number":77,"surah":23,"verses":[84,85,86,87,88,89],"references":[{"surah":23,"verses":[84,85,86,87,88,89]}],"verseLabel":"المؤمنون: 84-89","question":"ما بديع الجمع والتقسيم في أسئلة الإقرار بملك الله؟","answer":"تدرجت المحاجة من الأرض ومن فيها إلى السماوات والعرش، ثم جمعت ذلك كله في ﴿مَلَكُوتُ كُلِّ شَيْءٍ﴾؛ فبعد التفصيل جاء الإجمال الجامع لإلزامهم بمقتضى إقرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص175، تحت عنوان «بديع الجمع والتقسيم في الآية»","url":""}]},{"id":"s23-167","number":167,"surah":23,"verses":[84,85,86,87,88,89],"references":[{"surah":23,"verses":[84,85,86,87,88,89]}],"verseLabel":"المؤمنون: 84-89","question":"كيف استُدل بملك الله وخلقه على البعث بعد الموت؟","answer":"إقرارهم بأن الله خلق الأرض ومن فيها ويدبر الملكوت يلزم منه قدرته على إعادة الموتى؛ فلا يستقيم إثبات الخلق الأول وإنكار الإحياء الثاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص154، تحت عنوان «وجه الاستدلال في الآية على البعث بعد الممات»","url":""}]},{"id":"s23-78","number":78,"surah":23,"verses":[89],"references":[{"surah":23,"verses":[89]}],"verseLabel":"المؤمنون: 89","question":"ما دلالة ختام المحاجة بقوله تعالى: ﴿فَأَنَّى تُسْحَرُونَ﴾؟","answer":"شُبّه انصرافهم عن الحق، بعد إقرارهم بملك الله وقدرته، بحال من خُدع بالسحر فتوهم الباطل حقًّا. ففي التعبير تقبيح لانخداعهم بما يموّه عليهم، وتعجيب من مخالفة نتيجة إقرارهم الواضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص180–181، تحت عنوان «بلاغة الاستعارة في قوله ﴿تسحرون﴾»","url":""}]},{"id":"s23-79","number":79,"surah":23,"verses":[91],"references":[{"surah":23,"verses":[91]}],"verseLabel":"المؤمنون: 91","question":"ما دلالة ﴿مِنْ﴾ في قوله: ﴿مَا اتَّخَذَ اللَّهُ مِنْ وَلَدٍ﴾؟","answer":"زِيدت في سياق النفي لتأكيد الاستغراق، فنفت اتخاذ أي ولد بوجه من الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص191–192، تحت عنوان «معنى ﴿مِنْ﴾ ودلالتها في ﴿مِنْ وَلَدٍ﴾»","url":""}]},{"id":"s23-168","number":168,"surah":23,"verses":[91],"references":[{"surah":23,"verses":[91]}],"verseLabel":"المؤمنون: 91","question":"ما بديع المذهب الكلامي في نفي تعدد الآلهة؟","answer":"بنى البرهان على لوازم الفرض الباطل: لو تعددت الآلهة لانفرد كل واحد بخلقه أو غلب بعضهم بعضًا، وانتظام الكون ووحدة تدبيره يبطلان ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص196–197، تحت عنوان «بديع المذهب الكلامي»","url":""}]},{"id":"s23-80","number":80,"surah":23,"verses":[92],"references":[{"surah":23,"verses":[92]}],"verseLabel":"المؤمنون: 92","question":"ما دلالة الجمع بين الغيب والشهادة في قوله تعالى: ﴿عَالِمِ الْغَيْبِ وَالشَّهَادَةِ﴾؟","answer":"يجمع الطباق بين ما غاب عن الخلق وما حضر لهم، فيدل على إحاطة علم الله بجميع المعلومات، سرّها وعلانيتها. وهذه الإحاطة تنافي ما ينسبونه إليه من الشركاء الذين لا يملكون مثل هذا العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص205، تحت عنوان «بلاغة الطباق في ﴿عالم الغيب والشهادة﴾»","url":""}]},{"id":"s23-81","number":81,"surah":23,"verses":[93,94],"references":[{"surah":23,"verses":[93,94]}],"verseLabel":"المؤمنون: 93-94","question":"ما دلالة صيغة النهي في دعاء النبي: ﴿فَلَا تَجْعَلْنِي فِي الْقَوْمِ الظَّالِمِينَ﴾؟","answer":"ورد الدعاء بصيغة النهي، ومعناه سؤال الله الحفظ من أن يشمله ما ينزل بالظالمين من عقاب. وفي تعليم النبي هذا الدعاء إظهار للعبودية والافتقار إلى الله، وتعليم للابتهال إليه في دفع البلاء، مع التحذير من حال الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص214، تحت عنوان «غرض التعبير بالنهي ﴿فلا تجعلني﴾»","url":""}]},{"id":"s23-82","number":82,"surah":23,"verses":[96],"references":[{"surah":23,"verses":[96]}],"verseLabel":"المؤمنون: 96","question":"ما دلالة صيغة التفضيل في قوله تعالى: ﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ السَّيِّئَةَ﴾؟","answer":"ترشد صيغة «أحسن» إلى اختيار أبلغ وجوه الإحسان في مقابلة الإساءة، من الحلم والصفح وحسن المعاملة؛ فلا يقف المطلوب عند ترك الانتقام، بل يرتقي إلى الخُلُق الذي هو أحسن في دفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص226، تحت عنوان «دلالة التعبير بخبر المبتدأ (أفعل) تفضيل»","url":""}]},{"id":"s23-83","number":83,"surah":23,"verses":[97,98],"references":[{"surah":23,"verses":[97,98]}],"verseLabel":"المؤمنون: 97-98","question":"ما سر الإضافة والجمع في قوله: ﴿هَمَزَاتِ الشَّيَاطِينِ﴾؟","answer":"أضيفت الهمزات إلى الشياطين لكشف مصدرها، وجمعت لتعدد وساوسهم ونزغاتهم وتجددها في دفع الإنسان إلى الغضب والمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص236، تحت عنوان «سر الإضافة ودلالة الجمع في ﴿هَمَزَاتِ الشَّيَاطِينِ﴾»","url":""}]},{"id":"s23-169","number":169,"surah":23,"verses":[97,98],"references":[{"surah":23,"verses":[97,98]}],"verseLabel":"المؤمنون: 97-98","question":"ما دلالة عطف قوله: ﴿وَأَعُوذُ بِكَ رَبِّ أَنْ يَحْضُرُونِ﴾؟","answer":"زاد العطف الاستعاذة من مجرد حضور الشياطين بعد الاستعاذة من نزغاتهم، مبالغة في سد أسباب التأثير قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص236–237، تحت عنوان «دلالة العطف بالواو في ﴿وَأَعُوذُ بِكَ﴾»","url":""}]},{"id":"s23-84","number":84,"surah":23,"verses":[99,100],"references":[{"surah":23,"verses":[99,100]}],"verseLabel":"المؤمنون: 99-100","question":"ما سر التعبير بصيغة الجمع في طلب الرجوع: ﴿رَبِّ ارْجِعُونِ﴾؟","answer":"ذكر المصدر ثلاثة توجيهات: أن الجمع لتعظيم المخاطَب، وهو الله؛ أو أن نداء «رب» توجه إلى الله ثم وُجّه طلب الرجوع إلى الملائكة؛ أو أن صيغة الجمع تدل على تكرير الطلب لشدة التلهف، كأنه يقول: ارجعني، ارجعني. فلا يُحصر التعبير في توجيه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص249–250، تحت عنوان «نكتة العدول إلى ﴿رب ارجعون﴾»","url":""}]},{"id":"s23-85","number":85,"surah":23,"verses":[100],"references":[{"surah":23,"verses":[100]}],"verseLabel":"المؤمنون: 100","question":"ما دلالة وصف طلب الرجوع بأنه ﴿كَلِمَةٌ هُوَ قَائِلُهَا﴾؟","answer":"قيدت الكلمة بالجملة الاسمية «هو قائلها» لتبيين أنها لا تتجاوز القول إلى تحقيق المطلوب. ومن توجيهاتها أنه يقولها بلسانه من شدة الكرب دون صدق يقتضي الوفاء، أو أنها كلمة يقولها ولا يُجاب إليها؛ ففي الحالين لا يترتب عليها رجوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص255–256، تحت عنوان «سر تقييد خبر (إن) بجملة صفة اسمية»","url":""}]},{"id":"s23-86","number":86,"surah":23,"verses":[101],"references":[{"surah":23,"verses":[101]}],"verseLabel":"المؤمنون: 101","question":"ما سر تقييد نفي الأنساب بقوله: ﴿يَوْمَئِذٍ﴾؟","answer":"قيد الحكم بيوم القيامة لأن حقيقة القرابة لا تزول، وإنما ينقطع يومئذ نفعها وما كان الناس يتناصرون ويتفاخرون به من أجلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص265، تحت عنوان «سر التقييد بالظرف المضاف ﴿يَوْمَئِذٍ﴾»","url":""}]},{"id":"s23-170","number":170,"surah":23,"verses":[101],"references":[{"surah":23,"verses":[101]}],"verseLabel":"المؤمنون: 101","question":"ما دلالة عطف قوله: ﴿وَلَا يَتَسَاءَلُونَ﴾ على نفي الأنساب؟","answer":"أكمل العطف صورة انقطاع أسباب التناصر: فلا أنساب نافعة ولا تساؤل مؤانسة أو استعانة ينقذ بعضهم بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص266، تحت عنوان «دلالة العطف في ﴿وَلَا﴾»","url":""}]},{"id":"s23-87","number":87,"surah":23,"verses":[102,103],"references":[{"surah":23,"verses":[102,103]}],"verseLabel":"المؤمنون: 102-103","question":"ما غرض المقابلة بين ثقل الموازين والفلاح وخفتها والخسران؟","answer":"وضعت المقابلة المصيرين متجاورين، فأبرزت التفاوت الحاسم بين من رجحت حسناته فأفلح ومن خفت موازينه فهلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص274، تحت عنوان «غرض التعبير بأسلوب المقابلة»","url":""}]},{"id":"s23-171","number":171,"surah":23,"verses":[102,103],"references":[{"surah":23,"verses":[102,103]}],"verseLabel":"المؤمنون: 102-103","question":"ما بلاغة المجاز في قوله: ﴿خَسِرُوا أَنْفُسَهُمْ﴾؟","answer":"صور هلاك النفس بالخسران التجاري، فبين أن الضائع ليس مالًا خارجًا عن الإنسان، بل نفسه التي كان ينبغي أن يسعى في نجاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص276، تحت عنوان «غرض التعبير بالمجاز في ﴿خَسِرُوا أَنْفُسَهُمْ﴾»","url":""}]},{"id":"s23-88","number":88,"surah":23,"verses":[104],"references":[{"surah":23,"verses":[104]}],"verseLabel":"المؤمنون: 104","question":"ما دلالة لفظ ﴿تَلْفَحُ﴾ في قوله: ﴿تَلْفَحُ وُجُوهَهُمُ النَّارُ﴾؟","answer":"اللفح إصابة بحر النار وسمومها حتى يتغير الجلد، فاختير لتجسيد شدة مباشرة النار للوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص280، تحت عنوان «اللفح والكي»","url":""}]},{"id":"s23-89","number":89,"surah":23,"verses":[105],"references":[{"surah":23,"verses":[105]}],"verseLabel":"المؤمنون: 105","question":"ما بلاغة الاستفهام في قوله: ﴿أَلَمْ تَكُنْ آيَاتِي تُتْلَى عَلَيْكُمْ﴾؟","answer":"هو للتقرير والتوبيخ؛ يثبت أنهم تلقوا الآيات وقامت عليهم الحجة، فلم يأتهم العذاب بغير إنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص283، تحت عنوان «بلاغة الاستفهام في صدر الآية»","url":""}]},{"id":"s23-172","number":172,"surah":23,"verses":[105],"references":[{"surah":23,"verses":[105]}],"verseLabel":"المؤمنون: 105","question":"ما سر اختيار الفعل ﴿تُتْلَى﴾ مادة وصيغة؟","answer":"التلاوة تدل على قراءة الآيات متتابعة، والمضارع يستحضر تجدد عرضها عليهم في مقابل استمرار تكذيبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص284، تحت عنوان «سر إيثار الفعل ﴿تُتْلَى﴾ مادة وصيغة»","url":""}]},{"id":"s23-90","number":90,"surah":23,"verses":[108],"references":[{"surah":23,"verses":[108]}],"verseLabel":"المؤمنون: 108","question":"ما سر اختيار لفظ ﴿اخْسَئُوا﴾ مادة وصيغة؟","answer":"اللفظ زجر يحمل الإبعاد والذل والإهانة، وأمره يلزمهم الصمت والاستقرار في النار ويقطع رجاء الإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص300، تحت عنوان «سر اختيار لفظ ﴿اخْسَئُوا﴾ مادة وصيغة»","url":""}]},{"id":"s23-173","number":173,"surah":23,"verses":[108],"references":[{"surah":23,"verses":[108]}],"verseLabel":"المؤمنون: 108","question":"لماذا قيل: ﴿وَلَا تُكَلِّمُونِ﴾ دون «ولا تكلموا»؟","answer":"نهوا عن توجيه الكلام إلى الله خاصة، فكان أبلغ من نهي مطلق عن الكلام؛ إذ قطع رجاءهم في مخاطبته بطلب الخروج والتخفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص301، تحت عنوان «سر اختيار ﴿وَلَا تُكَلِّمُونِ﴾ دون (ولا تكلموا)»","url":""}]},{"id":"s23-174","number":174,"surah":23,"verses":[108],"references":[{"surah":23,"verses":[108]}],"verseLabel":"المؤمنون: 108","question":"ما بلاغة المجاز في النهي عن التكلم في قوله: ﴿وَلَا تُكَلِّمُونِ﴾؟","answer":"النهي عن الكلام مجاز مرسل يراد به منع لازمه ومقصوده، وهو سؤال الخروج والنجاة؛ لا نفي كل كلام يقع بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص302، تحت عنوان «بلاغة المجاز في النهي عن التكلم»","url":""}]},{"id":"s23-91","number":91,"surah":23,"verses":[109],"references":[{"surah":23,"verses":[109]}],"verseLabel":"المؤمنون: 109","question":"لماذا فُصلت جملة ﴿إِنَّهُ كَانَ فَرِيقٌ مِنْ عِبَادِي يَقُولُونَ﴾ عما قبلها؟","answer":"جاءت استئنافًا بيانيًا يعلل زجر أهل النار ومنع دعائهم، فكأنها جواب عن سؤال: لماذا منعوا من الكلام؟ لأنهم سخروا من عباد الله المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص304، تحت عنوان «علة فصل صدر الجملة عما قبلها»","url":""}]},{"id":"s23-175","number":175,"surah":23,"verses":[109],"references":[{"surah":23,"verses":[109]}],"verseLabel":"المؤمنون: 109","question":"ما دلالة الفاء في قوله: ﴿فَاتَّخَذْتُمُوهُمْ سِخْرِيًّا﴾؟","answer":"فرعت الفاء اتخاذ المؤمنين سخرية على دعائهم وإيمانهم، فصورت جرم الكافرين: جعلوا عبادة المؤمنين سببًا للاستهزاء بدل الاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص313، تحت عنوان «دلالة الفاء في صدر الآية»","url":""}]},{"id":"s23-92","number":92,"surah":23,"verses":[111],"references":[{"surah":23,"verses":[111]}],"verseLabel":"المؤمنون: 111","question":"ما دلالة الباء وتخصيص الصبر في قوله: ﴿جَزَيْتُهُمُ الْيَوْمَ بِمَا صَبَرُوا﴾؟","answer":"الباء سببية، فقررت أن صبرهم سبب الجزاء، وخص الصبر لأنه جامع لثباتهم على الطاعة واحتمالهم سخرية المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص318، تحت عنوان «دلالة الباء ودخولها على الصبر خاصة، ومجيئه بصيغة الماضي»","url":""}]},{"id":"s23-93","number":93,"surah":23,"verses":[112,113,114],"references":[{"surah":23,"verses":[112,113,114]}],"verseLabel":"المؤمنون: 112-114","question":"ما دلالة سؤال أهل النار: ﴿كَمْ لَبِثْتُمْ فِي الْأَرْضِ عَدَدَ سِنِينَ﴾؟","answer":"يواجههم السؤال بمحدودية اللبث الذي اغتروا به وسرعة انقضائه، فيبدو لهم قصيرًا عند معاينة الآخرة. ويذكر المصدر أن اللبث يحتمل العمر في الدنيا والمكث في القبور؛ وفي الحالين يقلب السؤال تصورهم عن طول المقام واستبعاد البعث، ويقرر ضآلة ما مضى أمام ما آلوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص326–327، تحت عنوان «بلاغة الكناية في السؤال بـ﴿كم لبثتم في الأرض﴾»","url":""}]},{"id":"s23-94","number":94,"surah":23,"verses":[115],"references":[{"surah":23,"verses":[115]}],"verseLabel":"المؤمنون: 115","question":"ما بلاغة الاستفهام في قوله: ﴿أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا﴾؟","answer":"هو إنكاري توبيخي يكشف فساد ظنهم أن الخلق لا حكمة له ولا حساب بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص336، تحت عنوان «بلاغة الاستفهام في صدر الآية»","url":""}]},{"id":"s23-176","number":176,"surah":23,"verses":[115],"references":[{"surah":23,"verses":[115]}],"verseLabel":"المؤمنون: 115","question":"ما دلالة عطف قوله: ﴿وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ﴾؟","answer":"كشف العطف أن إنكار الرجوع للمحاسبة ملازم لظن العبث؛ فالخلق المقصود بالحكمة يقتضي العودة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص338، تحت عنوان «دلالة عطف جملة ﴿وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ﴾»","url":""}]},{"id":"s23-95","number":95,"surah":23,"verses":[116],"references":[{"surah":23,"verses":[116]}],"verseLabel":"المؤمنون: 116","question":"ما دلالة الفاء في قوله: ﴿فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ﴾؟","answer":"فرعت تنزيه الله على إبطال ظن العبث؛ فمن له الملك لا يكون فعله لعبًا ولا يترك خلقه بلا حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص343، تحت عنوان «دلالة الفاء في صدر الجملة»","url":""}]},{"id":"s23-177","number":177,"surah":23,"verses":[116],"references":[{"surah":23,"verses":[116]}],"verseLabel":"المؤمنون: 116","question":"ما فائدة وصف الله بـ﴿الْحَقِّ﴾ بعد ﴿الْمَلِكُ﴾؟","answer":"قرر أن ملكه ثابت كامل دائم، وأن ذاته وأفعاله منزهة عن الباطل والعبث؛ فليس ملكًا صوريًا أو زائلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص345، تحت عنوان «فائدة الوصف بـ﴿الْحَقِّ﴾ بعد ﴿الْمَلِكُ﴾»","url":""}]},{"id":"s23-96","number":96,"surah":23,"verses":[117],"references":[{"surah":23,"verses":[117]}],"verseLabel":"المؤمنون: 117","question":"ما فائدة جملة ﴿لَا بُرْهَانَ لَهُ بِهِ﴾ في وصف من يدعو إلهًا آخر؟","answer":"كشفت أن الشرك دعوى عارية من الحجة بطبيعتها، وليس المعنى أن دعاء غير الله قد يصح إذا وجد له برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص352–353، تحت عنوان «فائدة جملة ﴿لَا بُرْهَانَ لَهُ بِهِ﴾»","url":""}]},{"id":"s23-178","number":178,"surah":23,"verses":[117],"references":[{"surah":23,"verses":[117]}],"verseLabel":"المؤمنون: 117","question":"ما دلالة ﴿لَا﴾ النافية للجنس ولفظ ﴿بُرْهَانَ﴾؟","answer":"استغرقت ﴿لا﴾ نفي كل حجة، واختيار البرهان يطلب الدليل الواضح القاطع؛ ففضح اعتماد المشرك على الوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص353، تحت عنوان «دلالة استخدام ﴿لَا﴾ النافية للجنس، ولفظ ﴿بُرْهَانَ﴾»","url":""}]},{"id":"s23-97","number":97,"surah":23,"verses":[118],"references":[{"surah":23,"verses":[118]}],"verseLabel":"المؤمنون: 118","question":"ما فائدة الواو في افتتاح قوله: ﴿وَقُلْ رَبِّ اغْفِرْ وَارْحَمْ﴾؟","answer":"عطفت الدعاء بالمغفرة والرحمة على ما سبقه من ذكر الحساب، ففتحت باب الرجاء بعد بيان مصير المجرمين، وأمرت الرسول بإرشاد المؤمنين إلى الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص358، تحت عنوان «فائدة الواو في صدر الآية»","url":""}]},{"id":"s23-179","number":179,"surah":23,"verses":[118],"references":[{"surah":23,"verses":[118]}],"verseLabel":"المؤمنون: 118","question":"ما دلالة الواو والجملة الحالية في قوله: ﴿وَأَنْتَ خَيْرُ الرَّاحِمِينَ﴾؟","answer":"جعلت الواو الثناء حالًا مصاحبًا للدعاء، فصار وصف الله بخير الراحمين استرحامًا وتضرعًا واستحقاقًا للإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص359، تحت عنوان «دلالة الواو وفائدة الجملة الحالية»","url":""}]},{"id":"s23-180","number":180,"surah":23,"verses":[118],"references":[{"surah":23,"verses":[118]}],"verseLabel":"المؤمنون: 118","question":"ما دلالة إيثار الخيرية في قوله: ﴿خَيْرُ الرَّاحِمِينَ﴾؟","answer":"دل وصف الخيرية على أن رحمة الله تامة دائمة عامة، بخلاف رحمة المخلوق المحدودة الناقصة؛ ففيه تعظيم للرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص359–360، تحت عنوان «إيثار الخيرية في ﴿خَيْرُ الرَّاحِمِينَ﴾»","url":""}]},{"id":"s23-181","number":181,"surah":23,"verses":[1,117],"references":[{"surah":23,"verses":[1,117]}],"verseLabel":"المؤمنون: 1، 117","question":"ما سر إحاطة السورة بالفلاح: ﴿قد أفلح المؤمنون﴾ في مطلعها و﴿إنه لا يفلح الكافرون﴾ قرب ختامها؟","answer":"المطلع يثبت الفلاح للمؤمنين ويعقبه بصفاتهم العملية، والخاتمة تنفيه عن الكافرين بعد عرض دلائل التوحيد ومصائر المكذبين. فالسورة مبنية على مفاصلة واضحة بين طريقين ونتيجتين، وجاء وسطها مؤكدًا للمعنى نفسه: ﴿فأولئك هم المفلحون﴾. وهكذا يجمع التناسب بين البداية والوسط والنهاية محور السورة كله.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص5، مبحث: التناسب بين مفتتح سورة المؤمنون وخاتمتها، وسورة المؤمنون – فقرة: المناسبة بين بداية السورة ونهايتها. .","url":""}]},{"id":"s23-182","number":182,"surah":23,"verses":[2],"references":[{"surah":23,"verses":[2]}],"verseLabel":"المؤمنون: 2","question":"ما سر اختيار ﴿خاشعون﴾ في سورة المؤمنون، في حين جاء ﴿دائمون﴾ في سورة المعارج؟","answer":"الخشوع أوسع وأعلى من مجرد الدوام؛ فهو روح الصلاة، ويجمع عمل القلب والجوارح من التدبر والخضوع والسكون وغض البصر وترك الالتفات. والخاشع مستغرق في صلاته ملازم لها حتى يتمها، فدخل الدوام في الخشوع وزاد عليه. ولأن صفات المؤمنين هنا أعلى، اختير لهم الوصف الأكمل.","sources":[{"label":"فاضل السامرائي، «مقارنة بين صفات المؤمنين في سورتي المؤمنون والمعارج»، فقرة: خاشعون ودائمون.","url":""}]},{"id":"s23-183","number":183,"surah":23,"verses":[2,9],"references":[{"surah":23,"verses":[2,9]}],"verseLabel":"المؤمنون: 2، 9","question":"ما سر وصف المؤمنين بصيغ الأسماء: ﴿خاشعون﴾ و﴿معرضون﴾ و﴿فاعلون﴾ و﴿حافظون﴾ و﴿راعون﴾، بدل التعبير عنهم بالأفعال؟","answer":"صيغ أسماء الفاعلين تجعل هذه الخصال صفات راسخة ملازمة للمؤمنين، لا أفعالًا عارضة تقع مرة وتنقطع أخرى. فالجملة الاسمية أقوى في إفادة الثبوت والدوام من نحو: يخشعون أو يعرضون أو يحفظون. وبذلك يرسم المطلع شخصية المؤمن المستقرة على الطاعة، لا صاحب المواقف المؤقتة.","sources":[{"label":"فاضل السامرائي، سورة المؤمنون – بوابة إسلاميات، فقرة: دلالة صيغة اسم الفاعل في صفات المؤمنين.","url":""}]},{"id":"s23-184","number":184,"surah":23,"verses":[3],"references":[{"surah":23,"verses":[3]}],"verseLabel":"المؤمنون: 3","question":"ما سر التعبير بـ﴿عن اللغو معرضون﴾ بدل الاكتفاء بقول يفيد أنهم لا يلغون؟","answer":"عدم فعل اللغو لا يمنع صاحبه من الميل إليه أو حضور مجالسه والاستمتاع بسماعه، أما الإعراض فيصور تباعدًا كاملًا عنه: فعلًا وسماعًا وحضورًا وتسببًا. وجاءت العبارة اسمية لتفيد الثبات، وقُدِّم ﴿عن اللغو﴾ لإبراز شدة تنزههم عنه؛ فهم في ناحية واللغو في ناحية أخرى.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص10، مبحث: بلاغة «عن اللغو معرضون».","url":""}]},{"id":"s23-185","number":185,"surah":23,"verses":[9],"references":[{"surah":23,"verses":[9]}],"verseLabel":"المؤمنون: 9","question":"ما دلالة جمع ﴿صلواتهم﴾ في سورة المؤمنون، وإفراد ﴿صلاتهم﴾ في سورة المعارج؟","answer":"الجمع أعم وأشمل؛ إذ يتناول الصلوات المتعددة من فرائض ونوافل، فتكون المحافظة عليها أعلى وأوسع من المحافظة على الصلاة بصيغة الإفراد. وهذا يلائم علو الصفات المذكورة في سورة المؤمنون وكمالها، ولذلك جاء جزاؤهم أعلى كذلك: وراثة الفردوس والخلود فيه.","sources":[{"label":"فاضل السامرائي، «مقارنة بين صفات المؤمنين في سورتي المؤمنون والمعارج»، فقرة: صلواتهم وصلاتهم.","url":""}]},{"id":"s23-186","number":186,"surah":23,"verses":[10,11],"references":[{"surah":23,"verses":[10,11]}],"verseLabel":"المؤمنون: 10، 11","question":"ما سر الوعد بالفردوس والخلود في سورة المؤمنون، والاكتفاء بـ﴿جنات مكرمون﴾ في سورة المعارج؟","answer":"صفات المؤمنين هنا أكمل وأعلى: إيمان عام، وخشوع، وإعراض عن اللغو، وزكاة شاملة، ومحافظة على الصلوات بصيغة الجمع. فلما علت الصفات علا الجزاء، فخصهم بالفردوس وصرح بخلودهم فيه. أما سياق المعارج فذكر صفات دون هذه في العموم والكمال، فجاء الجزاء مناسبًا لها.","sources":[{"label":"فاضل السامرائي، «مقارنة بين صفات المؤمنين في سورتي المؤمنون والمعارج»، فقرة: الفردوس وجنات مكرمون.","url":""}]},{"id":"s23-187","number":187,"surah":23,"verses":[21],"references":[{"surah":23,"verses":[21]}],"verseLabel":"المؤمنون: 21","question":"ما سر عود الضمير مؤنثًا مجموعًا في ﴿مما في بطونها﴾، وعوده مذكرًا مفردًا في نظيرتها من سورة النحل: ﴿مما في بطونه﴾؟","answer":"سياق المؤمنون يعدد منافع الأنعام على سعتها: السقي والمنافع الكثيرة والأكل والحمل، فيشمل أنواعًا وأعدادًا أكثر، ذكورًا وإناثًا، فناسب ضمير الجمع المؤنث العائد إلى الأنعام. أما آية النحل فالمقام فيها على اللبن، وهو مما يختص بالإناث وفي أوقات مخصوصة، فكان مدلولها أضيق فناسبه الإفراد.","sources":[{"label":"فاضل السامرائي، مقطع باحث المباشر: «الفرق بين نسقيكم مما في بطونها ونسقيكم مما في بطونه».","url":""}]},{"id":"s23-188","number":188,"surah":23,"verses":[31,44],"references":[{"surah":23,"verses":[31,44]}],"verseLabel":"المؤمنون: 31، 44","question":"ما دلالة التناسب بين ﴿قرنًا﴾ و﴿رسولًا﴾، ثم بين ﴿قرونًا﴾ و﴿رسلنا﴾؟","answer":"حين ذكر قرنًا واحدًا قال: ﴿فأرسلنا فيهم رسولًا﴾، فطابق الواحدُ الواحدَ. ثم لما اتسع الحديث إلى ﴿قرونًا آخرين﴾ قال: ﴿ثم أرسلنا رسلنا تترى﴾، فطابق الجمعُ الجمعَ. وهذا التناسق العددي يصور تعاقب الأمم وتعاقب رسلها، وتؤكده ﴿تترى﴾ بمعنى متتابعين بعضهم إثر بعض.","sources":[{"label":"فاضل السامرائي، «قرنًا آخرين وقرونًا آخرين»، فقرة: مطابقة القرن للرسول والقرون للرسل.","url":""}]},{"id":"s23-189","number":189,"surah":23,"verses":[37],"references":[{"surah":23,"verses":[37]}],"verseLabel":"المؤمنون: 37","question":"ما سر تفصيل مقالة المنكرين هنا بقولهم ﴿نموت ونحيا﴾، وحذف هذا التفصيل في نظيرتها من سورة الأنعام؟","answer":"هذا من مراعاة مقامي الإيجاز والتفصيل. ففي سورة المؤمنون نقل السياق محاجة القوم ومقولاتهم مفصلة، فبسط إنكارهم للحياة الآخرة بقوله ﴿نموت ونحيا﴾. أما في الأنعام فجاء القول منقولًا بإيجاز في سياق الحديث عن موقفهم من البعث، فاقتصر على ﴿إن هي إلا حياتنا الدنيا وما نحن بمبعوثين﴾.","sources":[{"label":"فاضل السامرائي، «إن هي إلا حياتنا الدنيا نموت ونحيا»، الآية 37 من سورة المؤمنون.","url":""}]},{"id":"s23-190","number":190,"surah":23,"verses":[52],"references":[{"surah":23,"verses":[52]}],"verseLabel":"المؤمنون: 52","question":"ما سر مجيء ﴿فاتقون﴾ في سورة المؤمنون، في مقابل ﴿فاعبدون﴾ في سورة الأنبياء؟","answer":"سورة الأنبياء أبرزت عبودية الأنبياء وإخلاصهم، وتكرر فيها ذكر العبادة، فناسبها ﴿فاعبدون﴾. أما سورة المؤمنون فجاء الأمر بالتقوى بعد الأمر بالعبادة والعمل الصالح، ثم أعقبه التحذير من التفرق: ﴿فتقطعوا أمرهم بينهم زبرًا﴾. فكانت التقوى أنسب بسياق حفظ وحدة الدين واجتناب أسباب التفرق.","sources":[{"label":"فاضل السامرائي، «وأنا ربكم فاعبدون – وأنا ربكم فاتقون».","url":""}]},{"id":"s23-191","number":191,"surah":23,"verses":[60],"references":[{"surah":23,"verses":[60]}],"verseLabel":"المؤمنون: 60","question":"ما دقة اختيار ﴿وجلة﴾ لوصف قلوب المؤمنين وهم يقدمون الطاعات؟","answer":"الوجل ليس مجرد خوف عام، بل اضطراب باطني يختص بالقلب ويبلغ أثره الجسد كالقشعريرة. ولذلك لم يسند الوجل في الاستعمال القرآني إلى جارحة أخرى، وإنما إلى القلب أو إلى الشخص من جهة قلبه. فالصورة تجمع العمل الصالح مع قلب شديد المراقبة، يخشى الرجوع إلى الله وألا يقبل منه.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين الخشية والخوف والوجل؟»، فقرة: ﴿وقلوبهم وجلة﴾.","url":""}]},{"id":"s23-192","number":192,"surah":23,"verses":[84,89],"references":[{"surah":23,"verses":[84,89]}],"verseLabel":"المؤمنون: 84، 89","question":"ما سر الجواب بـ﴿لله﴾ في محاجة سورة المؤمنون، وبـ﴿الله﴾ في نظيرتها من سورة الرعد؟","answer":"سياق المؤمنون قائم على الملكية: ﴿لمن الأرض ومن فيها﴾ و﴿من بيده ملكوت كل شيء﴾، فجاء الجواب بلام الملك: ﴿لله﴾. أما آية الرعد فالمقام فيها تعريف الذات الإلهية وتقرير التوحيد: ﴿قل من رب السماوات والأرض﴾، فجاء الجواب بالاسم مباشرة: ﴿قل الله﴾. فكل جواب صيغ على مقتضى السؤال وسياقه.","sources":[{"label":"فاضل السامرائي، مقطع باحث المباشر: «قل لمن الأرض ومن فيها… لماذا لله وليس الله؟».","url":""}]},{"id":"s23-193","number":193,"surah":23,"verses":[99],"references":[{"surah":23,"verses":[99]}],"verseLabel":"المؤمنون: 99","question":"ما دلالة التعبير بـ﴿جاء أحدهم الموت﴾، لا بما يفيد مجرد حضور الموت؟","answer":"المجيء يتضمن القرب الشديد وتحقق الوقوع، ويستعمل حين يكون الكلام على الموت نفسه وأحوال الإنسان عند مفارقة الروح. أما الحضور فيرد غالبًا في مقام الوصايا والأحكام، حيث يكون الموت قريبًا شاهدًا ولم تنفذ المفارقة بعد. وهنا طلب الرجوع دليل على أن الإنسان خرج من الدنيا، فناسب ﴿جاء﴾.","sources":[{"label":"فاضل السامرائي، تفسير الآية 99 من سورة المؤمنون، فقرة: الفرق بين «جاء الموت» و«حضر الموت».","url":""}]},{"id":"s23-194","number":194,"surah":23,"verses":[100],"references":[{"surah":23,"verses":[100]}],"verseLabel":"المؤمنون: 100","question":"ما سر تسمية قوله الطويل ﴿رب ارجعون لعلي أعمل صالحًا فيما تركت﴾ بـ﴿كلمة﴾؟","answer":"أطلقت الكلمة وأريد بها الكلام كله، وهو مجاز مرسل يطلق فيه الجزء ويراد به الكل. وفي هذا الاختزال تهوين لأمنيته المتأخرة: فما قاله، على طوله وحرارته، لا يتجاوز لفظًا يردده ولا يغير المصير. فجاءت ﴿كلمة﴾ لتسقط عنه قيمة الفعل والجدوى بعد انقضاء زمن العمل.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين الكلم والكلام؟»، فقرة: ﴿إنها كلمة هو قائلها﴾.","url":""}]},{"id":"s23-195","number":195,"surah":23,"verses":[19],"references":[{"surah":23,"verses":[19]}],"verseLabel":"المؤمنون: 19","question":"ما سر دخول الواو في ﴿ومنها تأكلون﴾، وحذفها من نظيرتها في قوله عن فاكهة الجنة: ﴿منها تأكلون﴾؟","answer":"فاكهة الدنيا لا تقتصر منافعها على الأكل؛ فمنها ما يدخر ويباع ويعصر ويصنع، فكأن التعبير عطف الأكل على منافع محذوفة مفهومة: ومنها تدخرون، ومنها تعصرون، ومنها تأكلون. أما فاكهة الجنة فسيقت للأكل والنعيم المباشر، فلم يحتج السياق إلى الواو العاطفة على مقدر.","sources":[{"label":"فاضل السامرائي، «ذكر الواو في ومنْها تأكلون وحذفها في منها تأكلون»، الآية 19 من المؤمنون.","url":""}]},{"id":"s23-196","number":196,"surah":23,"verses":[31],"references":[{"surah":23,"verses":[31]}],"verseLabel":"المؤمنون: 31","question":"ما سر وصف المفرد ﴿قرنًا﴾ بالجمع ﴿آخرين﴾ في قوله: ﴿ثم أنشأنا من بعدهم قرنًا آخرين﴾؟","answer":"المراد بالقرن هنا جماعة الناس الذين عاشوا في زمن واحد، فهو مفرد في اللفظ لكنه جمع في المعنى. لذلك روعي معناه فقيل ﴿آخرين﴾، كما يراعى في العربية معنى أسماء الجموع. فالمطابقة هنا معنوية، وهي تكشف أن الحديث عن أمة كاملة لا عن زمن مجرد.","sources":[{"label":"فاضل السامرائي، «قرنًا آخرين وقرونًا آخرين»، الآيتان 31 و42 من سورة المؤمنون.","url":""}]},{"id":"s23-197","number":197,"surah":23,"verses":[78],"references":[{"surah":23,"verses":[78]}],"verseLabel":"المؤمنون: 78","question":"ما سر قوله هنا ﴿قليلًا ما تشكرون﴾، في حين جاء في سورة النحل ﴿لعلكم تشكرون﴾ بعد ذكر السمع والأبصار والأفئدة؟","answer":"آية النحل تتحدث عن عموم الخلق وغاية منح هذه الحواس، فجاء الرجاء المتعلق بحصول الشكر: ﴿لعلكم تشكرون﴾. أما سياق المؤمنون فسبقه قوم لم يستكينوا ولم يتضرعوا حتى نزل بهم العذاب؛ أي إن عدم شكرهم قد ظهر بالفعل. لذلك واجههم التعبير بالحقيقة الواقعة: ﴿قليلًا ما تشكرون﴾.","sources":[{"label":"فاضل السامرائي، تفسير الآية 78 من سورة المؤمنون، فقرة: «قليلًا ما تشكرون» و«لعلكم تشكرون».","url":""}]},{"id":"s23-198","number":198,"surah":23,"verses":[91],"references":[{"surah":23,"verses":[91]}],"verseLabel":"المؤمنون: 91","question":"ما دلالة النفي بـ﴿ما اتخذ الله من ولد﴾ هنا، وبـ﴿لم يتخذ ولدًا﴾ في مواضع أخرى؟","answer":"﴿ما اتخذ﴾ تأتي هنا في مقام الرد على دعوى واقعة؛ فالمشركون قالوا باتخاذ الولد، فجاء النفي مقابلًا لقولهم ومكذبًا له. أما ﴿لم يتخذ﴾ في نحو الإسراء والفرقان فتأتي في مقام الإخبار والتعليم ابتداءً، لا في سياق محاجة قول مذكور. فاختلاف أداة النفي تابع لاختلاف المقام الخطابي.","sources":[{"label":"فاضل السامرائي، تفسير الآية 91 من سورة المؤمنون، فقرة: «فعل/لم يفعل، لقد فعل/ما فعل».","url":""}]},{"id":"s23-199","number":199,"surah":23,"verses":[109,118],"references":[{"surah":23,"verses":[109,118]}],"verseLabel":"المؤمنون: 109، 118","question":"ما سر اختيار ﴿خير الراحمين﴾ في السورة، ومجيء ﴿خير الغافرين﴾ في مقام آخر؟","answer":"إذا صرح السياق بالذنب ناسب أن يعقب بالمغفرة، كما في دعاء موسى بعد ذكر فعل السفهاء: ﴿وأنت خير الغافرين﴾. أما في سورة المؤمنون فمحور الدعاء هو الإيمان وطلب الرحمة، ولم يتقدم تصريح بذنب معين، فناسب ﴿خير الراحمين﴾. والرحمة حاضرة في الحالين، لكن خاتمة كل مقام أبرزت المعنى الغالب عليه.","sources":[{"label":"فاضل السامرائي، «وأنت خير الراحمين وأنت خير الغافرين»، الآية 109 من سورة المؤمنون.","url":""}]},{"id":"s24-1","number":1,"surah":24,"verses":[1],"references":[{"surah":24,"verses":[1]}],"verseLabel":"النور: 1","question":"ما مقاصد تنكير ﴿سُورَةٌ﴾ في افتتاح سورة النور؟","answer":"التنكير للتفخيم والتنويه بعظمة السورة وما فيها من أحكام، ويثير التشوق إلى تلقي ما يأتي بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص378، تحت عنوان «مقاصد تنكير ﴿سُورَةٌ﴾»","url":""}]},{"id":"s24-98","number":98,"surah":24,"verses":[1],"references":[{"surah":24,"verses":[1]}],"verseLabel":"النور: 1","question":"ما بلاغة وصف سورة النور بعدة صفات في مطلعها؟","answer":"تتابع أوصاف الإنزال والفرض وإبانة الآيات لتهيئة النفوس للعمل بأحكام السورة، والتنويه بأنها وحي ملزم واضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص383، تحت عنوان «بلاغة وصف السورة بعدة صفات»","url":""}]},{"id":"s24-2","number":2,"surah":24,"verses":[1],"references":[{"surah":24,"verses":[1]}],"verseLabel":"النور: 1","question":"ما دلالة الجمع بين ﴿أَنْزَلْنَاهَا﴾ و﴿فَرَضْنَاهَا﴾ مع أن الإنزال يشمل أحكام السورة؟","answer":"يصرح عطف الفرض بأن المقصود ليس مجرد نزول السورة، بل إنزالها ليُمتثل ما فيها من أحكام وآداب. وقُدّم الإنزال لأن فرض العمل بما نزل متفرع عليه وتابع له.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص380، تحت عنوان «دلالة العطف بجمع الفرض مع الإنزال وسر تقديم الإنزال عليه»","url":""}]},{"id":"s24-3","number":3,"surah":24,"verses":[1],"references":[{"surah":24,"verses":[1]}],"verseLabel":"النور: 1","question":"ما سر وصف آيات سورة النور بأنها ﴿بَيِّنَاتٍ﴾؟","answer":"ينوه الوصف بوضوح الآيات ودلالة أحكامها في نفسها، وأنها ترفع الجهل والالتباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص383، تحت عنوان «سر وصف الآيات بـ﴿بَيِّنَاتٍ﴾»","url":""}]},{"id":"s24-99","number":99,"surah":24,"verses":[1],"references":[{"surah":24,"verses":[1]}],"verseLabel":"النور: 1","question":"ما توجيه قراءتي قوله: ﴿آيَاتٍ مُبَيِّنَاتٍ﴾؟","answer":"على كسر الياء تكون الآيات مبينة للناس ما يحتاجون إليه، وعلى فتحها يكون الله قد بينها وجعلها واضحة؛ فتجمع القراءتان الإبانة والوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص119، تحت عنوان «توجيه قراءتي قوله: ﴿مُبَيِّنَاتٍ﴾»","url":""}]},{"id":"s24-4","number":4,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما دلالة تقديم ﴿الزَّانِيَةُ﴾ على ﴿الزَّانِي﴾؟","answer":"جاء التقديم في مقام تغليظ الزجر، ومن وجوهه ظهور أثر الفاحشة في المرأة بالحمل والتحذير من أن تحمل الرقة عليها على تعطيل الحكم؛ ولا يغير مساواة الطرفين في العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص390–391، تحت عنوان «دلالة تقديم في قوله تعالى ﴿الزَّانِيَةُ وَالزَّانِي﴾»","url":""}]},{"id":"s24-100","number":100,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما بلاغة التعبير بقوله: ﴿كُلَّ وَاحِدٍ مِنْهُمَا﴾؟","answer":"أكد لفظ العموم استقلال كل من الزانية والزاني بالعقوبة، وجاء التذكير في ﴿واحد﴾ على التغليب مع مساواتهما في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص394، تحت عنوان «بلاغة التعبير بالتغليب ﴿وَاحِدٍ﴾»","url":""}]},{"id":"s24-5","number":5,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما دلالة التعبير باسم الفاعل في قوله تعالى: ﴿الزَّانِيَةُ وَالزَّانِي﴾؟","answer":"يُلحظ هنا اتصاف الشخص بالفعل عند التلبس به؛ فاسم الفاعل في هذا السياق قريب من معنى «التي تزني والذي يزني». فلا يلزم من الصيغة أن تكون الفاحشة عادة راسخة متكررة، بل عُلّق الحكم على حصول الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص392، تحت عنوان «دلالة التعبير باسم الفاعل»","url":""}]},{"id":"s24-6","number":6,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما سر اختيار ﴿فَاجْلِدُوا﴾ بدل «فاضربوا»؟","answer":"«الجلد» أخص من مطلق الضرب؛ إذ يتصل بظاهر البدن وجلده. وفي اختياره، بحسب المصدر، إدماج لمعنى الاعتدال في العقوبة وألا تكون ضربًا مبرحًا يمزق الجلد؛ فالكلمة تحمل دلالة لا يؤديها لفظ الضرب المطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص393–394، تحت عنوان «بلاغة الإدماج باستخدام لفظ (الجلد) مادة وصيغة»","url":""}]},{"id":"s24-7","number":7,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما دلالة اختيار ﴿رَأْفَةٌ﴾ دون «رحمة» في قوله تعالى: ﴿وَلَا تَأْخُذْكُمْ بِهِمَا رَأْفَةٌ فِي دِينِ اللَّهِ﴾؟","answer":"الرأفة شدة الرحمة ورقتها، وقد تحمل صاحبها على دفع الألم في الحال. فالنهي متوجه إلى الرقة التي تفضي إلى ترك الحكم أو التهاون فيه، لا إلى إلغاء أصل الرحمة التي جُبلت عليها القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص397، تحت عنوان «دلالة التعبير بـ﴿رأفة﴾ دون(رحمة)»","url":""}]},{"id":"s24-8","number":8,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما سر الاعتراض بقوله: ﴿إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ﴾؟","answer":"الشرط للتحريض والتغليظ لا للتشكيك في إيمانهم؛ فاستنهض ما في نفوسهم من إيمان لحملهم على امتثال الحكم بلا رأفة تعطل الحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص398، تحت عنوان «سر الاعتراض بجملة الشرط ﴿إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ﴾»","url":""}]},{"id":"s24-101","number":101,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما دلالة عطف الإيمان باليوم الآخر على الإيمان بالله؟","answer":"جمع أصل التكليف بمراقبة الله مع استحضار الحساب والجزاء على التهاون، فاشتد باعث الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص399، تحت عنوان «دلالة عطف الإيمان باليوم الآخر على الإيمان بالله»","url":""}]},{"id":"s24-9","number":9,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما سر اختيار الشهادة في قوله: ﴿وَلْيَشْهَدْ عَذَابَهُمَا﴾؟","answer":"تفيد حضور إقامة الحد ومعاينته، فتحقق علانيته وتعين على الردع والاعتبار ومعرفة إقامته من غير زيادة أو نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص400، تحت عنوان «سر اصطفاء الشهادة مادة وصيغة»","url":""}]},{"id":"s24-102","number":102,"surah":24,"verses":[2],"references":[{"surah":24,"verses":[2]}],"verseLabel":"النور: 2","question":"ما غرض تنكير الفاعل ﴿طَائِفَةٌ﴾؟","answer":"ترك العدد والصفات غير معينين؛ فالمقصود جماعة من المؤمنين يحصل بحضورها الشهود والعظة، لا عدد يحدده اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص401، تحت عنوان «الغرض من تنكير الفاعل ﴿طَائِفَةٌ﴾»","url":""}]},{"id":"s24-10","number":10,"surah":24,"verses":[3],"references":[{"surah":24,"verses":[3]}],"verseLabel":"النور: 3","question":"ما بلاغة القصر في قوله: ﴿الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً﴾؟","answer":"يبرز القصر التناسب بين من اتخذوا الفجور عادة، ويبالغ في التنفير من الاقتران بهم والزجر عن مسلكهم، على ما يغلب من أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص409–410، تحت عنوان «بلاغة التعبير بأسلوب القصر»","url":""}]},{"id":"s24-103","number":103,"surah":24,"verses":[3],"references":[{"surah":24,"verses":[3]}],"verseLabel":"النور: 3","question":"ما بلاغة التمهيد في جملة ﴿الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةً﴾؟","answer":"مهد التصوير بما فيه من نفرة اجتماعية للحكم اللاحق بالتحريم، فسبق التقرير النفسي والتقبيحُ الإلزامَ التشريعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص410، تحت عنوان «بلاغة التمهيد في الجملة السابقة»","url":""}]},{"id":"s24-11","number":11,"surah":24,"verses":[4],"references":[{"surah":24,"verses":[4]}],"verseLabel":"النور: 4","question":"ما دلالة اشتراط ﴿أَرْبَعَةِ شُهَدَاءَ﴾ في سياق القذف؟","answer":"في هذا التقييد تشديد على القاذف ورحمة بالعباد وستر لأعراضهم؛ فالفاحشة مما يُتستر به، فلا يُفتح باب اتهام الناس بها بغير بينة. ويقابل ذلك صيانة المجتمع من تداول التهم بلا تثبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص420، تحت عنوان «سر التقييد بالجار والمجرور ﴿بأربعة﴾»","url":""}]},{"id":"s24-12","number":12,"surah":24,"verses":[4],"references":[{"surah":24,"verses":[4]}],"verseLabel":"النور: 4","question":"ما دلالة عطف قوله: ﴿وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا﴾ على الجلد؟","answer":"جمع العطف للقاذف بين العقوبة البدنية ورد الاعتبار لقوله؛ فمَن آذى الناس بلسانه عوقب في بدنه وأسقطت الثقة بشهادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص421، تحت عنوان «دلالة عطف جملة ﴿وَلَا تَقْبَلُوا﴾ على ما قبلها»","url":""}]},{"id":"s24-104","number":104,"surah":24,"verses":[4],"references":[{"surah":24,"verses":[4]}],"verseLabel":"النور: 4","question":"ما دلالة التذييل بقوله: ﴿وَأُولَئِكَ هُمُ الْفَاسِقُونَ﴾؟","answer":"قرر سوء حال القاذفين وخروجهم عن الطاعة، وجاء الضمير والقصر لتغليظ وصفهم وإكمال الزجر بعد الجلد ورد الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص422، تحت عنوان «دلالة التذييل بجملة العطف ﴿وَأُولَئِكَ هُمُ الْفَاسِقُونَ﴾»","url":""}]},{"id":"s24-13","number":13,"surah":24,"verses":[5],"references":[{"surah":24,"verses":[5]}],"verseLabel":"النور: 5","question":"ما دلالة الاستثناء في قوله: ﴿إِلَّا الَّذِينَ تَابُوا مِنْ بَعْدِ ذَلِكَ﴾؟","answer":"فتح الاستثناء باب الرجوع بعد الوعيد، وتعلقه بقبول الشهادة أو وصف الفسق محل خلاف؛ أما التوبة الصادقة فترفع الإصرار على الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص423–424، تحت عنوان «دلالة الاستثناء في صدر الآية، وعلاقته بالحكم عليهم بالفسق»","url":""}]},{"id":"s24-105","number":105,"surah":24,"verses":[5],"references":[{"surah":24,"verses":[5]}],"verseLabel":"النور: 5","question":"ما فائدة عطف الإصلاح على التوبة؟","answer":"بين أن التوبة ليست قولًا مجردًا، بل يظهر صدقها في إصلاح السلوك وإزالة أثر الذنب قدر الاستطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص424، تحت عنوان «فائدة عطف الإصلاح على التوبة»","url":""}]},{"id":"s24-14","number":14,"surah":24,"verses":[6],"references":[{"surah":24,"verses":[6]}],"verseLabel":"النور: 6","question":"ما دلالة الفاء في قوله: ﴿فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ﴾؟","answer":"فرعت الفاء حكم اللعان على تعذر الشهود، فدل الترتيب على أن أيمان الزوج تقوم مقام البينة عند خصوص هذا العجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص437، تحت عنوان «دلالة الفاء في ﴿فَشَهَادَةُ﴾»","url":""}]},{"id":"s24-106","number":106,"surah":24,"verses":[6],"references":[{"surah":24,"verses":[6]}],"verseLabel":"النور: 6","question":"ما بلاغة المجاز في تسمية اليمين شهادة في آيات اللعان؟","answer":"سميت الأيمان شهادة لأنها نابت مناب شهادة الشهود في هذا الموضع، فهو مجاز مرسل بعلاقة الحلول الاعتباري.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص436–437، تحت عنوان «بلاغة التعبير بالمجاز في التعبير عن اليمين بالشهادة»","url":""}]},{"id":"s24-15","number":15,"surah":24,"verses":[6,7,8,9],"references":[{"surah":24,"verses":[6,7,8,9]}],"verseLabel":"النور: 6-9","question":"ما نكتة تحديد شهادات اللعان بأربع؟","answer":"جعلت الأيمان الأربع قائمة مقام الشهود الأربعة الذين يتطلبهم حكم القذف، فناسب عدد الشهادات عدد البينة المتعذرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص438، تحت عنوان «نكتة تحديد عدد الشهادات بالأربع»","url":""}]},{"id":"s24-107","number":107,"surah":24,"verses":[6,7,8,9],"references":[{"surah":24,"verses":[6,7,8,9]}],"verseLabel":"النور: 6-9","question":"ما دلالة عطف الشهادة الخامسة في لعان الزوج؟","answer":"الخامسة ليست شاهدًا آخر، بل تغليظ للأيمان السابقة واستحضار لعاقبة الكذب بالدعاء على النفس بلعنة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص439–440، تحت عنوان «دلالة عطف الشهادة الخامسة»","url":""}]},{"id":"s24-108","number":108,"surah":24,"verses":[6,7,8,9],"references":[{"surah":24,"verses":[6,7,8,9]}],"verseLabel":"النور: 6-9","question":"ما دلالة عطف الشهادة الخامسة في لعان الزوجة؟","answer":"قوّت الخامسة أيمان المرأة الأربع واستحضرت غضب الله عليها إن كان الزوج صادقًا، فزادت الردع والتغليظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص449–450، تحت عنوان «دلالة عطف الشهادة الخامسة»","url":""}]},{"id":"s24-16","number":16,"surah":24,"verses":[9],"references":[{"surah":24,"verses":[9]}],"verseLabel":"النور: 9","question":"لماذا عُينت اللعنة للرجل في الخامسة من اللعان؟","answer":"من وجوهه أن كذبه افتراء يعرّض زوجته للطرد والنبذ، فناسبه الدعاء عليه باللعنة والطرد من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص441، تحت عنوان «إيثار تعيين اللعنة للرجل هنا، والغضب للمرأة في الآية الموالية»","url":""}]},{"id":"s24-109","number":109,"surah":24,"verses":[9],"references":[{"surah":24,"verses":[9]}],"verseLabel":"النور: 9","question":"لماذا اختير الغضب للمرأة في الخامسة بدل اللعنة؟","answer":"من وجوهه أن كذبها يجمع الفاحشة وإنكارها، وأن الغضب أبلغ في التخويف عند من اعتاد سماع اللعن؛ وهي توجيهات تفسيرية لا علة مقطوعًا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص451–452، تحت عنوان «سر اصطفاء الغضب للمرأة بدلا من اللعنة»","url":""}]},{"id":"s24-17","number":17,"surah":24,"verses":[10],"references":[{"surah":24,"verses":[10]}],"verseLabel":"النور: 10","question":"ما دلالة حذف جواب ﴿وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ﴾؟","answer":"حُذف الجواب لتهويل ما كان سيقع لولا الفضل والرحمة، ولتتسع النفس في تقديره بحسب المقام: من فضيحة أو عقوبة أو حرج لا مخرج منه. فتركه غير مصرّح به أبلغ في تعظيم نعمة الله التي دفعت هذه العواقب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص457، تحت عنوان «الغرض من حذف جواب ﴿لولا﴾»","url":""}]},{"id":"s24-18","number":18,"surah":24,"verses":[11],"references":[{"surah":24,"verses":[11]}],"verseLabel":"النور: 11","question":"ما دلالة التعبير عن أهل الإفك بلفظ ﴿عُصْبَةٌ﴾؟","answer":"يصورهم جماعة يشد بعضها بعضًا وتتعاون على ترويج الإفك، وفي اللفظ تحقير لشأنهم أمام من طهرهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص469، تحت عنوان «دلالة التعبير بـ﴿عُصْبَةٌ﴾»","url":""}]},{"id":"s24-110","number":110,"surah":24,"verses":[11],"references":[{"surah":24,"verses":[11]}],"verseLabel":"النور: 11","question":"ما معنى (من) ونكتة وصف العصبة بأنها ﴿مِنْكُمْ﴾؟","answer":"تفيد ﴿من﴾ أن الأذى صدر من داخل جماعة المسلمين، فزاد ذلك التوبيخ لمخالفة مقتضى أخوة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص469–470، تحت عنوان «معنى (من) ونكتة وصف العصبة بأنها ﴿مِنْكُمْ﴾»","url":""}]},{"id":"s24-19","number":19,"surah":24,"verses":[11],"references":[{"surah":24,"verses":[11]}],"verseLabel":"النور: 11","question":"ما غرض النهي في قوله: ﴿لَا تَحْسَبُوهُ شَرًّا لَكُمْ﴾؟","answer":"نهى عن الوقوف عند ألم المحنة العاجل، ووجّه إلى ما ترتب عليها من ثواب الصبر ونزول البراءة وظهور فضل المظلومين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص470، تحت عنوان «غرض النهي في قوله: ﴿لَا تَحْسَبُوهُ شَرًّا لَكُمْ﴾»","url":""}]},{"id":"s24-111","number":111,"surah":24,"verses":[11],"references":[{"surah":24,"verses":[11]}],"verseLabel":"النور: 11","question":"ما فائدة الإضراب بقوله: ﴿بَلْ هُوَ خَيْرٌ لَكُمْ﴾؟","answer":"أبطل تقدير الشر الخالص وأثبت خير العاقبة، فأزال مرارة الحادثة من النفوس من غير أن يجعل فعل الإفك نفسه خيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص471، تحت عنوان «فائدة الإضراب بقوله: ﴿بَلْ هُوَ خَيْرٌ لَكُمْ﴾»","url":""}]},{"id":"s24-20","number":20,"surah":24,"verses":[11],"references":[{"surah":24,"verses":[11]}],"verseLabel":"النور: 11","question":"ما دلالة اختيار ﴿اكْتَسَبَ﴾ بدل «كسب» في وصف إثم أهل الإفك؟","answer":"الاكتساب أخص بما يجلبه المرء لنفسه، وصيغة الافتعال تلائم الاعتمال والقصد. فالتعبير يصورهم متحملين إثمًا تعمدوا تحصيله لأنفسهم، وهو أبلغ في الترتب والمسؤولية من مجرد الكسب العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص475، تحت عنوان «دلالة التعبير بـ﴿اكتسب﴾ مادة وصيغة»","url":""}]},{"id":"s24-21","number":21,"surah":24,"verses":[12],"references":[{"surah":24,"verses":[12]}],"verseLabel":"النور: 12","question":"ما دلالة قوله تعالى: ﴿ظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بِأَنْفُسِهِمْ خَيْرًا﴾ بدل الاقتصار على «بإخوانهم»؟","answer":"من توجيهاته تنزيل أهل الإيمان منزلة النفس الواحدة: ما يصيب عرض بعضهم فكأنه يصيب الجميع، فينبغي أن يصون المؤمن أخاه كما يصون نفسه. ويحتمل أيضًا أن ينظر كل سامع إلى نفسه: أيرضى لها مثل هذا الاتهام؟ فيكون ذلك باعثًا على حسن الظن بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص487، تحت عنوان «دلالة قوله: ﴿بأنفسهم﴾»","url":""}]},{"id":"s24-22","number":22,"surah":24,"verses":[12],"references":[{"surah":24,"verses":[12]}],"verseLabel":"النور: 12","question":"ما غرض تقديم ﴿إِذْ سَمِعْتُمُوهُ﴾ على عامله؟","answer":"دل التقديم على أن حسن الظن وإنكار الإفك مطلوبان من لحظة سماعه، قبل الخوض فيه أو إشاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص485، تحت عنوان «غرض تقديم الظرف ﴿إِذْ سَمِعْتُمُوهُ﴾ على عامله»","url":""}]},{"id":"s24-112","number":112,"surah":24,"verses":[12],"references":[{"surah":24,"verses":[12]}],"verseLabel":"النور: 12","question":"ما نكتة وصف الإفك بأنه ﴿مُبِينٌ﴾؟","answer":"أعلن الوصف ظهور كذبه ووضوح بطلانه لمن استصحب البراءة ولم يجعل دعوى بلا بينة علمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص488–489، تحت عنوان «نكتة وصف الإفك بأنه ﴿مُبِينٌ﴾»","url":""}]},{"id":"s24-23","number":23,"surah":24,"verses":[13],"references":[{"surah":24,"verses":[13]}],"verseLabel":"النور: 13","question":"لماذا عُين الشهداء في حديث الإفك بأربعة؟","answer":"طبق السياق ميزان القذف المقرر في أول السورة على الإفك نفسه؛ فلا تغني كثرة الناقلين عن البينة المؤلفة من أربعة شهداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص493، تحت عنوان «نكتة التعيين للشهداء بهذا العدد»","url":""}]},{"id":"s24-113","number":113,"surah":24,"verses":[13],"references":[{"surah":24,"verses":[13]}],"verseLabel":"النور: 13","question":"ما نكتة فصل قوله: ﴿لَوْلَا جَاءُوا عَلَيْهِ بِأَرْبَعَةِ شُهَدَاءَ﴾ عما قبله؟","answer":"جاءت الجملة استئنافًا للتوبيخ وبيان الميزان الذي كان ينبغي رد الخبر إليه، بعد لومهم على تلقيه وإشاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص491، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s24-24","number":24,"surah":24,"verses":[14],"references":[{"surah":24,"verses":[14]}],"verseLabel":"النور: 14","question":"كيف وُجه اختلاف مواضع ﴿وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ﴾ في سورة النور؟","answer":"يتجدد الامتنان بتجدد المقام: مرة في اللعان، ومرة في دفع عذاب الإفك، ومرة في حفظ أخلاق الجماعة؛ ولذلك تختلف الأجوبة المقدرة بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص460–461، تحت عنوان «توجيه المتشابه اللفظي في الآية الكريمة ونظيراتها في السورة الكريمة»","url":""}]},{"id":"s24-114","number":114,"surah":24,"verses":[14],"references":[{"surah":24,"verses":[14]}],"verseLabel":"النور: 14","question":"ما نكتة تكرار ﴿لَوْلَا﴾ في آيات الإفك؟","answer":"كرر الشرط ليجدد التنبيه إلى فضل الله ورحمته عند كل جرم وآثاره، وحذف الجواب أحيانًا ليتسع لكل ما دفعه الله من العقوبة والفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص536، تحت عنوان «نكتة تكرار (لولا) في الآيات»","url":""}]},{"id":"s24-25","number":25,"surah":24,"verses":[15],"references":[{"surah":24,"verses":[15]}],"verseLabel":"النور: 15","question":"ما دلالة التعبير بـ﴿تَلَقَّوْنَهُ بِأَلْسِنَتِكُمْ﴾ مع أن تلقي الأخبار يكون بالسمع؟","answer":"جُعلت الألسنة آلة التلقي تصويرًا لحرصهم على الخبر وسرعة نقله؛ فكأنه لا يمر إلا من لسان إلى لسان، دون روية وتثبت. وفي هذه الصورة توبيخ لمن يبادر إلى إذاعة ما يسمع قبل أن يعلم حقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص508، تحت عنوان «بلاغة المجاز ﴿تلقونه بألسنتكم﴾»","url":""}]},{"id":"s24-26","number":26,"surah":24,"verses":[15],"references":[{"surah":24,"verses":[15]}],"verseLabel":"النور: 15","question":"ما نكتة التقييد بقوله: ﴿وَهُوَ عِنْدَ اللَّهِ عَظِيمٌ﴾؟","answer":"صحح القيد مقياسهم البشري؛ فما حسبوه هينًا عظيم في حكم الله، والعبرة بميزانه لا بسهولة تناقل القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص511، تحت عنوان «نكتة التقييد بقوله: ﴿عِنْدَ اللَّهِ﴾»","url":""}]},{"id":"s24-115","number":115,"surah":24,"verses":[15],"references":[{"surah":24,"verses":[15]}],"verseLabel":"النور: 15","question":"ما فائدة وصف حديث الإفك بالعظم؟","answer":"هول الوصف شأن الاعتداء على العرض وآثاره في الفرد والجماعة، ومنع الاستهانة به لمجرد أنه كلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص511، تحت عنوان «فائدة وصف الحديث بالإفك بالعظم»","url":""}]},{"id":"s24-27","number":27,"surah":24,"verses":[16],"references":[{"surah":24,"verses":[16]}],"verseLabel":"النور: 16","question":"ما الموقع البياني لقوله: ﴿سُبْحَانَكَ﴾ في إنكار الإفك؟","answer":"جاءت جملة اعتراضية للتعجب القائم على تنزيه الله، وأظهرت شدة نفرة النفس من قبول هذا القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص517، تحت عنوان «الموقع النحوي والبياني لقوله: ﴿سُبْحَانَكَ﴾»","url":""}]},{"id":"s24-116","number":116,"surah":24,"verses":[16],"references":[{"surah":24,"verses":[16]}],"verseLabel":"النور: 16","question":"ما دلالة التعبير بلفظ ﴿بُهْتَانٌ﴾؟","answer":"البهتان كذب يحيّر من ينسب إليه لشدته وبطلانه، فاختير لتأكيد براءة المقذوفين وتشنيع الافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص518، تحت عنوان «دلالة التعبير بالبهتان مادة وصيغة»","url":""}]},{"id":"s24-117","number":117,"surah":24,"verses":[16],"references":[{"surah":24,"verses":[16]}],"verseLabel":"النور: 16","question":"ما فائدة وصف البهتان بأنه ﴿عَظِيمٌ﴾؟","answer":"زاد الوصف التهويل والتقبيح، وأبرز جسامة الاعتداء وآثاره، فلا يعامل كحديث عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص519، تحت عنوان «فائدة وصف البهتان بالعظم»","url":""}]},{"id":"s24-28","number":28,"surah":24,"verses":[17],"references":[{"surah":24,"verses":[17]}],"verseLabel":"النور: 17","question":"لماذا نُهي عن العود إلى ﴿مِثْلِهِ﴾ دون عينه؟","answer":"النهي عن المثل أوسع من النهي عن الإفك المعين، فيشمل كل قول يشابهه في الاعتداء على الأعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص522، تحت عنوان «علة النهي عن العود لمثله دون عينه»","url":""}]},{"id":"s24-118","number":118,"surah":24,"verses":[17],"references":[{"surah":24,"verses":[17]}],"verseLabel":"النور: 17","question":"ما نكتة التأكيد بقوله: ﴿أَبَدًا﴾؟","answer":"أكد الظرف دوام النهي وشدته في جميع الأزمنة، لما يسببه الإفك من أذى وتمزيق لروابط المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص523، تحت عنوان «نكتة التأكيد بالظرف ﴿أَبَدًا﴾»","url":""}]},{"id":"s24-29","number":29,"surah":24,"verses":[19],"references":[{"surah":24,"verses":[19]}],"verseLabel":"النور: 19","question":"ما دلالة تعليق الوعيد على محبة شيوع الفاحشة في قوله تعالى: ﴿يُحِبُّونَ أَنْ تَشِيعَ الْفَاحِشَةُ﴾؟","answer":"محبة انتشار السوء تكشف خبث النية تجاه المؤمنين، وتدفع صاحبها إلى إذاعته أو السرور بوقوعه. فالتعبير بالمحبة يتناول فساد الباطن، ويكني أيضًا عن السعي في الترويج وإبراز ما يحب صاحبه وقوعه؛ فلا ينحصر التحذير في مباشرة الفاحشة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص529، تحت عنوان «نكتة تعليق الوعيد على المحبة على سبيل الكناية»","url":""}]},{"id":"s24-30","number":30,"surah":24,"verses":[21],"references":[{"surah":24,"verses":[21]}],"verseLabel":"النور: 21","question":"ما دلالة لفظ ﴿خُطُوَاتِ﴾ معنى وصيغة في قوله: ﴿لَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ﴾؟","answer":"يجمع اللفظ طرق الإغواء ومسالكه المتعددة المتدرجة من وسوسة إلى معصية؛ فحذر من كل سبيل من سبله لا من اتباعه إجمالًا فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص543، تحت عنوان «دلالة ﴿خُطُوَاتِ﴾ معنى وصيغة»","url":""}]},{"id":"s24-31","number":31,"surah":24,"verses":[21],"references":[{"surah":24,"verses":[21]}],"verseLabel":"النور: 21","question":"ما بلاغة التعبير بـ﴿مِنْ﴾ في قوله: ﴿مَا زَكَى مِنْكُمْ مِنْ أَحَدٍ﴾؟","answer":"أكدت ﴿من﴾ استغراق النفي، فلا يستقل أي فرد بتزكية نفسه لولا فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص552، تحت عنوان «بلاغة التعبير بـ﴿مِنْ﴾»","url":""}]},{"id":"s24-119","number":119,"surah":24,"verses":[21],"references":[{"surah":24,"verses":[21]}],"verseLabel":"النور: 21","question":"ما سر تنكير ﴿أَحَدٍ﴾ في قوله: ﴿مِنْ أَحَدٍ﴾؟","answer":"وقع النكرة في سياق النفي فشملت كل فرد، مهما كانت منزلته، في تقرير الافتقار إلى فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص552–553، تحت عنوان «سر تنكير ﴿أَحَدٍ﴾»","url":""}]},{"id":"s24-120","number":120,"surah":24,"verses":[21],"references":[{"surah":24,"verses":[21]}],"verseLabel":"النور: 21","question":"ما فائدة الظرف ﴿أَبَدًا﴾ في قوله: ﴿مَا زَكَى مِنْكُمْ مِنْ أَحَدٍ أَبَدًا﴾؟","answer":"مد النفي إلى جميع الأزمنة، فأكمل عموم الأشخاص بعموم الوقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص553، تحت عنوان «فائدة التعبير بالظرف ﴿أَبَدًا﴾»","url":""}]},{"id":"s24-32","number":32,"surah":24,"verses":[22],"references":[{"surah":24,"verses":[22]}],"verseLabel":"النور: 22","question":"ما دلالة الجمع بين العفو والصفح في قوله تعالى: ﴿وَلْيَعْفُوا وَلْيَصْفَحُوا﴾؟","answer":"العفو ترك المؤاخذة، والصفح أبلغ في التجاوز؛ إذ يترك معه التثريب واللوم، وتصفو النفس من أثر الإساءة. فالجمع يدعو إلى تمام الإحسان، لا مجرد إسقاط العقوبة مع إبقاء العتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص571، تحت عنوان «بلاغة ذكر الصفح بعد العفو»","url":""}]},{"id":"s24-33","number":33,"surah":24,"verses":[22],"references":[{"surah":24,"verses":[22]}],"verseLabel":"النور: 22","question":"ما بلاغة الاستفهام في قوله: ﴿أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ﴾؟","answer":"حض على العفو بإثارة محبة مغفرة الله؛ فمن يرجو المغفرة يليق به أن يتجاوز عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص571–572، تحت عنوان «بلاغة الاستفهام بالهمزة: ﴿أَلَا تُحِبُّونَ﴾»","url":""}]},{"id":"s24-121","number":121,"surah":24,"verses":[22],"references":[{"surah":24,"verses":[22]}],"verseLabel":"النور: 22","question":"ما وجه اختيار التحضيض بـ﴿أَلَا﴾ بعد الأمر بالعفو؟","answer":"جاء التحضيض لطيفًا يستنهض الرغبة في المغفرة ويؤثر في النفس، بدل الاقتصار على أمر مباشر قد لا يبلغ هذا الوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص572، تحت عنوان «وجه اصطفاء التحضيض بـ﴿أَلَا﴾»","url":""}]},{"id":"s24-34","number":34,"surah":24,"verses":[23],"references":[{"surah":24,"verses":[23]}],"verseLabel":"النور: 23","question":"ما دلالة وصف النساء بـ﴿الْمُحْصَنَاتِ﴾؟","answer":"صور الإحصان العفة حصنًا يحمي المرأة، فشدد قبح الاعتداء على من صانت نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص581، تحت عنوان «دلالة التعبير بـ﴿الْمُحْصَنَاتِ﴾»","url":""}]},{"id":"s24-122","number":122,"surah":24,"verses":[23],"references":[{"surah":24,"verses":[23]}],"verseLabel":"النور: 23","question":"ما بلاغة وصفهن باسم الفاعل ﴿الْغَافِلَاتِ﴾؟","answer":"دل الاسم على ثبوت نزاهتهن عن الفاحشة والريبة وعدم خطورها ببالهن، لا على غفلة مذمومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص582، تحت عنوان «بلاغة التعبير باسم الفاعل: ﴿الْغَافِلَاتِ﴾»","url":""}]},{"id":"s24-123","number":123,"surah":24,"verses":[23],"references":[{"surah":24,"verses":[23]}],"verseLabel":"النور: 23","question":"ما نكتة تأكيد وصف المقذوفات بـ﴿الْمُؤْمِنَاتِ﴾؟","answer":"زاد وصف الإيمان تشريفهن وبيان اجتماع الفضائل فيهن، فعظم جرم من رماهن وشوه سمعتهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص583، تحت عنوان «نكتة تأكيد الوصف بـ﴿الْمُؤْمِنَاتِ﴾»","url":""}]},{"id":"s24-35","number":35,"surah":24,"verses":[24],"references":[{"surah":24,"verses":[24]}],"verseLabel":"النور: 24","question":"ما دلالة تخصيص الألسنة والأيدي والأرجل بالشهادة في سياق القذف؟","answer":"هذه الجوارح أدوات تداول القذف: تنطق به الألسنة، وتشير الأيدي، وتسعى الأرجل في نشره. فتشهد عليهم الأدوات التي استعملوها في الإساءة، وفي ذلك تصوير لانكشاف عملهم وشدة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص590–591، تحت عنوان «علة إيثار الألسنة والأيدي والأرجل»","url":""}]},{"id":"s24-36","number":36,"surah":24,"verses":[25],"references":[{"surah":24,"verses":[25]}],"verseLabel":"النور: 25","question":"ما بلاغة اختيار لفظ ﴿الدِّينَ﴾ بمعنى الجزاء؟","answer":"استحضر اللفظ مقابلة العمل بما يستحقه، على معنى كما تدين تدان، فربط الجزاء بفعل صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص600، تحت عنوان «بلاغة اختيار لفظ الدين»","url":""}]},{"id":"s24-124","number":124,"surah":24,"verses":[25],"references":[{"surah":24,"verses":[25]}],"verseLabel":"النور: 25","question":"ما سر وصف الدين بأنه ﴿الْحَقَّ﴾؟","answer":"قرر الوصف عدل الجزاء وثبوته وتمامه، فلا ظلم فيه ولا نقص مما استحقه صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص600، تحت عنوان «سر وصف الدين بالحق»","url":""}]},{"id":"s24-37","number":37,"surah":24,"verses":[26],"references":[{"surah":24,"verses":[26]}],"verseLabel":"النور: 26","question":"ما توجيه الوصف بالخبث في قوله: ﴿الْخَبِيثَاتُ لِلْخَبِيثِينَ﴾؟","answer":"يحتمل الخبيثات الأقوال أو النساء، ويقابلهن الخبيثون؛ وعلى الوجهين يظهر تناسب الخبيث مع أهله من غير تحويل الآية إلى حكم مطلق على كل زواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص609–610، تحت عنوان «توجيه الوصف بالخبث»","url":""}]},{"id":"s24-125","number":125,"surah":24,"verses":[26],"references":[{"surah":24,"verses":[26]}],"verseLabel":"النور: 26","question":"ما بلاغة القصر في مقابلة الخبيثات بالطيبات؟","answer":"أكد القصر مناسبة الأقوال أو الأشخاص لأهلها، وأبرز براءة الطيبين من مقالة أهل الإفك.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص611–612، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s24-126","number":126,"surah":24,"verses":[26],"references":[{"surah":24,"verses":[26]}],"verseLabel":"النور: 26","question":"ما سر اسم الإشارة للبعيد ﴿أُولَئِكَ﴾ في سياق تبرئة الطيبين؟","answer":"أشار إليهم بالبعيد لعلو منزلتهم وبعدهم عن الخبث الذي رماهم به أهل الإفك.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص613، تحت عنوان «سر التعبير باسم الإشارة للبعيد ﴿أُولَئِكَ﴾»","url":""}]},{"id":"s24-38","number":38,"surah":24,"verses":[27],"references":[{"surah":24,"verses":[27]}],"verseLabel":"النور: 27","question":"ما بلاغة النهي بـ﴿لَا﴾ في قوله: ﴿لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ﴾؟","answer":"حفظ النهي حرمة البيوت ومنع الدخول المفضي إلى الريبة وكشف العورات، ثم أرشد إلى الاستئناس والسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص622، تحت عنوان «بلاغة النهي بـ﴿لَا﴾»","url":""}]},{"id":"s24-127","number":127,"surah":24,"verses":[27],"references":[{"surah":24,"verses":[27]}],"verseLabel":"النور: 27","question":"ما سر تنكير ﴿بُيُوتًا﴾ وجمعها؟","answer":"عم التنكير في سياق النهي كل بيت غير مملوك للمخاطب، وأفاد الجمع شمول الأنواع، فلا تستثنى بيوت الأقارب لمجرد القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص623–624، تحت عنوان «سر تنكير البيوت وجمعها ﴿بُيُوتًا﴾»","url":""}]},{"id":"s24-39","number":39,"surah":24,"verses":[27],"references":[{"surah":24,"verses":[27]}],"verseLabel":"النور: 27","question":"ما سر التعبير بـ﴿تَسْتَأْنِسُوا﴾ دون «تستأذنوا»؟","answer":"الاستئناس يتضمن طلب الإذن ويزيد عليه إزالة الوحشة واستكشاف رضا أهل البيت بالدخول؛ فلا يكون الدخول مفاجئًا يقلقهم. فاختير اللفظ لما يجمعه من الإذن وحصول الأنس بين الداخل وأهل المنزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص624–625، تحت عنوان «إيثار لفظ الاستئناس دون الاستئذان»","url":""}]},{"id":"s24-40","number":40,"surah":24,"verses":[28],"references":[{"surah":24,"verses":[28]}],"verseLabel":"النور: 28","question":"ما دلالة وصف الرجوع عند عدم الإذن بأنه ﴿أَزْكَى لَكُمْ﴾؟","answer":"الرجوع أطهر للنفس من الإلحاح والوقوف على الباب على وجه يوقع في الريبة أو يثير ضيق الصدر. فصيغة «أزكى» ترغّب في أدب الرجوع وتبين أثر الامتثال في تزكية الزائر وصيانة نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص645، تحت عنوان «نكتة بناء ﴿أزكى﴾ بصيغة أفعل التفضيل»","url":""}]},{"id":"s24-41","number":41,"surah":24,"verses":[29],"references":[{"surah":24,"verses":[29]}],"verseLabel":"النور: 29","question":"ما بلاغة وصف البيوت بـ﴿غَيْرَ مَسْكُونَةٍ﴾ دون «خالية»؟","answer":"دل الوصف على أماكن لم تعد للسكن الخاص، لا مجرد منزل غاب أهله مؤقتًا؛ فوافق موضع الاستثناء من الاستئذان.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص652، تحت عنوان «بلاغة التعبير بـ﴿مَسْكُونَةٍ﴾ دون (خالية)»","url":""}]},{"id":"s24-128","number":128,"surah":24,"verses":[29],"references":[{"surah":24,"verses":[29]}],"verseLabel":"النور: 29","question":"ما بلاغة الإطناب بقوله: ﴿فِيهَا مَتَاعٌ لَكُمْ﴾؟","answer":"بيّن القيد وجه الانتفاع الذي من أجله أبيح الدخول، فمنع أن يفهم الاستثناء لكل بيت غير مسكون بلا حاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص652، تحت عنوان «بلاغة الإطناب بجملة ﴿فِيهَا مَتَاعٌ لَكُمْ﴾»","url":""}]},{"id":"s24-42","number":42,"surah":24,"verses":[30],"references":[{"surah":24,"verses":[30]}],"verseLabel":"النور: 30","question":"ما دلالة دخول «من» في ﴿مِنْ أَبْصَارِهِمْ﴾ دون ﴿وَيَحْفَظُوا فُرُوجَهُمْ﴾؟","answer":"من توجيهات الفرق أن «من» للتبعيض؛ فباب النظر أوسع، وفيه مباح لا يُطلب غض البصر عنه، بينما جاء حفظ الفروج مطلقًا لشدة الاحتياط فيه، مع بقاء ما أباحه الشرع. فالاختلاف يراعي تفاوت نطاق المباح في البابين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص664، تحت عنوان «فائدة دخول ﴿من﴾ على (الأبصار) دون (الفروج)»","url":""}]},{"id":"s24-43","number":43,"surah":24,"verses":[30],"references":[{"surah":24,"verses":[30]}],"verseLabel":"النور: 30","question":"ما نكتة التعبير باسم الله ﴿خَبِيرٌ﴾ بعد أمر غض البصر؟","answer":"الخبير يحيط بدقائق الأعمال وخفايا الدوافع، فناسب ما قد يخفى من النظر وحمل على المراقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص668، تحت عنوان «نكتة التعبير باسم ﴿خَبِيرٌ﴾»","url":""}]},{"id":"s24-129","number":129,"surah":24,"verses":[30],"references":[{"surah":24,"verses":[30]}],"verseLabel":"النور: 30","question":"لماذا اختير لفظ ﴿يَصْنَعُونَ﴾ دون مرادفاته؟","answer":"الصنع فعل يجري بقصد وإتقان، فشمل ما يتعمده الإنسان ويحكمه من تصرفات خيرًا أو شرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص669، تحت عنوان «وجه اختيار مفردة ﴿يَصْنَعُونَ﴾ دون مرادفاتها»","url":""}]},{"id":"s24-130","number":130,"surah":24,"verses":[30],"references":[{"surah":24,"verses":[30]}],"verseLabel":"النور: 30","question":"ما بلاغة تذييل أمر غض البصر بقوله: ﴿إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ﴾؟","answer":"عمم التذييل المراقبة والجزاء، فذكّر بأن الأمر ليس أدبًا ظاهرًا فقط وأن الأعمال ودقائقها معلومة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص670، تحت عنوان «بلاغة التذييل»","url":""}]},{"id":"s24-44","number":44,"surah":24,"verses":[31],"references":[{"surah":24,"verses":[31]}],"verseLabel":"النور: 31","question":"ما دلالة إعادة أمر غض البصر وحفظ الفرج في خطاب المؤمنات؟","answer":"كانت المؤمنات داخلات في الخطاب العام بطريق التغليب، ثم أفردن بالذكر لتأكيد اشتراكهن في التكليف والعناية به في حقهن. فالإعادة توكيد واهتمام، لا لأن الخطاب الأول لا يمكن أن يشملهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص674–675، تحت عنوان «الإطناب في خطاب المؤمنات بعد المؤمنين»","url":""}]},{"id":"s24-45","number":45,"surah":24,"verses":[31],"references":[{"surah":24,"verses":[31]}],"verseLabel":"النور: 31","question":"ما نكتة إيثار ﴿ظَهَرَ﴾ في قوله: ﴿إِلَّا مَا ظَهَرَ مِنْهَا﴾ دون «أظهرن»؟","answer":"أسند الظهور إلى الزينة ليلحظ ما يبدو دون قصد أو ما يشق إخفاؤه، بخلاف أظهرن التي تصرح بتعمد الإبداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص681، تحت عنوان «نكتة إيثار ﴿ظَهَرَ﴾ دون (أظهرن منها)»","url":""}]},{"id":"s24-131","number":131,"surah":24,"verses":[31],"references":[{"surah":24,"verses":[31]}],"verseLabel":"النور: 31","question":"ما دلالة ﴿مَا ظَهَرَ مِنَ الزِّينَةِ﴾ في السياق؟","answer":"يدل على قدر مستثنى مما تدعو الحاجة إلى ظهوره أو يظهر بغير قصد، مع بقاء الخلاف في تعيينه؛ فلا يحسم الفرق اللغوي وحده تفاصيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص678–679، تحت عنوان «دلالة ما ظهر من الزينة في السياق»","url":""}]},{"id":"s24-46","number":46,"surah":24,"verses":[31],"references":[{"surah":24,"verses":[31]}],"verseLabel":"النور: 31","question":"ما دلالة التعبير بـ﴿وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ﴾؟","answer":"«وليضربن» يفيد توكيد إلقاء الخمار وإحكامه على موضع الجيب، بحيث يستر النحر والصدر. فليس المقصود مجرد وجود الخمار، بل توجيه طريقة استعماله؛ إذ كان يُلقى خلف الرأس فيبقى ما عند فتحة الثوب مكشوفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص682، تحت عنوان «فائدة استعمال مفردة ﴿وليضربن﴾»","url":""}]},{"id":"s24-47","number":47,"surah":24,"verses":[31],"references":[{"surah":24,"verses":[31]}],"verseLabel":"النور: 31","question":"ما نكتة التعبير بالمفرد ﴿الطِّفْلِ﴾ دون الجمع؟","answer":"استعمل اسم الجنس المفرد للجماعة، ويلفت الإفراد إلى اعتبار حال كل طفل لأن الإدراك يختلف بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص689، تحت عنوان «نكتة التعبير بلفظ المفرد ﴿الطِّفْلِ﴾ دون الجمع»","url":""}]},{"id":"s24-132","number":132,"surah":24,"verses":[31],"references":[{"surah":24,"verses":[31]}],"verseLabel":"النور: 31","question":"ما دلالة ﴿أل﴾ في لفظ ﴿الطِّفْلِ﴾؟","answer":"هي للجنس، فشمل اللفظ الأطفال جميعًا، ولذلك صح أن يوصف بعده بالجمع ﴿الَّذِينَ لَمْ يَظْهَرُوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص689، تحت عنوان «دلالة (أل) في لفظ ﴿الطِّفْلِ﴾»","url":""}]},{"id":"s24-48","number":48,"surah":24,"verses":[31],"references":[{"surah":24,"verses":[31]}],"verseLabel":"النور: 31","question":"ما دلالة النهي عن ضرب الأرجل ليُعلم ما يخفى من الزينة؟","answer":"قد يلفت صوت الزينة المستورة الانتباه إليها كما يلفت ظهورها النظر؛ فالنهي يمنع تعمد إظهار أثرها المسموع بقصد التنبيه إليها. وبذلك لا يقتصر الأدب على ستر الزينة مع استدعاء الالتفات إليها بطريق آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص691، تحت عنوان «علة نهي النساء عن الضرب بالأرجل»","url":""}]},{"id":"s24-49","number":49,"surah":24,"verses":[32],"references":[{"surah":24,"verses":[32]}],"verseLabel":"النور: 32","question":"ما معنى الواو في قوله: ﴿وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ﴾؟","answer":"عطفت الأمر بتيسير النكاح على أوامر العفة وغض البصر، فانتقل السياق من الوقاية إلى معالجة أسبابها الاجتماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص702، تحت عنوان «معنى الواو في قوله: ﴿وَأَنْكِحُوا﴾»","url":""}]},{"id":"s24-133","number":133,"surah":24,"verses":[32],"references":[{"surah":24,"verses":[32]}],"verseLabel":"النور: 32","question":"إلى من يعود ضمير الجماعة في قوله: ﴿وَأَنْكِحُوا﴾؟","answer":"يتجه الخطاب إلى من بيدهم إقامة النكاح وتيسيره من الأولياء والسادة والحكام، بحسب الولاية والقدرة، لا تكليفًا متماثلًا لكل فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص703، تحت عنوان «عود الضمير في ﴿وَأَنْكِحُوا﴾»","url":""}]},{"id":"s24-50","number":50,"surah":24,"verses":[32],"references":[{"surah":24,"verses":[32]}],"verseLabel":"النور: 32","question":"ما نكتة فصل قوله: ﴿إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ﴾؟","answer":"جاء استئنافًا يدفع الاعتراض بالفقر على تيسير الزواج، ويقرر أن الفقر ليس مانعًا مطلقًا مع رجاء فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص705–706، تحت عنوان «نكتة فصل قوله: ﴿إِنْ يَكُونُوا فُقَرَاءَ﴾»","url":""}]},{"id":"s24-134","number":134,"surah":24,"verses":[32],"references":[{"surah":24,"verses":[32]}],"verseLabel":"النور: 32","question":"لماذا جاء شرط الفقر بـ﴿إِنْ﴾ دون «إذا»؟","answer":"عرض الفقر أمرًا محتمل الوقوع لا متحققًا في كل حالة، كما أن الإغناء من فضل الله متعلق بمشيئته لا وعد آليًا بالغنى المادي لكل زواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص706–707، تحت عنوان «غرض مجيء الشرط بـ﴿إِنْ﴾، دون (إذا)»","url":""}]},{"id":"s24-51","number":51,"surah":24,"verses":[33],"references":[{"surah":24,"verses":[33]}],"verseLabel":"النور: 33","question":"ما نكتة الاشتراط بـ﴿إِنْ﴾ دون «إذا» في قوله: ﴿إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا﴾؟","answer":"جعل العلم بالخير محتمل الحصول أو الخفاء، لا أمرًا مقطوعًا بتحققه في كل طالب للمكاتبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص718، تحت عنوان «نكتة الاشتراط بـ﴿إِنْ﴾ دون (إذا)»","url":""}]},{"id":"s24-135","number":135,"surah":24,"verses":[33],"references":[{"surah":24,"verses":[33]}],"verseLabel":"النور: 33","question":"ما فائدة تقييد المكاتبة بشرط العلم بالخير؟","answer":"رعى قدرة المكاتب وأمانته وصلاحه لأداء الحق، مع التنبيه إلى أن عدم العلم بالخير لا يساوي العلم بعدمه ولا يبرر منعًا مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص718–719، تحت عنوان «فائدة تقييد المكاتبة بالشرط»","url":""}]},{"id":"s24-52","number":52,"surah":24,"verses":[33],"references":[{"surah":24,"verses":[33]}],"verseLabel":"النور: 33","question":"ما سر التعبير بـ﴿الْبِغَاءِ﴾ دون «الزنا» في سياق إكراه الإماء؟","answer":"البغاء أخص في هذا السياق؛ إذ يلحظ بذل الفاحشة لقاء عوض واتخاذها طريقًا للكسب. فاختير لما يلائم إكراه الإماء ابتغاء عرض الحياة الدنيا، لا لمجرد تسمية الفعل دون غرضه المالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص724، تحت عنوان «بلاغة التعبير بلفظ ﴿البغاء﴾ دون لفظ (الزنى)»","url":""}]},{"id":"s24-53","number":53,"surah":24,"verses":[33],"references":[{"surah":24,"verses":[33]}],"verseLabel":"النور: 33","question":"ما معنى الفاء في قوله: ﴿فَإِنَّ اللَّهَ مِنْ بَعْدِ إِكْرَاهِهِنَّ غَفُورٌ رَحِيمٌ﴾؟","answer":"فرعت المغفرة والرحمة للمكرهات على وقوع الإكراه، فطمأنتهن برفع المؤاخذة ولم تسقط مسؤولية المكرِه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص730، تحت عنوان «معنى الفاء في قوله: ﴿فَإِنَّ اللَّهَ﴾»","url":""}]},{"id":"s24-136","number":136,"surah":24,"verses":[33],"references":[{"surah":24,"verses":[33]}],"verseLabel":"النور: 33","question":"ما نكتة إظهار لفظ ﴿إِكْرَاهِهِنَّ﴾ بدل الإضمار؟","answer":"أعاد سبب الحكم صريحًا لإبرازه وتأكيد أن المغفرة والرحمة متعلقتان بحال الإكراه لا بالفعل الاختياري.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص731، تحت عنوان «نكتة الإظهار في موضع الإضمار في شبه الجملة»","url":""}]},{"id":"s24-54","number":54,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"لماذا اختير ﴿النُّورُ﴾ دون الضوء في قوله: ﴿اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"النور أعم من الضوء، ويستعمل في الحسي والمعنوي؛ فناسب الهداية والإظهار والتدبير الذي يعم السماوات والأرض، ولم يحصر المعنى في الإشعاع الحسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص746–747، تحت عنوان «نكتة اختيار النور دون الضوء»","url":""}]},{"id":"s24-137","number":137,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"ما الاستعارة في قوله: ﴿اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"على توجيه الاستعارة صُوّرت هداية الله وإظهاره للحق بالنور الذي يكشف المرئيات؛ فالآية تقرّب أثر الهداية ولا تجعل الذات الإلهية ضوءًا حسيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص744–745، تحت عنوان «الاستعارة التصريحية في: ﴿الله نور السماوات والأرض﴾»","url":""}]},{"id":"s24-55","number":55,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"لماذا خُصت ﴿الْمِشْكَاةِ﴾ بالذكر في مثل النور؟","answer":"المشكاة تجمع نور المصباح وتحصره فيقوى ظهوره، فكانت أنسب ببناء صورة النور المتضاعف من المصباح والزجاجة والزيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص749، تحت عنوان «نكتة تخصيص المشكاة بالذكر دون غيرها»","url":""}]},{"id":"s24-138","number":138,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"كيف يجري مثل النور على التشبيه التمثيلي المركب؟","answer":"يشبّه مجموع حال نور الهداية في قلب المؤمن بمجموع هيئة المشكاة والمصباح والزجاجة والزيت الصافي؛ فوجه الشبه صورة منتزعة من عناصر متآزرة لا مقابلة مفردة لازمة لكل لفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص759–760، تحت عنوان «إجراء النظم على التشبيه التمثيلي المركب»","url":""}]},{"id":"s24-139","number":139,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"كيف يجري مثل النور على التشبيه المفرد؟","answer":"على هذا الوجه تُقابل عناصر المثل بأحوال الهداية والإيمان مقابلات مفردة، مع بقاء المقصود إبراز صفاء النور وقوته، وهو تحليل بلاغي بديل عن حمله على التمثيل المركب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص760–761، تحت عنوان «إجراء النظم على التشبيه المفرد»","url":""}]},{"id":"s24-56","number":56,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"ما دلالة إعادة الاسمين في ﴿الْمِصْبَاحُ فِي زُجَاجَةٍ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ﴾ بدل الضمير؟","answer":"الإظهار يقرر المصباح والزجاجة في الذهن، ويجدد استحضار أسباب صفاء النور وقوته. وفيه تفسير بعد إبهام وتفصيل بعد إجمال، وعناية بكل عنصر بإسناد خبر مستقل إليه، فيثبت وصف الصورة ويقوى حضورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص749–750، تحت عنوان «الإظهار في مقام الإضمار»","url":""}]},{"id":"s24-57","number":57,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"ما موقع جملة ﴿لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ﴾ من وصف الشجرة؟","answer":"جاءت صفةً للشجرة تبين جودة موقعها وتوسطه؛ فلا تختص بشمس أول النهار أو آخره، بل تنال من الضوء ما يطيب ثمرها ويصفو زيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص756–757، تحت عنوان «موقع جملة: ﴿لا شرقية ولا غربية﴾»","url":""}]},{"id":"s24-140","number":140,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"ما قيمة الطباق في قوله: ﴿لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ﴾؟","answer":"جمع الطباق طرفي الجهات المتقابلة فاستوعب نفي الانحصار في أحدهما، وأبرز توسط الشجرة وكمال تعرضها للشمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص757، تحت عنوان «قيمة الطباق في قوله: ﴿لا شرقية ولا غربية﴾»","url":""}]},{"id":"s24-58","number":58,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"ما موقع جملة ﴿نُورٌ عَلَى نُورٍ﴾ مما قبلها؟","answer":"جاءت تلخيصًا لصفاء عناصر المثل واجتماع أسباب الإضاءة، فصوّرت نورًا متضاعفًا يعلو بعضه بعضًا، وفي المعنى هدى يتآزر مع الفطرة والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص761، تحت عنوان «موقع جملة: ﴿نور على نور﴾ مما قبلها»","url":""}]},{"id":"s24-141","number":141,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"ما دلالة تنكير ﴿نُورٌ﴾ في قوله: ﴿نُورٌ عَلَى نُورٍ﴾؟","answer":"أفاد التنكير التعظيم والتفخيم، وصوّر نورًا بالغًا لا يحد بقدر مألوف، ثم كرر اللفظ لزيادة معنى التضاعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص762، تحت عنوان «دلالة التنكير في: ﴿نور على نور﴾»","url":""}]},{"id":"s24-59","number":59,"surah":24,"verses":[36,37],"references":[{"surah":24,"verses":[36,37]}],"verseLabel":"النور: 36-37","question":"ما دلالة مجيء ﴿فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ﴾ بعد مثل النور؟","answer":"يذكر المصدر وجه اتصال الجملة بالمثل، فتزيد أوصاف البيوت المشهد حسنًا وتعظيمًا، ووجه استئناف الحديث عن أهل الذكر ومواطن عبادتهم. وعلى الوجهين يبرز شأن المساجد وما فيها من ذكر وصلاة، فلا يحصر تعلق الجملة النحوي في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص767–768، تحت عنوان «موقع جملة: ﴿في بيوت﴾ مما قبلها»","url":""}]},{"id":"s24-60","number":60,"surah":24,"verses":[37],"references":[{"surah":24,"verses":[37]}],"verseLabel":"النور: 37","question":"ما دلالة الجمع بين ﴿تِجَارَةٌ﴾ و﴿بَيْعٌ﴾ في مدح المؤمنين؟","answer":"عمّ التعبير وجوه الاشتغال بالكسب، ثم أبرز البيع لأنه موطن تحقق الربح وأشد إلهاء، فزاد المدح بأن نشاطهم الاقتصادي كله لا يصرفهم عن ذكر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص782–783، تحت عنوان «دلالة الجمع بين التجارة والبيع»","url":""}]},{"id":"s24-142","number":142,"surah":24,"verses":[37],"references":[{"surah":24,"verses":[37]}],"verseLabel":"النور: 37","question":"لماذا أُفرد البيع بالذكر دون الشراء؟","answer":"لأن تعلق النفس بالبيع عند حصول الربح أقوى، ولأن البيع غاية الدورة التجارية وأظهر في الإلهاء، فخص بالذكر بعد التجارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص783، تحت عنوان «سر إفراد البيع بالذكر دون الشراء»","url":""}]},{"id":"s24-61","number":61,"surah":24,"verses":[37],"references":[{"surah":24,"verses":[37]}],"verseLabel":"النور: 37","question":"ما دلالة التعبير بـ﴿وَإِقَامِ الصَّلَاةِ﴾ بالمصدر دون «يقيمون الصلاة»؟","answer":"المصدر يؤكد تعلق القلوب بإقامة الصلاة ولزومها؛ فهم يستعدون لها ويظلون متعلقين بها حتى خارج أوقاتها. أما الفعل فيصور تجدد إقامتها عند حلول وقتها، فجاء المصدر لإبراز رسوخ هذا التعلق واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص785، تحت عنوان «سر التعبير بالمصدرية دون الفعلية»","url":""}]},{"id":"s24-62","number":62,"surah":24,"verses":[39],"references":[{"surah":24,"verses":[39]}],"verseLabel":"النور: 39","question":"ما دلالة تشبيه أعمال الكافرين بالسراب؟","answer":"يمثل التشبيه خيبة من توهم نفع عمله ثم لم يجد ثمرته حين اشتدت حاجته إليه، بحال ظمآن قصد ما حسبه ماء فلم يجده شيئًا. فالمثل ينقل المعنى إلى صورة محسوسة، ويجمع بطلان الرجاء وشدة الحسرة عند انكشاف الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص15–16، تحت عنوان «بلاغة التشبيه التمثيلي في الآية»","url":""}]},{"id":"s24-63","number":63,"surah":24,"verses":[39],"references":[{"surah":24,"verses":[39]}],"verseLabel":"النور: 39","question":"لماذا خُص الظمآن بحسبان السراب ماء؟","answer":"قد يخطئ غيره في السراب، لكن حاجة الظمآن وشدة طلبه للماء تزيدان تعلقه بالوهم، فتكون خيبته عند انكشافه أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص19–20، تحت عنوان «تخصيص الحسبان بالظمآن»","url":""}]},{"id":"s24-143","number":143,"surah":24,"verses":[39],"references":[{"surah":24,"verses":[39]}],"verseLabel":"النور: 39","question":"ما دلالة صيغة المبالغة في ﴿الظَّمْآنُ﴾ دون «الظامئ»؟","answer":"تصور الصيغة بلوغ العطش غايته وما يصاحبه من اللهفة والتحرق، فتضاعف أثر الخيبة حين لا يجد ماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص20، تحت عنوان «سر التعبير بصيغة المبالغة في ﴿الظمآن﴾ دون الظامئ»","url":""}]},{"id":"s24-64","number":64,"surah":24,"verses":[39],"references":[{"surah":24,"verses":[39]}],"verseLabel":"النور: 39","question":"ما دلالة الواو في قوله: ﴿وَوَجَدَ اللَّهَ عِنْدَهُ﴾؟","answer":"عطفت على خيبة السراب مفاجأة الحساب، فلم تنته الصورة إلى فقد الماء المتوهم، بل أعقبه لقاء الجزاء على العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص24، تحت عنوان «دلالة الواو في قوله: ﴿ووجد الله عنده﴾»","url":""}]},{"id":"s24-144","number":144,"surah":24,"verses":[39],"references":[{"surah":24,"verses":[39]}],"verseLabel":"النور: 39","question":"ما دلالة الظرفية في قوله: ﴿وَوَجَدَ اللَّهَ عِنْدَهُ﴾؟","answer":"تهوّل ﴿عنده﴾ المفاجأة وتقرر حضور الحساب عند انكشاف العمل؛ ولا تعني حلول الله في مكان السراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص24–25، تحت عنوان «دلالة التعبير بالظرفية ﴿عنده﴾»","url":""}]},{"id":"s24-65","number":65,"surah":24,"verses":[40],"references":[{"surah":24,"verses":[40]}],"verseLabel":"النور: 40","question":"ما دلالة جمع الظلمات في المثل الثاني لأعمال الكافرين؟","answer":"الجمع يصور ظلمات متراكبة يشتد بها الظلام، فتجتمع ظلمة البحر وما فوقه من موج وسحاب. وتقابل هذه الصورة تعدد أسباب الضلال من جهل وكفر وشك وإعراض عن الحق، فتتضافر كثرتها وشدتها في بناء المثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص39–40، تحت عنوان «نكتة جمع لفظ ﴿ظلمات﴾ في الموضعين»","url":""}]},{"id":"s24-66","number":66,"surah":24,"verses":[40],"references":[{"surah":24,"verses":[40]}],"verseLabel":"النور: 40","question":"ما دلالة وصف البحر بأنه ﴿لُجِّيٍّ﴾؟","answer":"اللجي عميق كثير الماء بعيد الغور، وتلحظ مادته لجّة البحر واضطراب موجه، فتجمع الصورة رهبة العمق والاضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص41، تحت عنوان «دلالة وصف البحر باللجي»","url":""}]},{"id":"s24-145","number":145,"surah":24,"verses":[40],"references":[{"surah":24,"verses":[40]}],"verseLabel":"النور: 40","question":"ما نكتة وصف الظلمات بأنها ﴿فِي بَحْرٍ لُجِّيٍّ﴾؟","answer":"جعل الظلمات في بحر عميق يضاعف استحكامها؛ فهي ظلمة العمق تعلوها أمواج وسحاب، فيتعذر الاهتداء والخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص41، تحت عنوان «نكتة وصف الظلمات بأنها ﴿في بحر لجي﴾»","url":""}]},{"id":"s24-67","number":67,"surah":24,"verses":[40],"references":[{"surah":24,"verses":[40]}],"verseLabel":"النور: 40","question":"ما فائدة قوله: ﴿لَمْ يَكَدْ يَرَاهَا﴾ في وصف الظلمات؟","answer":"على الوجه الراجح ينفي رؤية اليد ومقاربتها مبالغةً في استحكام الظلمة، ويذكر وجه آخر بأنها لا ترى إلا بعسر شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص49–50، تحت عنوان «الموقع النحوي لقوله: ﴿لم يكد يراها﴾، وفائدة التعبير به»","url":""}]},{"id":"s24-146","number":146,"surah":24,"verses":[40],"references":[{"surah":24,"verses":[40]}],"verseLabel":"النور: 40","question":"لماذا اختيرت اليد في قوله: ﴿إِذَا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرَاهَا﴾؟","answer":"اليد من أقرب ما يراه الإنسان؛ فإذا لم يرها كان أعجز عن رؤية الأبعد وعن الاهتداء إلى طريق النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص50، تحت عنوان «سر انتخاب اليد دون سائر الأعضاء في الرؤية»","url":""}]},{"id":"s24-68","number":68,"surah":24,"verses":[41],"references":[{"surah":24,"verses":[41]}],"verseLabel":"النور: 41","question":"ما دلالة التعبير بـ﴿كُلٌّ﴾ في قوله: ﴿كُلٌّ قَدْ عَلِمَ صَلَاتَهُ وَتَسْبِيحَهُ﴾؟","answer":"يفيد اللفظ عموم المخلوقات المذكورة وعدم اختصاص التسبيح بالطير؛ فلكل مخلوق عبادة وتسبيح على الوجه الذي ألهمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص65، تحت عنوان «دلالة التعبير بـ﴿كل﴾»","url":""}]},{"id":"s24-147","number":147,"surah":24,"verses":[41],"references":[{"surah":24,"verses":[41]}],"verseLabel":"النور: 41","question":"إلى من يعود الضمير المحذوف في ﴿قَدْ عَلِمَ صَلَاتَهُ وَتَسْبِيحَهُ﴾؟","answer":"يحتمل عوده إلى كل مخلوق، أي ألهمه الله صلاته وتسبيحه، ويحتمل عوده إلى الله، أي أحاط علمه بعبادة كل مخلوق؛ فيبرز الأول الإلهام والثاني العلم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص66–67، تحت عنوان «بلاغة عود الضمير المحذوف في ﴿علم﴾»","url":""}]},{"id":"s24-69","number":69,"surah":24,"verses":[43],"references":[{"surah":24,"verses":[43]}],"verseLabel":"النور: 43","question":"ما دلالة التعبير بـ﴿يُزْجِي سَحَابًا﴾؟","answer":"الإزجاء سوق الشيء برفق، فيصور بدء تكوين السحاب وانتقال أجزائه شيئًا فشيئًا قبل تأليفها وتراكمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص82–83، تحت عنوان «دلالة التعبير بـ﴿يزجي﴾ مادة»","url":""}]},{"id":"s24-148","number":148,"surah":24,"verses":[43],"references":[{"surah":24,"verses":[43]}],"verseLabel":"النور: 43","question":"ما دلالة ﴿ثُمَّ﴾ في قوله: ﴿ثُمَّ يُؤَلِّفُ بَيْنَهُ﴾؟","answer":"تفيد الترتيب مع التراخي، فتنقل المشهد من سوق قطع السحاب المتفرقة إلى ضم بعضها إلى بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص84، تحت عنوان «دلالة التعبير بـ﴿ثم﴾ في قوله: ﴿ثم يؤلف بينه﴾»","url":""}]},{"id":"s24-149","number":149,"surah":24,"verses":[43],"references":[{"surah":24,"verses":[43]}],"verseLabel":"النور: 43","question":"ما دلالة ﴿ثُمَّ﴾ في قوله: ﴿ثُمَّ يَجْعَلُهُ رُكَامًا﴾؟","answer":"ترتب مرحلة التراكم على مرحلة التأليف؛ فبعد اجتماع القطع تصير طبقات بعضها فوق بعض، ويكتمل تدرج الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص85، تحت عنوان «دلالة التعبير بـ﴿ثم﴾ في قوله: ﴿ثم يجعله﴾»","url":""}]},{"id":"s24-70","number":70,"surah":24,"verses":[43],"references":[{"surah":24,"verses":[43]}],"verseLabel":"النور: 43","question":"ما دلالة ذكر البَرَد دون الثلج في مشهد إنزال الماء من السماء؟","answer":"يعلل المصدر ذلك بأن المخاطبين كانوا يعرفون البَرَد لنزوله في أرضهم، فخوطبوا بما يعرفون، بخلاف الثلج الذي لم يكن مألوفًا في بلادهم. ويذكر أيضًا ما يحدثه البَرَد من تبريد وجه الأرض الحارة، بوصفه وجهًا من وجوه الامتنان في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص91، تحت عنوان «دلالة ذكر البرد دون الثلج»","url":""}]},{"id":"s24-71","number":71,"surah":24,"verses":[43],"references":[{"surah":24,"verses":[43]}],"verseLabel":"النور: 43","question":"ما التشبيه في قوله: ﴿مِنْ جِبَالٍ فِيهَا مِنْ بَرَدٍ﴾؟","answer":"من توجيهاته تشبيه قطع السحاب العظيمة المتراكمة بالجبال في الضخامة والعلو، ويذكر أيضًا وجه جبال من برد في السماء؛ فلا يجزم بوجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص90، تحت عنوان «بلاغة التشبيه في ﴿جبال﴾»","url":""}]},{"id":"s24-150","number":150,"surah":24,"verses":[43],"references":[{"surah":24,"verses":[43]}],"verseLabel":"النور: 43","question":"ما فائدة الظرفية في قوله: ﴿فِيهَا مِنْ بَرَدٍ﴾؟","answer":"جعل البرد في تلك الجبال أو الكتل السحابية يصور احتواءها عليه وصدوره من داخلها، فيقوي تجسيم المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص90، تحت عنوان «فائدة الظرفية في قوله: ﴿فيها﴾»","url":""}]},{"id":"s24-72","number":72,"surah":24,"verses":[44],"references":[{"surah":24,"verses":[44]}],"verseLabel":"النور: 44","question":"لماذا عُبر بلفظ ﴿لَعِبْرَةً﴾ في تقليب الليل والنهار؟","answer":"العبرة انتقال من الأثر المشاهد إلى معرفة قدرة مدبره ووحدانيته، فليست مجرد رؤية لتعاقب الزمن بل نظر يفضي إلى الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص103، تحت عنوان «علة التعبير بلفظ: ﴿لعبرة﴾»","url":""}]},{"id":"s24-151","number":151,"surah":24,"verses":[44],"references":[{"surah":24,"verses":[44]}],"verseLabel":"النور: 44","question":"لماذا خُص ﴿أُولِي الْأَبْصَارِ﴾ بالذكر؟","answer":"لأن أصحاب الأبصار والبصائر هم المنتفعون بالتأمل في الآيات؛ فوضوح المشهد لا يغني عن نظر واع يجاوز الحس إلى الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص103–104، تحت عنوان «سر تخصيص ﴿لأولي الأبصار﴾ بالذكر»","url":""}]},{"id":"s24-73","number":73,"surah":24,"verses":[45],"references":[{"surah":24,"verses":[45]}],"verseLabel":"النور: 45","question":"ما دلالة تنكير ﴿مِنْ مَاءٍ﴾ في النور، وتعريفه في الأنبياء: ﴿مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾؟","answer":"النور في مقام تفصيل أنواع الدواب واختلاف صورها، فالتنكير يلحظ نوع الماء الذي يختص بكل دابة ويمهد لتفصيل أصنافها. أما الأنبياء ففي مقام إجمال أصل الحياة في جنس الماء المعروف، فناسبه التعريف. فالمقارنة بين بسط الاستدلال وتفصيله هنا، وإجماله هناك.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص107، تحت عنوان «دلالة تنكير لفظ ﴿ماء﴾ هنا، وتعريفه في سورة الأنبياء»","url":""}]},{"id":"s24-74","number":74,"surah":24,"verses":[45],"references":[{"surah":24,"verses":[45]}],"verseLabel":"النور: 45","question":"ما دلالة الفاء في تفصيل الدواب بعد قوله: ﴿خَلَقَ كُلَّ دَابَّةٍ مِنْ مَاءٍ﴾؟","answer":"فرّعت الفاء صور المشي المختلفة على أصل الخلق الواحد، فأظهرت القدرة في تنويع الهيئات والحركات مع وحدة المنشأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص108، تحت عنوان «معنى الفاء ودلالة التعبير بها»","url":""}]},{"id":"s24-152","number":152,"surah":24,"verses":[45],"references":[{"surah":24,"verses":[45]}],"verseLabel":"النور: 45","question":"ما دلالة الواو وترتيب أصناف الدواب في الآية؟","answer":"عطفت الواو الأنواع المتغايرة، وبدأ الترتيب بما يمشي على بطنه لأنه أعجب بلا آلة ظاهرة، ثم ما يمشي على رجلين، ثم على أربع بحسب الغالب المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص111، تحت عنوان «معنى الواو، وبلاغة الترتيب في الآية»","url":""}]},{"id":"s24-75","number":75,"surah":24,"verses":[46],"references":[{"surah":24,"verses":[46]}],"verseLabel":"النور: 46","question":"ما نكتة عطف قوله في النور 34: ﴿وَلَقَدْ أَنْزَلْنَا إِلَيْكُمْ آيَاتٍ مُبَيِّنَاتٍ﴾؟","answer":"وصلت الواو خاتمة التشريعات بما قبلها، فقررت أن الأحكام السابقة آيات مبينات وموعظة، وأكدت تماسك هذا المقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص733، تحت عنوان «نكتة عطف قوله: ﴿ولقد أنزلنا﴾»","url":""}]},{"id":"s24-153","number":153,"surah":24,"verses":[46],"references":[{"surah":24,"verses":[46]}],"verseLabel":"النور: 46","question":"لماذا فُصل قوله في النور 46: ﴿لَقَدْ أَنْزَلْنَا آيَاتٍ مُبَيِّنَاتٍ﴾ عما قبله؟","answer":"جاءت الجملة نتيجةً مؤكدة للاستدلالات والعبر السابقة، فبلغ اتصالها المعنوي مبلغًا استغنى معه عن الواو، وليس الفصل انقطاعًا عن السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص117–118، تحت عنوان «سر فصل الآية عما قبلها»","url":""}]},{"id":"s24-76","number":76,"surah":24,"verses":[47,48],"references":[{"surah":24,"verses":[47,48]}],"verseLabel":"النور: 47-48","question":"ما دلالة ﴿ثُمَّ﴾ في قوله عن المنافقين: ﴿ثُمَّ يَتَوَلَّى فَرِيقٌ مِنْهُمْ﴾؟","answer":"تفيد التراخي الرتبي والاستبعاد؛ فالتولي قبيح مستغرب بعد تصريحهم بالإيمان والطاعة، لا مجرد حدث متأخر زمنيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص126، تحت عنوان «معنى ﴿ثم﴾، ودلالة التعبير بها»","url":""}]},{"id":"s24-154","number":154,"surah":24,"verses":[47,48],"references":[{"surah":24,"verses":[47,48]}],"verseLabel":"النور: 47-48","question":"ما سر ترتيب المعاني في قوله: ﴿آمَنَّا بِاللَّهِ وَبِالرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّى فَرِيقٌ مِنْهُمْ﴾؟","answer":"رتب السياق الدعوى باللسان، ثم الفعل المكذب لها، ثم نفي الإيمان؛ فكشف تدريجيًا الفجوة بين القول وحقيقة السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص130، تحت عنوان «سر ترتيب المعاني في الآية»","url":""}]},{"id":"s24-77","number":77,"surah":24,"verses":[49],"references":[{"surah":24,"verses":[49]}],"verseLabel":"النور: 49","question":"ما دلالة إتيان المنافقين ﴿مُذْعِنِينَ﴾ إذا كان الحق لهم؟","answer":"الإذعان يتضمن الانقياد مع الإسراع والرغبة، وهم يظهرونه حين يوافق الحكم مصلحتهم، ثم يعرضون إذا كان عليهم. فليس هذا قبولًا للعدل لذاته، بل شاهد على اتباع المصلحة، وتزيد الكلمة إبراز التناقض بين الإقبال والإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص145، تحت عنوان «سر التعبير بلفظ: ﴿مذعنين﴾»","url":""}]},{"id":"s24-78","number":78,"surah":24,"verses":[50],"references":[{"surah":24,"verses":[50]}],"verseLabel":"النور: 50","question":"ما بلاغة الاستفهام في قوله: ﴿أَفِي قُلُوبِهِمْ مَرَضٌ أَمِ ارْتَابُوا أَمْ يَخَافُونَ﴾؟","answer":"استفهام إنكاري توبيخي يستقصي وجوه فساد الباطن وسوء الظن التي تفسر إعراضهم عن حكم الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص149، تحت عنوان «بلاغة الاستفهام»","url":""}]},{"id":"s24-155","number":155,"surah":24,"verses":[50],"references":[{"surah":24,"verses":[50]}],"verseLabel":"النور: 50","question":"ما سر الفصل والإضراب بقوله: ﴿بَلْ أُولَئِكَ هُمُ الظَّالِمُونَ﴾؟","answer":"استأنف الحكم عليهم بعد تعداد أحوالهم، وانتقل ببل إلى تقرير ظلمهم الجامع؛ فهو إضراب انتقالي يزيد الذم ولا يبطل ما سبق من مرض وارتياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص156، تحت عنوان «سر الفصل والإضراب في جملة: ﴿بل أولئك﴾»","url":""}]},{"id":"s24-79","number":79,"surah":24,"verses":[51],"references":[{"surah":24,"verses":[51]}],"verseLabel":"النور: 51","question":"لماذا خُص التعبير بفعلي السمع والطاعة في قول المؤمنين: ﴿سَمِعْنَا وَأَطَعْنَا﴾؟","answer":"الفعلان كناية موجزة عن قبول الحكم وكمال الانقياد؛ فالسمع هنا سماع استجابة يعقبه العمل لا مجرد إدراك الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص166، تحت عنوان «تخصيص التعبير بفعلي السمع والطاعة»","url":""}]},{"id":"s24-156","number":156,"surah":24,"verses":[51],"references":[{"surah":24,"verses":[51]}],"verseLabel":"النور: 51","question":"ما بلاغة التضاد بين موقف المؤمنين وموقف المنافقين في سورة النور؟","answer":"تظهر المقابلة حقيقة كل فريق: المنافقون يدعون الطاعة ثم يعرضون، والمؤمنون يسمعون ويطيعون، فيزداد المعنى وضوحًا بضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص169، تحت عنوان «بلاغة التضاد بين هذه الآية وآية المنافقين السابقة»","url":""}]},{"id":"s24-80","number":80,"surah":24,"verses":[52],"references":[{"surah":24,"verses":[52]}],"verseLabel":"النور: 52","question":"ما دلالة الجمع والترتيب في ﴿يُطِعِ اللَّهَ وَرَسُولَهُ وَيَخْشَ اللَّهَ وَيَتَّقْهِ﴾؟","answer":"الطاعة هي المعنى الجامع، ثم تذكر الخشية والتقوى مما يعين على تحقيقها. وينظر المصدر بالخشية إلى ما مضى من تقصير، وبالتقوى إلى ما يستقبل من أحوال وأعمال؛ فيجتمع تدارك السابق والتحرز من المخالفة اللاحقة، ويكتمل بهما معنى الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص172–173، تحت عنوان «سر ذكر معاني الطاعة والخشية والتقوى وترتيبها»","url":""}]},{"id":"s24-81","number":81,"surah":24,"verses":[53],"references":[{"surah":24,"verses":[53]}],"verseLabel":"النور: 53","question":"لماذا وُصفت الطاعة في قوله: ﴿طَاعَةٌ مَعْرُوفَةٌ﴾ بأنها معروفة؟","answer":"فيه تعريض بأن طاعتهم المزعومة معروفة بالنفاق ومخالفة العمل للقول، ويحتمل أن المراد طاعة صادقة في المعروف بدل الأيمان المتكلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص187–188، تحت عنوان «علة التعبير بلفظ: ﴿معروفة﴾»","url":""}]},{"id":"s24-157","number":157,"surah":24,"verses":[53],"references":[{"surah":24,"verses":[53]}],"verseLabel":"النور: 53","question":"ما وجه إيجاز القصر في قوله: ﴿لَا تُقْسِمُوا طَاعَةٌ مَعْرُوفَةٌ﴾؟","answer":"حذف ما دل عليه المقام وأوجز الجواب ليقصر المطلوب على طاعة تظهر بالأفعال، أو ليقرر أن حقيقة طاعتهم معروفة؛ فاستغنى عن تفصيل تكشفه القرينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص188، تحت عنوان «إيجاز القصر ووجهه»","url":""}]},{"id":"s24-82","number":82,"surah":24,"verses":[54],"references":[{"surah":24,"verses":[54]}],"verseLabel":"النور: 54","question":"لماذا أُظهر لفظ ﴿الرَّسُولِ﴾ في قوله: ﴿وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ الْمُبِينُ﴾؟","answer":"الإظهار بدل الضمير يجعل الكلام قاعدة عامة في وظيفة الرسول، ويشعر بأن مقتضى الرسالة البلاغ الواضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص208، تحت عنوان «سر إظهار لفظ ﴿الرسول﴾ دون إضماره»","url":""}]},{"id":"s24-158","number":158,"surah":24,"verses":[54],"references":[{"surah":24,"verses":[54]}],"verseLabel":"النور: 54","question":"ما بلاغة القصر في قوله: ﴿وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ الْمُبِينُ﴾؟","answer":"قصر إضافي يحدد ما يلزم الرسول تجاه المعرضين بالبلاغ، وينفي أن يكون عليه خلق الهداية في القلوب أو حسابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص209، تحت عنوان «بلاغة القصر الإضافي في سياق آية التذييل»","url":""}]},{"id":"s24-83","number":83,"surah":24,"verses":[55],"references":[{"surah":24,"verses":[55]}],"verseLabel":"النور: 55","question":"ما نكتة توالي المؤكدات في وعد الاستخلاف والتمكين والأمن؟","answer":"تتوالى لام القسم ونون التوكيد في ﴿لَيَسْتَخْلِفَنَّهُمْ﴾ و﴿وَلَيُمَكِّنَنَّ﴾ و﴿وَلَيُبَدِّلَنَّهُمْ﴾ لتثبيت الوعد في النفوس وزيادة البشارة، مع بقائه متعلقًا بالإيمان والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص219، تحت عنوان «نكتة توالي المؤكدات في السياق»","url":""}]},{"id":"s24-84","number":84,"surah":24,"verses":[55],"references":[{"surah":24,"verses":[55]}],"verseLabel":"النور: 55","question":"ما دلالة ضمير المتكلم المفرد في قوله: ﴿يَعْبُدُونَنِي﴾؟","answer":"يعين المعبود الحق ويلائم مقام التوحيد؛ فالعبادة خالصة لله وحده لا يشرك فيها غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص231، تحت عنوان «سر التعبير بضمير المتكلم وحده»","url":""}]},{"id":"s24-159","number":159,"surah":24,"verses":[55],"references":[{"surah":24,"verses":[55]}],"verseLabel":"النور: 55","question":"ما دلالة تنكير ﴿شَيْئًا﴾ في قوله: ﴿لَا يُشْرِكُونَ بِي شَيْئًا﴾؟","answer":"وقعت النكرة في سياق النفي فعمّت كل شيء وكل نوع من الشرك، فنفت قليله وكثيره ودقيقه وجليله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص232، تحت عنوان «نكتة تنكير لفظ ﴿شيئا﴾ في السياق»","url":""}]},{"id":"s24-85","number":85,"surah":24,"verses":[58],"references":[{"surah":24,"verses":[58]}],"verseLabel":"النور: 58","question":"ما دلالة تخصيص أوقات الاستئذان الثلاثة للمذكورين في الآية 58؟","answer":"هذه أوقات يغلب فيها التخفف من الثياب أو الانكشاف في المضاجع: قبل الفجر، وعند راحة الظهيرة، وبعد العشاء. فخصصت لحماية الخصوصية، وخفف فيما بينها لكثرة دخول المماليك والصغار وطوافهم؛ فلا يُحمل هذا التخصيص على كل داخل أو على البالغين بإطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص266، تحت عنوان «نكتة تعيين الاستئذان في هذه الأوقات الثلاثة»","url":""}]},{"id":"s24-86","number":86,"surah":24,"verses":[58],"references":[{"surah":24,"verses":[58]}],"verseLabel":"النور: 58","question":"ما دلالة تسمية الأوقات ﴿ثَلَاثُ عَوْرَاتٍ لَكُمْ﴾؟","answer":"سميت الأوقات باسم ما يقع فيها من انكشاف يحتاج إلى الستر، حتى كأنها نفس العورة مبالغة. ويبرز هذا التعبير علة الاستئذان وضرورة صون الخصوصية في تلك الأوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص269، تحت عنوان «بلاغة التعبير عن الأوقات بالعورات»","url":""}]},{"id":"s24-87","number":87,"surah":24,"verses":[59],"references":[{"surah":24,"verses":[59]}],"verseLabel":"النور: 59","question":"لماذا عُلّق بلوغ الأطفال بـ﴿إِذَا﴾ دون «إن»؟","answer":"لأن البلوغ متحقق الوقوع في مجرى الفطرة والعادة، فناسبته إذا، وثبت الانتقال إلى حكم الاستئذان العام عند حصوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص282، تحت عنوان «نكتة تعليق الشرط بـ (إذا) الشرطية»","url":""}]},{"id":"s24-160","number":160,"surah":24,"verses":[59],"references":[{"surah":24,"verses":[59]}],"verseLabel":"النور: 59","question":"ما دلالة حذف متعلق فعل الاستئذان في قوله: ﴿فَلْيَسْتَأْذِنُوا﴾؟","answer":"عمم الحذف مواضع الدخول وأوقاته بعد البلوغ؛ فلم يعد الاستئذان مقصورًا على العورات الثلاث كما كان قبل التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص286، تحت عنوان «دلالة حذف متعلق فعل الاستئذان»","url":""}]},{"id":"s24-88","number":88,"surah":24,"verses":[60],"references":[{"surah":24,"verses":[60]}],"verseLabel":"النور: 60","question":"ما دلالة إضافة ﴿ثِيَابَهُنَّ﴾ إلى القواعد من النساء؟","answer":"تحدد الإضافة أن الرخصة في بعض الثياب الظاهرة الخاصة بهن كالجلباب، لا في كل ساتر يفضي وضعه إلى كشف العورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص307، تحت عنوان «دلالة الإضافة في لفظ ﴿ثيابهن﴾»","url":""}]},{"id":"s24-161","number":161,"surah":24,"verses":[60],"references":[{"surah":24,"verses":[60]}],"verseLabel":"النور: 60","question":"ما بلاغة الحال في قوله: ﴿غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ﴾؟","answer":"جاءت الحال احتراسًا تشريعيًا يضبط الرخصة، فلا يكون وضع الثياب الظاهرة وسيلة إلى إبداء الزينة أو لفت الأنظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص307–308، تحت عنوان «بلاغة الحال في الاحتراس التشريعي»","url":""}]},{"id":"s24-89","number":89,"surah":24,"verses":[60],"references":[{"surah":24,"verses":[60]}],"verseLabel":"النور: 60","question":"ما دلالة عطف حكم الاستحباب في قوله: ﴿وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ﴾ على الرخصة؟","answer":"بعد بيان المباح رغب في الأكمل، فدل على أن إبقاء الثياب الظاهرة ودوام التستر أفضل، مع بقاء أصل الرخصة صحيحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص309–310، تحت عنوان «دلالة عطف حكم الاستحباب على المباح»","url":""}]},{"id":"s24-162","number":162,"surah":24,"verses":[60],"references":[{"surah":24,"verses":[60]}],"verseLabel":"النور: 60","question":"ما بلاغة اختيار لفظ ﴿يَسْتَعْفِفْنَ﴾؟","answer":"صيغة الاستفعال تصور طلب مزيد من العفة والتحفظ؛ فليست المسألة مجرد ترك للرخصة بل قصد إلى الأكمل والأبعد عن الريبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص310، تحت عنوان «بلاغة اختيار مفردة الاستعفاف»","url":""}]},{"id":"s24-90","number":90,"surah":24,"verses":[61],"references":[{"surah":24,"verses":[61]}],"verseLabel":"النور: 61","question":"لماذا خُصت بيوت الأقارب والأصدقاء بالذكر في رخصة الأكل؟","answer":"رفع التفصيل الحرج عما جرت العادة فيه بالتبسط وطيب النفس، مع مراعاة صلة القرابة والصداقة، من غير أن يجعل الرخصة إهدارًا لرضا أصحاب البيوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص335، تحت عنوان «سر تخصيص المنصوص عليهم بالذكر»","url":""}]},{"id":"s24-163","number":163,"surah":24,"verses":[61],"references":[{"surah":24,"verses":[61]}],"verseLabel":"النور: 61","question":"ما نكتة تكرار لفظ ﴿بُيُوتِ﴾ في أصناف رخصة الأكل؟","answer":"يبين التكرار استقلال كل صنف وخصوصيته، ويقرر شمول الحكم له واحدًا واحدًا بدل إذابته في إجمال قد يخفي اختلاف الحقوق والمراتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص336، تحت عنوان «نكتة تكرار لفظ البيوت»","url":""}]},{"id":"s24-91","number":91,"surah":24,"verses":[61],"references":[{"surah":24,"verses":[61]}],"verseLabel":"النور: 61","question":"ما دلالة ﴿أَوْ﴾ في قوله: ﴿جَمِيعًا أَوْ أَشْتَاتًا﴾؟","answer":"تفيد سعة الإباحة بين حال الاجتماع والانفراد وترفع الحرج في كلتيهما، ولا يلزم من الإباحة تساوي الحالين في الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص341، تحت عنوان «دلالة ﴿أو﴾ في قوله: ﴿أو أشتاتا﴾»","url":""}]},{"id":"s24-164","number":164,"surah":24,"verses":[61],"references":[{"surah":24,"verses":[61]}],"verseLabel":"النور: 61","question":"لماذا قُدم ﴿جَمِيعًا﴾ على ﴿أَشْتَاتًا﴾؟","answer":"قُدم الاجتماع لأنه الأصلح للألفة والأقرب إلى الفضل، ثم ذكرت رخصة الانفراد دفعًا للتكلف والحرج بحسب الأحوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص340–341، تحت عنوان «دلالة تقديم ﴿جميعا﴾ على ﴿أشتاتا﴾»","url":""}]},{"id":"s24-92","number":92,"surah":24,"verses":[61],"references":[{"surah":24,"verses":[61]}],"verseLabel":"النور: 61","question":"ما دلالة التعبير بـ﴿فَسَلِّمُوا عَلَى أَنْفُسِكُمْ﴾ عند دخول البيوت؟","answer":"نُزّل أهل البيوت منزلة نفس الداخل لشدة اتصالهم به في الدين والقرابة والمودة، فسلامه عليهم كسلامه على نفسه. وفي ذلك ترغيب في المحبة والأمان والإحسان، وتصوير المؤمنين كأنهم نفس واحدة في تراحمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص344–345، تحت عنوان «فائدة استعمال لفظ ﴿أنفسكم﴾»","url":""}]},{"id":"s24-93","number":93,"surah":24,"verses":[62],"references":[{"surah":24,"verses":[62]}],"verseLabel":"النور: 62","question":"ما نوع القصر في وصف المؤمنين بأنهم لا يذهبون حتى يستأذنوا الرسول، وما بلاغته؟","answer":"قصر صفة المؤمنين الصادقين على ملازمة الأمر الجامع حتى الإذن، فجعل هذا الأدب علامة على الإيمان والانقياد لا مجرد إجراء مجلسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص362، تحت عنوان «نوع القصر وبلاغته»","url":""}]},{"id":"s24-165","number":165,"surah":24,"verses":[62],"references":[{"surah":24,"verses":[62]}],"verseLabel":"النور: 62","question":"ما التعريض في قوله: ﴿لَمْ يَذْهَبُوا حَتَّى يَسْتَأْذِنُوهُ﴾؟","answer":"مدح المؤمنين بالاستئذان يعرّض بالمنافقين الذين يتسللون بغير إذن، فيكشف سوء أدبهم من غير تصريح مباشر بهم في الجملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص368، تحت عنوان «بلاغة التعريض في ﴿لم يذهبوا حتى يستأذنوه﴾»","url":""}]},{"id":"s24-94","number":94,"surah":24,"verses":[62],"references":[{"surah":24,"verses":[62]}],"verseLabel":"النور: 62","question":"ما غرض ذكر ﴿بَعْضِ﴾ وإضافته في قوله: ﴿لِبَعْضِ شَأْنِهِمْ﴾؟","answer":"تبين أن حاجة خاصة معتبرة قد تكفي للاستئذان، ولو لم تستغرق شؤون صاحبها كلها، مع منع اتخاذ كل ذريعة عذرًا للانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص376، تحت عنوان «غرض ذكر لفظ (بعض) وإضافته»","url":""}]},{"id":"s24-166","number":166,"surah":24,"verses":[62],"references":[{"surah":24,"verses":[62]}],"verseLabel":"النور: 62","question":"لماذا اختير لفظ ﴿الشَّأْنِ﴾ دون الأمر في عذر الاستئذان؟","answer":"الشأن أمر له أهمية وعناية، فناسب اشتراط حاجة جديرة بالنظر للانصراف عن الأمر الجامع، ولم يجعل الإذن تابعًا لأمر تافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص376–377، تحت عنوان «نكتة استعمال لفظ (الشأن) دون (الأمر)»","url":""}]},{"id":"s24-95","number":95,"surah":24,"verses":[63],"references":[{"surah":24,"verses":[63]}],"verseLabel":"النور: 63","question":"ما دلالة النهي في ﴿لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا﴾؟","answer":"يحتمل أن يكون المراد نداءهم الرسول، فيؤمرون بتوقيره في اللفظ وهيئة النداء، لا مناداته كنداء أقرانهم. ويحتمل أن يكون المراد دعوته إياهم، فلا يسوون الاستجابة له بالتساهل في دعوات بعضهم بعضًا. ويجمع الوجهين تعظيم مقام الرسالة والأدب والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص387–388، تحت عنوان «نوع إضافة لفظ ﴿دعاء﴾ إلى ﴿الرسول﴾»","url":""}]},{"id":"s24-96","number":96,"surah":24,"verses":[63],"references":[{"surah":24,"verses":[63]}],"verseLabel":"النور: 63","question":"ما بلاغة التضمين في قوله: ﴿يُخَالِفُونَ عَنْ أَمْرِهِ﴾؟","answer":"عُديت المخالفة بعن لتضمنها معنى الإعراض أو الصد، فصوّر المخالف منحرفًا منصرفًا عن أمر الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص396، تحت عنوان «بلاغة التضمين»","url":""}]},{"id":"s24-167","number":167,"surah":24,"verses":[63],"references":[{"surah":24,"verses":[63]}],"verseLabel":"النور: 63","question":"ما دلالة تنكير ﴿فِتْنَةٌ﴾ في وعيد المخالفين؟","answer":"وسع التنكير صور الابتلاء وهوّلها؛ فقد تكون بلاءً ظاهرًا أو استدراجًا بالنعم أو زيغًا في القلب، فلا يأمن المخالف نوعًا من الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص397–398، تحت عنوان «دلالة مفردة ﴿فتنة﴾ منكرة»","url":""}]},{"id":"s24-168","number":168,"surah":24,"verses":[63],"references":[{"surah":24,"verses":[63]}],"verseLabel":"النور: 63","question":"ما معنى ﴿أَوْ﴾ وتكرار الإصابة في قوله: ﴿أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ﴾؟","answer":"تفصل أو نوعي الوعيد من غير أن تمنع اجتماعهما، وتكرار الفعل يستقل بكل إصابة ويزيد وقع التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص398، تحت عنوان «معنى حرف ﴿أو﴾ وتكرار فعل (الإصابة)»","url":""}]},{"id":"s24-97","number":97,"surah":24,"verses":[64],"references":[{"surah":24,"verses":[64]}],"verseLabel":"النور: 64","question":"ما غرض التحقيق بـ﴿قَدْ﴾ في قوله: ﴿قَدْ يَعْلَمُ مَا أَنْتُمْ عَلَيْهِ﴾؟","answer":"تؤكد قد تحقق علم الله بأحوالهم الخفية، وترد على من يتوهم أن تسلله أو مخالفته يمكن أن يخفيا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص404–405، تحت عنوان «غرض التحقيق بأداة ﴿قد﴾»","url":""}]},{"id":"s24-169","number":169,"surah":24,"verses":[64],"references":[{"surah":24,"verses":[64]}],"verseLabel":"النور: 64","question":"ما نكتة استعمال الموصول وصلته في قوله: ﴿مَا أَنْتُمْ عَلَيْهِ﴾؟","answer":"عم الموصول أحوالهم التي استقروا عليها من طاعة أو مخالفة، وجاءت صلته كناية موجزة عن الهيئة الباطنة والظاهرة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص406، تحت عنوان «نكتة استعمال الموصول وصلته»","url":""}]},{"id":"s24-170","number":170,"surah":24,"verses":[64],"references":[{"surah":24,"verses":[64]}],"verseLabel":"النور: 64","question":"ما الكناية في قوله: ﴿فَيُنَبِّئُهُمْ بِمَا عَمِلُوا﴾؟","answer":"الإنباء بالأعمال كناية عن المحاسبة والجزاء عليها؛ فالختام لا يقف عند كشف ما فعلوا بل يحذر من تبعته عند الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص410، تحت عنوان «بلاغة الكناية في قوله: ﴿فينبئهم﴾»","url":""}]},{"id":"s24-171","number":171,"surah":24,"verses":[7,9],"references":[{"surah":24,"verses":[7,9]}],"verseLabel":"النور: 7، 9","question":"ما سر اختيار اللعنة في يمين الزوج، واختيار الغضب في يمين الزوجة؟","answer":"اللعنة هي الطرد والإبعاد من رحمة الله، وهي ملائمة للزوج إن كان كاذبًا؛ لأنه بقذفه الكاذب يعرّض زوجته للعقوبة والفضيحة. أما الزوجة، فإن كانت كاذبة، فقد قارفت الفاحشة ثم دفعت الحد عن نفسها بالأيمان؛ فناسب حالها الغضب. فاختلاف اللفظين تابع لاختلاف الجناية المترتبة على كذب كل واحد منهما.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين اللعنة والغضب؟» – برنامج لمسات بيانية، سورة النور، الآيتان 7 و9.","url":""}]},{"id":"s24-172","number":172,"surah":24,"verses":[52],"references":[{"surah":24,"verses":[52]}],"verseLabel":"النور: 52","question":"ما السر الصوتي واللغوي في قراءة حفص: ﴿وَيَتَّقْهِ﴾ بسكون القاف؟","answer":"القياس المشهور بعد حذف حرف العلة أن تُحرّك القاف بالكسر: «ويتّقِه»، لكن تسكين القاف لغة لبعض العرب في المعتل المحذوف الآخر، فيعاملونه معاملة المجزوم الصحيح. وقد جاءت قراءة حفص على هذه اللغة، وفي السكون تخفيف للنطق. والهاء مفعول به، أي: يتقي الله.","sources":[{"label":"فاضل السامرائي، «ما اللمسة البيانية في كلمة ويتقه بتسكين القاف؟» – سورة النور، الآية 52.","url":""}]},{"id":"s24-173","number":173,"surah":24,"verses":[58,59],"references":[{"surah":24,"verses":[58,59]}],"verseLabel":"النور: 58، 59","question":"ما سر التعريف في ﴿يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ﴾، ثم الإضافة في ﴿يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ﴾؟","answer":"الآية الأولى تعالج استئذان من لم يبلغوا الحلم في أوقات مخصوصة ذات علامات ظاهرة، فجاء ﴿الْآيَاتِ﴾. أما الثانية فتنقل من بلغ الحلم إلى حكم البالغين العام في الاستئذان، وهو حكم إلهي لازم كاستئذان الذين من قبلهم، فجاءت الإضافة المشرفة والمؤكدة للنسبة: ﴿آيَاتِهِ﴾. فاختلاف الخاتمتين يتبع انتقال المخاطَب من طور الصغر إلى التكليف الكامل.","sources":[{"label":"فاضل السامرائي، «اللمسة البيانية في الآيات وآياته» – سورة النور، الآيتان 58 و59.","url":""}]},{"id":"s24-174","number":174,"surah":24,"verses":[64],"references":[{"surah":24,"verses":[64]}],"verseLabel":"النور: 64","question":"هل تفيد ﴿قَدْ﴾ التقليل في قوله: ﴿قَدْ يَعْلَمُ مَا أَنْتُمْ عَلَيْهِ﴾؟ وما سر دخولها على علم الله؟","answer":"«قد» مع المضارع لا تنحصر في التقليل؛ فمن معانيها التحقيق والتكثير أيضًا، ويعين السياق المراد. وعلم الله متحقق محيط، فلا يمكن حملها هنا على قلة العلم أو تردده؛ بل تفيد تحقيقه وتقريره في مقام التحذير والمحاسبة. ثم يؤكد ختام السورة هذا الإحاطة بقوله: ﴿وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ﴾.","sources":[{"label":"فاضل السامرائي، «لماذا جاء العلم بعد قد؟» – سورة النور، الآية 64.","url":""}]},{"id":"s24-175","number":175,"surah":24,"verses":[7,9],"references":[{"surah":24,"verses":[7,9]}],"verseLabel":"النور: 7، 9","question":"ما دلالة رفع ﴿وَالْخَامِسَةُ﴾ في يمين الزوج، ونصب ﴿وَالْخَامِسَةَ﴾ في يمين الزوجة؟","answer":"جاءت الأولى مرفوعة عطفًا على ﴿أَرْبَعُ شَهَادَاتٍ﴾، وهي خبر في قوله: ﴿فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ﴾. وجاءت الثانية منصوبة عطفًا على ﴿أَرْبَعَ شَهَادَاتٍ﴾ الواقعة مفعولًا به في قوله: ﴿أَنْ تَشْهَدَ أَرْبَعَ شَهَادَاتٍ﴾. فالحركة الإعرابية تكشف اختلاف البناءين مع بقاء العدد والمعنى العام متقابلين.","sources":[{"label":"فاضل السامرائي، «ما سبب الاختلاف في حركة كلمة الخامسة؟» – برنامج لمسات بيانية، سورة النور، الآيتان 7 و9.","url":""}]},{"id":"s24-176","number":176,"surah":24,"verses":[20],"references":[{"surah":24,"verses":[20]}],"verseLabel":"النور: 20","question":"ما سر مجيء ﴿وَأَنَّ اللَّهَ رَءُوفٌ رَحِيمٌ﴾ من غير لام التوكيد التي جاءت في قوله: ﴿إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ﴾؟","answer":"مقدار التوكيد يتبع حاجة المقام؛ فقد يجتمع «إنّ» واللام حين يكون المقام محتاجًا إلى تقوية الخبر، وقد يكتفى بأداة واحدة. ففي آية البقرة جاء السياق في تعداد النعم وطمأنة المؤمنين إلى عدم ضياع إيمانهم، فازداد التوكيد، أما آية النور فلم يحتج مقامها إلى اللام. فليس اختلاف الصياغة ترادفًا، بل موازنة دقيقة لدرجة التوكيد.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص14، مبحث «التوكيد باللام في: إن الله بالناس لرؤوف رحيم، وحذفه في: وأن الله رؤوف رحيم»، النسخة المصورة.","url":""}]},{"id":"s24-177","number":177,"surah":24,"verses":[29],"references":[{"surah":24,"verses":[29]}],"verseLabel":"النور: 29","question":"ما سر حذف ﴿كُنْتُمْ﴾ من قوله: ﴿وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ﴾، مع ورودها في البقرة: ﴿وَمَا كُنْتُمْ تَكْتُمُونَ﴾؟","answer":"في خطاب الملائكة بالبقرة كان الحديث عما استقر كتمانه في نفوسهم قبل ذلك، فناسب ﴿كُنْتُمْ تَكْتُمُونَ﴾ الدالة على حالة ماضية ممتدة. أما آية النور فمتصلة بدخول البيوت غير المسكونة؛ والمقصود ما يظهره الداخل وما يخفيه وقت الدخول: أهو لمتاعه أم لتجسس أو فساد؟ لذلك جاء المضارع مباشرًا من غير ﴿كنتم﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص9، مبحث «وما كنتم تكتمون وما تكتمون»، النسخة المصورة. وانظر أيضًا المقطع المباشر على منصة باحث.","url":""}]},{"id":"s24-178","number":178,"surah":24,"verses":[34],"references":[{"surah":24,"verses":[34]}],"verseLabel":"النور: 34","question":"ما الفرق البياني بين ﴿آيَاتٍ بَيِّنَاتٍ﴾ و«آيات مبيِّنات»؟","answer":"«بيِّنات» تصف الآيات بأنها واضحة ظاهرة الدلالة في ذاتها، مثل قولنا: أمر بيِّن. أما «مبيِّنات» فتفيد أنها توضّح لغيرها وتكشف المعنى والحكم. فالفرق بين الوصفين هو الفرق بين الوضوح الذاتي والقدرة على الإيضاح، ولكل قراءة أو صيغة مجالها الدلالي.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين آيات بينات وآيات مبيّنات؟» – سورة النور، الآية 34.","url":""}]},{"id":"s24-179","number":179,"surah":24,"verses":[35],"references":[{"surah":24,"verses":[35]}],"verseLabel":"النور: 35","question":"ما سر التعبير بـ﴿نُورُ السَّمَاوَاتِ وَالْأَرْضِ﴾ لا بـ«ضياء السماوات والأرض»؟","answer":"الضياء حالة قوية من حالات النور، أما النور فأوسع منه؛ إذ يشمل بدايات الإشراق ومراتب النور كلها حتى يشتد فيصير ضياءً. واختيار الأعم يفتح الدلالة على أنواع من النور نعرفها وأخرى لا ندرك حقيقتها. كما أن ختام الآية ﴿يَهْدِي اللَّهُ لِنُورِهِ مَنْ يَشَاءُ﴾ يقوّي معنى الهداية الشاملة في لفظ النور.","sources":[{"label":"فاضل السامرائي، «ما دلالة استخدام كلمة نور؟» – سورة النور، الآية 35.","url":""}]},{"id":"s24-180","number":180,"surah":24,"verses":[53],"references":[{"surah":24,"verses":[53]}],"verseLabel":"النور: 53","question":"ما دلالة تقديم الخبرة في قوله: ﴿إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ﴾، وتأخيرها في مواضع أخرى: ﴿بِمَا تَعْمَلُونَ خَبِيرٌ﴾؟","answer":"إذا كان محور الكلام الإنسان أو عمله قُدّم العمل، فيقال: ﴿بِمَا تَعْمَلُونَ خَبِيرٌ﴾. وإذا كان الكلام على الله تعالى أو على الخبرة والأمور القلبية قُدّمت الخبرة: ﴿خَبِيرٌ بِمَا تَعْمَلُونَ﴾. فالتقديم يضع بؤرة العبارة في الموضع الذي يخدم سياقها.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين بما تعملون خبير وخبير بما تعملون؟» – سورة النور، الآية 53.","url":""}]},{"id":"s24-181","number":181,"surah":24,"verses":[58,59],"references":[{"surah":24,"verses":[58,59]}],"verseLabel":"النور: 58–59","question":"ما دلالة الانتقال من ﴿الَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ﴾ إلى ﴿الْأَطْفَالُ مِنْكُمُ﴾ عند بلوغهم؟","answer":"لفظ «الطفل» قد يطلق على المفرد والجمع باعتبار الجنس، لكن آية البلوغ تتعلق بأفراد صار لكل واحد منهم حكم البالغ ونظرته ومسؤوليته. لذلك جاء الجمع الصريح ﴿الْأَطْفَالُ﴾، ثم أُلحقوا بمن سبقهم من البالغين في الاستئذان. فانتقال اللفظ يواكب انتقال الحكم من معاملة الجنس الصغير إلى تكليف الأفراد.","sources":[{"label":"فاضل السامرائي، «لماذا أفردت آية للأطفال الذين بلغوا الحلم؟» – سورة النور، الآيتان 58 و59.","url":""}]},{"id":"s24-182","number":182,"surah":24,"verses":[61],"references":[{"surah":24,"verses":[61]}],"verseLabel":"النور: 61","question":"ما سر إفراد ﴿الطِّفْلِ﴾ ثم وصفه بالجمع في قوله: ﴿أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا﴾؟","answer":"«الطفل» من الألفاظ التي تستعمل للمفرد وللجنس الجمعي؛ فالإفراد في اللفظ يلحظ الجنس، بينما ﴿الَّذِينَ﴾ تلحظ الأفراد الداخلين تحته. واجتماع الاعتبارين عربي فصيح: مفرد في صورته، جمع في معناه. وبذلك استوعب التعبير طائفة الأطفال بلفظ موجز من غير إخلال بالمطابقة المعنوية.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص66، «الطفل الذين لم يظهروا على عورات النساء».","url":""}]},{"id":"s25-1","number":1,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]},{"surah":67,"verses":[1]}],"verseLabel":"الفرقان: 1؛ الملك: 1","question":"ما بلاغة صيغة ﴿تَبَارَكَ﴾ في مطلع سورة الفرقان؟","answer":"تفيد المبالغة في البركة وكثرة فيض الخيرات وثبوتها لله، فتهيئ لتعظيم نعمة الفرقان المنزل على عبده.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص430، تحت عنوان «بلاغة صيغة ﴿تبارك﴾»","url":""}]},{"id":"s25-85","number":85,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]},{"surah":67,"verses":[1]}],"verseLabel":"الفرقان: 1؛ الملك: 1","question":"ما فائدة تعقيب تنزيل الفرقان على الثناء بـ﴿تَبَارَكَ﴾؟","answer":"يبيّن أن تنزيل القرآن من أعظم آثار بركة الله وخيره، وينبه إلى كثرة منافعه وعموم هدايته للعالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص432، تحت عنوان «فائدة تعقيب تنزيل القرآن على لفظ الثناء ﴿تبارك﴾»","url":""}]},{"id":"s25-86","number":86,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]},{"surah":67,"verses":[1]}],"verseLabel":"الفرقان: 1؛ الملك: 1","question":"ما براعة استهلال سورة الملك بقوله: ﴿تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ﴾؟","answer":"افتتحت السورة بتنزيه الله وتعظيمه وإثبات انفراده بالملك والقدرة، فمهّدت لمقاصدها في إظهار كمال التدبير والرد على ضلال المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص692–693، تحت عنوان «براعة الاستهلال في السورة الكريمة»","url":""}]},{"id":"s25-87","number":87,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]},{"surah":67,"verses":[1]}],"verseLabel":"الفرقان: 1؛ الملك: 1","question":"ما بلاغة التعبير بالفعل ﴿تَبَارَكَ﴾ مادة وصيغة في مطلع الملك؟","answer":"تدل المادة على كثرة الخير وثبوته ودوامه، وتفيد الصيغة تعاظمه وكماله، فاختصت بالله في مقام تعظيم ملكه وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص694، تحت عنوان «بلاغة التعبير بالفعل ﴿تبارك﴾ مادة وصيغة»","url":""}]},{"id":"s25-2","number":2,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]}],"verseLabel":"الفرقان: 1","question":"ما سر التعبير عن القرآن باسم ﴿الفرقان﴾؟","answer":"للدلالة على تمييزه الحق من الباطل؛ والتعبير بالمصدر مبالغة في هذا الفصل، لما اشتمل عليه القرآن من دلائل الوحدانية وما يبين صدق إنزاله من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص432، تحت عنوان «توجيه تخصيص اسم ﴿الفرقان﴾ بالذكر»","url":""}]},{"id":"s25-3","number":3,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]}],"verseLabel":"الفرقان: 1","question":"ما فائدة حرف الاستعلاء في قوله: ﴿نَزَّلَ الْفُرْقَانَ عَلَى عَبْدِهِ﴾؟","answer":"يفيد تمكن الوحي من قلب المتلقي واستقراره عليه، مع استحضار نزوله من علو وشرف المنزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص432–433، تحت عنوان «فائدة استعمال حرف الاستعلاء»","url":""}]},{"id":"s25-88","number":88,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]}],"verseLabel":"الفرقان: 1","question":"ما بلاغة وصف الرسول بالعبودية في قوله: ﴿عَلَى عَبْدِهِ﴾؟","answer":"إضافة العبد إلى الله تشريف للرسول، والعبودية لله كمال يناسب مقام تلقي الوحي والقيام بتبليغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص433، تحت عنوان «بلاغة اختيار وصف العبودية ﴿عبده﴾»","url":""}]},{"id":"s25-4","number":4,"surah":25,"verses":[1],"references":[{"surah":25,"verses":[1]}],"verseLabel":"الفرقان: 1","question":"ما سر تخصيص ﴿نذيرا﴾ بالذكر دون «بشيرا»؟","answer":"لأن المقام مقام تهديد للمشركين المكذبين، فناسبه إبراز الإنذار. وهذا لا ينفي البشارة؛ فقد استغني عن التصريح بها، وفي افتتاح السورة بـ﴿تبارك﴾ وما يتصل به من الخير إشارة إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص435، تحت عنوان «توجيه تخصيص ﴿نذيرا﴾ بالذكر دون (بشيرا)»","url":""}]},{"id":"s25-5","number":5,"surah":25,"verses":[2],"references":[{"surah":25,"verses":[2]}],"verseLabel":"الفرقان: 2","question":"لماذا عُطفت جملة ﴿فَقَدَّرَهُ﴾ على قوله: ﴿خَلَقَ كُلَّ شَيْءٍ﴾؟","answer":"أضاف العطف إلى أصل الإيجاد معنى إحكام المخلوقات وتحديد خصائصها ومقاديرها ووظائفها على نظام ينافي العبث.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص443–444، تحت عنوان «علة عطف جملة ﴿فقدره﴾ على ما قبلها»","url":""}]},{"id":"s25-89","number":89,"surah":25,"verses":[2],"references":[{"surah":25,"verses":[2]}],"verseLabel":"الفرقان: 2","question":"ما دلالة المفعول المطلق في قوله: ﴿فَقَدَّرَهُ تَقْدِيرًا﴾؟","answer":"أكد المصدر تمام التقدير وإحكامه، وأن كل مخلوق جرى على مقدار يناسب ما أعد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص444، تحت عنوان «دلالة التوكيد في المفعول المطلق»","url":""}]},{"id":"s25-6","number":6,"surah":25,"verses":[3],"references":[{"surah":25,"verses":[3]}],"verseLabel":"الفرقان: 3","question":"ما دلالة الجمع بين ﴿لا يخلقون شيئا﴾ و﴿وهم يخلقون﴾ في وصف المعبودات؟","answer":"نفي خلقهم لغيرهم لا يغني عن التصريح بأنهم أنفسهم مخلوقون؛ فجاءت الجملة المثبتة لرفع هذا الاحتمال وتأكيد عجزهم وافتقارهم إلى خالق، وبذلك يبطل استحقاقهم للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص451–452، تحت عنوان «فائدة عطف الجملة المثبتة على المنفية»","url":""}]},{"id":"s25-7","number":7,"surah":25,"verses":[3],"references":[{"surah":25,"verses":[3]}],"verseLabel":"الفرقان: 3","question":"ما سر تكرار ﴿يملكون﴾ في نفي الضر والنفع ثم الموت والحياة والنشور عن المعبودات؟","answer":"للتنبيه إلى اختلاف جهتي النفي: فالأولى تتناول الضر والنفع المتعلقين بأحوال الحياة، والثانية تتناول أصل الحياة وزوالها والبعث بعدها. فإذا عجزت المعبودات عن التصرف في هذه الأمور لأنفسها، فعجزها عن نفع عابديها أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص458، تحت عنوان «نكتة تكرار فعل ﴿يملكون﴾»","url":""}]},{"id":"s25-8","number":8,"surah":25,"verses":[4],"references":[{"surah":25,"verses":[4]}],"verseLabel":"الفرقان: 4","question":"ما بلاغة استعمال ﴿إِفْكٌ﴾ في اتهامهم القرآن؟","answer":"الإفك كذب مصروف عن وجه الحق بالغ العظم، فاختاره المكذبون لتشنيع القرآن وتنفير الناس منه، فانقلب الوصف شاهدًا على فظاعة قولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص470، تحت عنوان «بلاغة استعمال مفردة ﴿إفك﴾»","url":""}]},{"id":"s25-90","number":90,"surah":25,"verses":[4],"references":[{"surah":25,"verses":[4]}],"verseLabel":"الفرقان: 4","question":"ما دلالة الواو في قوله: ﴿وَأَعَانَهُ عَلَيْهِ قَوْمٌ آخَرُونَ﴾؟","answer":"عطفت تهمة الاستعانة على تهمة الافتراء، ليزعموا أن إحكام القرآن نتاج جماعة لا اختلاق فرد، فجمعوا باطلًا إلى باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص472، تحت عنوان «معنى (الواو) ودلالة عطف الجملة على الجملة»","url":""}]},{"id":"s25-91","number":91,"surah":25,"verses":[4],"references":[{"surah":25,"verses":[4]}],"verseLabel":"الفرقان: 4","question":"ما دلالة اقتران وصفي ﴿ظُلْمًا وَزُورًا﴾ في الرد عليهم؟","answer":"جمع الرد بين الظلم لمجاوزتهم الحق ونسبة الوحي إلى الافتراء، والزور لانحراف قولهم عن الحقيقة واختلاقهم الإعانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص478، تحت عنوان «دلالة اقتران وصفي ﴿ظلما وزورا﴾»","url":""}]},{"id":"s25-9","number":9,"surah":25,"verses":[5],"references":[{"surah":25,"verses":[5]}],"verseLabel":"الفرقان: 5","question":"ما نكتة الجملة الاسمية في قولهم: ﴿أَسَاطِيرُ الْأَوَّلِينَ﴾؟","answer":"صاغوا تهمتهم في جملة اسمية توهم الثبوت والاستقرار، كأن كون القرآن أساطير حقيقة مقررة لا دعوى تحتاج إلى دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص483، تحت عنوان «نكتة التعبير بالجملة الاسمية»","url":""}]},{"id":"s25-92","number":92,"surah":25,"verses":[5],"references":[{"surah":25,"verses":[5]}],"verseLabel":"الفرقان: 5","question":"ما نكتة الجمع المضاف في ﴿أَسَاطِيرُ الْأَوَّلِينَ﴾؟","answer":"يوهم الجمع كثرة القصص الباطلة، وإضافتها إلى الأولين توحي في زعمهم بقدمها وتداولها من قبل، لينفوا عنها الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص483، تحت عنوان «نكتة الجمع المضاف»","url":""}]},{"id":"s25-10","number":10,"surah":25,"verses":[5],"references":[{"surah":25,"verses":[5]}],"verseLabel":"الفرقان: 5","question":"ما بلاغة اختيار لفظ ﴿تُمْلَى﴾ في قولهم: ﴿فَهِيَ تُمْلَى عَلَيْهِ﴾؟","answer":"اختاروا الإملاء لما فيه من تأن وضبط وتلقين، ليزعموا أن إحكام ما يتلوه نتج من تكرار القراءة عليه لا من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص486، تحت عنوان «بلاغة اختيار مفردة ﴿تملى﴾»","url":""}]},{"id":"s25-93","number":93,"surah":25,"verses":[5],"references":[{"surah":25,"verses":[5]}],"verseLabel":"الفرقان: 5","question":"ما فن الطباق في قوله: ﴿بُكْرَةً وَأَصِيلًا﴾؟","answer":"جمع أول النهار وآخره لتصوير استمرار الإملاء في زعمهم، ويحتمل أن يريدوا الوقتين نفسيهما بوصفهما وقتي فراغ، وفي الحالين يقوى افتراؤهم بالجمع بين الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص488، تحت عنوان «فن الطباق»","url":""}]},{"id":"s25-11","number":11,"surah":25,"verses":[6],"references":[{"surah":25,"verses":[6]}],"verseLabel":"الفرقان: 6","question":"ما فائدة الاسم الموصول في قوله: ﴿أَنْزَلَهُ الَّذِي يَعْلَمُ السِّرَّ﴾؟","answer":"عرّف منزل القرآن بصلته الدالة على إحاطة العلم، فكانت الصلة نفسها حجة على صدق الوحي ومناسبة لما في القرآن من علم محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص491، تحت عنوان «فائدة التعبير بالاسم الموصول»","url":""}]},{"id":"s25-94","number":94,"surah":25,"verses":[6],"references":[{"surah":25,"verses":[6]}],"verseLabel":"الفرقان: 6","question":"ما التعريض في استعمال لفظ ﴿السِّرَّ﴾ ردًا على المكذبين؟","answer":"فيه تعريض بأن افتراءهم الخفي والظاهر معلوم لله وسيجازيهم عليه، وأن حقيقة مصدر القرآن لا تخفى على من يعلم أسرار السماوات والأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص492، تحت عنوان «بلاغة التعريض باستعمال مفردة ﴿السر﴾»","url":""}]},{"id":"s25-12","number":12,"surah":25,"verses":[7],"references":[{"surah":25,"verses":[7]}],"verseLabel":"الفرقان: 7","question":"لماذا خص المشركون أكل الرسول الطعام ومشيه في الأسواق بالاعتراض؟","answer":"اختاروا حالين بشريتين ظاهرتين: الحاجة إلى الطعام والسعي في طلب المعاش، وجعلوهما باطلًا ذريعة لإنكار الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص503، تحت عنوان «توجيه تخصيص الأكل والمشي بالذكر»","url":""}]},{"id":"s25-95","number":95,"surah":25,"verses":[7],"references":[{"surah":25,"verses":[7]}],"verseLabel":"الفرقان: 7","question":"لماذا أُطنب لاحقًا بوصف الرسل السابقين بأنهم يأكلون الطعام ويمشون في الأسواق؟","answer":"أعيد الوصف نفسه لإبطال أصل اعتراضهم؛ فالبشرية والحاجة المعتادة صفة للرسل جميعًا ولا تنافي اصطفاءهم للوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص617، تحت عنوان «علة الإطناب في وصف حال المرسلين»","url":""}]},{"id":"s25-13","number":13,"surah":25,"verses":[7],"references":[{"surah":25,"verses":[7]}],"verseLabel":"الفرقان: 7","question":"ما سر التعبير بـ﴿إليه﴾ دون «عليه» في قولهم ﴿لولا أنزل إليه ملك﴾؟","answer":"لأن مرادهم ملك يشاهدونه مع الرسول ويصحبه في الإنذار، لا مجرد ملك ينزل عليه بالوحي. فـ﴿إليه﴾ تناسب الوصول إليه ومشاهدته معه، ويؤكد ذلك قولهم ﴿فيكون معه نذيرا﴾؛ أما «عليه» فلا تؤدي في هذا المقام مرادهم نفسه من المصاحبة المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص504، تحت عنوان «نكتة استعمال ﴿إليه﴾ دون (عليه)»","url":""}]},{"id":"s25-14","number":14,"surah":25,"verses":[8],"references":[{"surah":25,"verses":[8]}],"verseLabel":"الفرقان: 8","question":"ما توجيه ترتيب مطالب المشركين للرسول: الملك، ثم الكنز، ثم الجنة؟","answer":"رتبوا مطالبهم تنازليًا في زعمهم: ملك يؤيده، ثم كنز يغنيه، ثم جنة تكفيه الطعام؛ فكشف الترتيب جعلهم المال والاستغناء معيارًا للرسالة وقصدهم التعجيز.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص511، تحت عنوان «توجيه ترتيب المطالب»","url":""}]},{"id":"s25-16","number":16,"surah":25,"verses":[10],"references":[{"surah":25,"verses":[10]}],"verseLabel":"الفرقان: 10","question":"ما بلاغة الاستئناف في قوله: ﴿تَبَارَكَ الَّذِي إِنْ شَاءَ جَعَلَ لَكَ خَيْرًا مِنْ ذَلِكَ﴾؟","answer":"استأنف الرد لتنزيه الله وتعظيم قدرته بعد مقترحاتهم، وقرر أن ترك إجابتهم ليس عجزًا بل حكمة واختيارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص525، تحت عنوان «بلاغة الاستئناف ودلالته»","url":""}]},{"id":"s25-96","number":96,"surah":25,"verses":[10],"references":[{"surah":25,"verses":[10]}],"verseLabel":"الفرقان: 10","question":"ما بلاغة جملة الشرط في قوله: ﴿إِنْ شَاءَ جَعَلَ لَكَ خَيْرًا مِنْ ذَلِكَ﴾؟","answer":"علقت العطاء بالمشيئة الإلهية، فأثبتت القدرة على ما هو خير من مقترحاتهم وردت الأمر إلى الحكمة لا إلى تعنت المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص526، تحت عنوان «بلاغة التعبير بجملة الشرط»","url":""}]},{"id":"s25-17","number":17,"surah":25,"verses":[11],"references":[{"surah":25,"verses":[11]}],"verseLabel":"الفرقان: 11","question":"ما دلالة ﴿بَلْ﴾ في قوله: ﴿بَلْ كَذَّبُوا بِالسَّاعَةِ﴾؟","answer":"إضراب انتقالي ينقل من اعتراضاتهم على الرسول إلى أصل أعمق من ضلالهم، وهو تكذيب البعث والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص533، تحت عنوان «معنى ﴿بل﴾ ودلالتها»","url":""}]},{"id":"s25-97","number":97,"surah":25,"verses":[11],"references":[{"surah":25,"verses":[11]}],"verseLabel":"الفرقان: 11","question":"ما دلالة الواو في قوله: ﴿وَأَعْتَدْنَا لِمَنْ كَذَّبَ بِالسَّاعَةِ سَعِيرًا﴾؟","answer":"عطفت الوعيد على كشف تكذيبهم، فربطت الجريمة بعاقبتها المهيأة وأكدت أن الإنكار لا ينتهي إلى جدل بلا جزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص534، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s25-18","number":18,"surah":25,"verses":[12],"references":[{"surah":25,"verses":[12]}],"verseLabel":"الفرقان: 12","question":"ما نكتة نسبة الرؤية إلى النار في قوله: ﴿إِذَا رَأَتْهُمْ﴾؟","answer":"شُخصت النار كذات حية مترصدة ترى أهلها وتستقبلهم بالغيظ، ويذكر وجه إسناد رؤية خزنتها إليها؛ وكلاهما يهوّل المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص541، تحت عنوان «نكتة نسبة الرؤية إلى النار»","url":""}]},{"id":"s25-98","number":98,"surah":25,"verses":[12],"references":[{"surah":25,"verses":[12]}],"verseLabel":"الفرقان: 12","question":"ما دلالة وصف المكان بالبعيد في قوله: ﴿مِنْ مَكَانٍ بَعِيدٍ﴾؟","answer":"يطيل البعد زمن توقع العذاب ويجعل صوت النار ومشهدها يبلغانهم قبل الوصول، فيتضاعف الرعب والانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص542، تحت عنوان «دلالة وصف المكان بالبعيد»","url":""}]},{"id":"s25-99","number":99,"surah":25,"verses":[12],"references":[{"surah":25,"verses":[12]}],"verseLabel":"الفرقان: 12","question":"ما دلالة استعارة التغيظ والزفير للنار؟","answer":"شُبه غليان النار وصوتها بحال مغتاظ يزفر، فصارت في التصوير كأنها حية شديدة الحنق على أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص545، تحت عنوان «دلالة استعارة التغيظ والزفير للنار»","url":""}]},{"id":"s25-100","number":100,"surah":25,"verses":[12],"references":[{"surah":25,"verses":[12]}],"verseLabel":"الفرقان: 12","question":"ما توجيه الاستعارة التمثيلية في قوله: ﴿سَمِعُوا لَهَا تَغَيُّظًا وَزَفِيرًا﴾؟","answer":"شُبه مجموع حال النار في شدة اضطرامها وصوتها بحال إنسان امتلأ غيظًا وأطلق زفيره؛ فوجه الشبه هيئة مركبة لا لفظًا مفردًا وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص545، تحت عنوان «توجيه الاستعارة التمثيلية في التركيب»","url":""}]},{"id":"s25-19","number":19,"surah":25,"verses":[13],"references":[{"surah":25,"verses":[13]}],"verseLabel":"الفرقان: 13","question":"ما نكتة وصف مكان الإلقاء في النار بالضيق؟","answer":"يجمع الوصف حرارة العذاب إلى شدة الحصر، فيمنع الانبساط والحركة ويزيد الكرب فوق كرب النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص553، تحت عنوان «نكتة وصف المكان بالضيق»","url":""}]},{"id":"s25-101","number":101,"surah":25,"verses":[13],"references":[{"surah":25,"verses":[13]}],"verseLabel":"الفرقان: 13","question":"ما نكتة التعبير بـ﴿مُقَرَّنِينَ﴾؟","answer":"تصور اللفظة شدة الربط والاقتران؛ ومن وجوهها قرن الكافر بشيطانه أو جمع الأتباع والمتبوعين أو ربط المعذبين بعضهم ببعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص555، تحت عنوان «نكتة التعبير بـ﴿مقرنين﴾»","url":""}]},{"id":"s25-20","number":20,"surah":25,"verses":[14],"references":[{"surah":25,"verses":[14]}],"verseLabel":"الفرقان: 14","question":"ما دلالة ﴿لا تدعوا اليوم ثبورا واحدا وادعوا ثبورا كثيرا﴾؟","answer":"فيه تقنيط لهم من الخلاص، وبيان أن ما نزل بهم من البلاء أعظم من أن يكفيه دعاء واحد بالهلاك. وتكرار الدعاء لا يقطع العذاب ولا يجلب راحة؛ فالمقصود تهويل حالهم والإياس من النجاة، لا أن الهلاك يتحقق لهم إذا أكثروا طلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص559–560، تحت عنوان «بلاغة الكنايات في التركيب»","url":""}]},{"id":"s25-21","number":21,"surah":25,"verses":[15],"references":[{"surah":25,"verses":[15]}],"verseLabel":"الفرقان: 15","question":"ما دلالة التفضيل بـ﴿خَيْرٌ﴾ في مقابلة جنة الخلد بالسعير؟","answer":"التفضيل للتقرير والتبكيت في أمر بيّن، لا لإثبات خير حقيقي في السعير؛ فهو يكشف فساد اختيار المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص566، تحت عنوان «دلالة التفضيل في ﴿خير﴾»","url":""}]},{"id":"s25-102","number":102,"surah":25,"verses":[15],"references":[{"surah":25,"verses":[15]}],"verseLabel":"الفرقان: 15","question":"ما دلالة إضافة الجنة إلى الخلد؟","answer":"تمدح الجنة بدوام نعيمها وتنزهها عن زوال جنان الدنيا، فتجعل البقاء والنعيم التام جزءًا من المفاضلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص568، تحت عنوان «دلالة الإضافة في ﴿جنة الخلد﴾»","url":""}]},{"id":"s25-22","number":22,"surah":25,"verses":[16],"references":[{"surah":25,"verses":[16]}],"verseLabel":"الفرقان: 16","question":"لماذا حُذف مفعول ﴿يَشَاءُونَ﴾ في قوله: ﴿لَهُمْ فِيهَا مَا يَشَاءُونَ﴾؟","answer":"عم الحذف أنواع النعيم التي تتعلق بها مشيئتهم، لأن ذكر بعض المفعولات قد يوهم الاقتصار ويضيق سعة الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص574، تحت عنوان «علة حذف مفعول المشيئة»","url":""}]},{"id":"s25-103","number":103,"surah":25,"verses":[16],"references":[{"surah":25,"verses":[16]}],"verseLabel":"الفرقان: 16","question":"ما الكناية في وصف نعيم الجنة بأنه ﴿وَعْدًا مَسْئُولًا﴾؟","answer":"التركيب كناية عن تحقق الوعد ولزوم إنجازه وانتفاء إخلافه، فيطمئن أهل الجنة إلى تمام ما وعدوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص577، تحت عنوان «بلاغة الكناية في التركيب»","url":""}]},{"id":"s25-23","number":23,"surah":25,"verses":[17],"references":[{"surah":25,"verses":[17]}],"verseLabel":"الفرقان: 17","question":"ما دلالة سؤال المعبودين أمام عابديهم وتقديمه على سؤال العابدين؟","answer":"توجَّه المواجهة أولا إلى من عظموهم واتخذوهم معبودين، فإذا تبرؤوا من إضلال عابديهم انهارت حجتهم وظهر بطلان تعلقهم بهم. وفي ذلك زيادة في خزي العابدين وحسرتهم، إذ يأتي التكذيب ممن كانوا يرجون نفعه ويعظمون قدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص585، تحت عنوان «نكتة تقديم سؤال المعبودين على سؤال العابدين»","url":""}]},{"id":"s25-24","number":24,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"لماذا صُدر جواب المعبودين بالتسبيح؟","answer":"بادروا بتنزيه الله إجمالًا قبل تفصيل التبرؤ، وقدموه على شأن أنفسهم لأنه الأحق بالتقديم في مقام إنكار الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص596، تحت عنوان «نكتة تصدير القول بالتسبيح»","url":""}]},{"id":"s25-104","number":104,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما الكناية في قول المعبودين: ﴿سُبْحَانَكَ﴾؟","answer":"التسبيح كناية عن استبعاد أن يكونوا أندادًا لله أو أن يدعوا الناس إلى اتخاذهم أولياء من دونه، مع التصريح بتنزيهه عن الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص596، تحت عنوان «بلاغة الكناية في جملة التسبيح»","url":""}]},{"id":"s25-25","number":25,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما دلالة عطف الآباء في قوله: ﴿مَتَّعْتَهُمْ وَآبَاءَهُمْ﴾؟","answer":"أبرز العطف أن النعمة امتدت إلى أجيالهم، وأنهم نشؤوا في تمتع موروث لم يقابلوه بالشكر والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص601–602، تحت عنوان «دلالة عطف الآباء عليهم»","url":""}]},{"id":"s25-105","number":105,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما دلالة جعل النسيان غاية للتمتيع في قوله: ﴿حَتَّى نَسُوا الذِّكْرَ﴾؟","answer":"صوّر طول التمتع والاستغراق فيه حتى آل حالهم إلى الإعراض عن الذكر، لا لأن النعمة تعذرهم بل لأنها كانت تستوجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص602، تحت عنوان «دلالة جعل النسيان غاية للتمتيع»","url":""}]},{"id":"s25-106","number":106,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما دلالة التعبير بالنسيان في قوله: ﴿نَسُوا الذِّكْرَ﴾؟","answer":"عبر بالنسيان عن شدة الترك والإهمال حتى صار الذكر كالمغيّب عن قلوبهم وسلوكهم، وهو نسيان تفريط لا عجز غير مؤاخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص603، تحت عنوان «دلالة التعبير بالنسيان»","url":""}]},{"id":"s25-26","number":26,"surah":25,"verses":[19],"references":[{"surah":25,"verses":[19]}],"verseLabel":"الفرقان: 19","question":"ما موقع جملة ﴿فَقَدْ كَذَّبُوكُمْ﴾ مما قبلها؟","answer":"جاءت نتيجة لمحاكمة دعوى العابدين؛ فلما تبرأ المعبودون مما نسب إليهم صار جوابهم حجة فاصلة على كذب عابديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص607، تحت عنوان «موقع جملة ﴿فقد كذبوكم﴾ مما قبله»","url":""}]},{"id":"s25-107","number":107,"surah":25,"verses":[19],"references":[{"surah":25,"verses":[19]}],"verseLabel":"الفرقان: 19","question":"ما دلالة ﴿قَدْ﴾ في قوله: ﴿فَقَدْ كَذَّبُوكُمْ﴾؟","answer":"حققت وقوع التكذيب وثبوته بعد ظهور شهادة المعبودين، فلم تبق دعوى العابدين محتملة في مقام الفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص608، تحت عنوان «دلالة (قد) التحقيقية في السياق»","url":""}]},{"id":"s25-108","number":108,"surah":25,"verses":[19],"references":[{"surah":25,"verses":[19]}],"verseLabel":"الفرقان: 19","question":"ما معنى الباء في قوله: ﴿بِمَا تَقُولُونَ﴾؟","answer":"تحتمل الملابسة، أي كذبوكم في شأن قولكم، وتحتمل السببية، أي كان قولكم سببًا في إظهار تكذيبهم لكم؛ وكلاهما يربط الحكم بالدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص608، تحت عنوان «معنى الباء في ﴿بما﴾»","url":""}]},{"id":"s25-27","number":27,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"ما دلالة أسلوبي النفي والاستثناء في تقرير بشرية الرسل السابقين؟","answer":"قصر حالهم على ما هو معهود من البشر في الأكل والمشي، ردًا على توهم أن الرسالة تستلزم الخروج عن الطبيعة البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص615–616، تحت عنوان «دلالة أسلوبي النفي والاستثناء في الآية»","url":""}]},{"id":"s25-109","number":109,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"ما الكناية في أكل الرسل الطعام ومشيهم في الأسواق؟","answer":"كناية عن حاجتهم البشرية إلى القوت وقضاء المصالح وطلب المعاش، وهي أحوال لا تنافي اصطفاءهم بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص616، تحت عنوان «بلاغة الكناية في أكل الطعام والمشي في الأسواق»","url":""}]},{"id":"s25-28","number":28,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"إلى من يعود ضمير الخطاب في قوله: ﴿وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً﴾؟","answer":"يعم الخطاب الناس، ويدخل فيه ابتلاء الناس بالرسل وابتلاء الرسل بأقوامهم؛ فاختلاف الأحوال والمواقف امتحان يكشف الصبر والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص617–618، تحت عنوان «فائدة ضمير الخطاب وعوده في ﴿بعضكم لبعض فتنة﴾»","url":""}]},{"id":"s25-110","number":110,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"لماذا اختير لفظ ﴿فِتْنَةً﴾ في قوله: ﴿بَعْضَكُمْ لِبَعْضٍ فِتْنَةً﴾؟","answer":"يصور اللفظ شدة الاختبار الذي يمحص المواقف، وفيه مجاز بجعل الشخص أو اختلاف حاله نفس الفتنة لما يكون سببًا للامتحان.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص618، تحت عنوان «سر إيثار لفظ ﴿فتنة﴾، ودلالة المجاز فيه»","url":""}]},{"id":"s25-111","number":111,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"ما بلاغة الاستفهام في قوله: ﴿أَتَصْبِرُونَ﴾؟","answer":"خرج الاستفهام للحث والاختبار، فيحتمل معنى الأمر بالصبر والتحذير من ضعف الاحتمال، لا مجرد طلب خبر عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص618–619، تحت عنوان «بلاغة الاستفهام في الآية ﴿أتصبرون﴾»","url":""}]},{"id":"s25-29","number":29,"surah":25,"verses":[21],"references":[{"surah":25,"verses":[21]}],"verseLabel":"الفرقان: 21","question":"ما غرض تقديم ﴿عَلَيْنَا﴾ في قولهم: ﴿لَوْلَا أُنْزِلَ عَلَيْنَا الْمَلَائِكَةُ﴾؟","answer":"أبرز التقديم تعاظمهم ورؤيتهم أنفسهم أهلًا لتلقي الملائكة مباشرة، وفيه تحكم متكبر في دلائل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص629، تحت عنوان «الغرض من تقديم شبه الجملة ﴿علينا﴾»","url":""}]},{"id":"s25-112","number":112,"surah":25,"verses":[21],"references":[{"surah":25,"verses":[21]}],"verseLabel":"الفرقان: 21","question":"ما دلالة ﴿أَوْ﴾ والتعبير بالرؤية في قولهم: ﴿أَوْ نَرَى رَبَّنَا﴾؟","answer":"نقلت أو تعنتهم إلى اقتراح أشد، وصرحوا بالرؤية الحسية شرطًا للتصديق، فكشفوا أن مقصدهم المكابرة لا طلب الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص629–630، تحت عنوان «معنى ﴿أو﴾، ودلالة التعبير بالرؤية في ﴿أو نرى ربنا﴾»","url":""}]},{"id":"s25-113","number":113,"surah":25,"verses":[21],"references":[{"surah":25,"verses":[21]}],"verseLabel":"الفرقان: 21","question":"ما دلالة التعبير بـ﴿عُتُوًّا﴾ مادة وصيغة؟","answer":"العتو مجاوزة الحد مع الاستكبار، والمصدر يصور تمكنه وعظمه في نفوسهم وأقوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص632، تحت عنوان «دلالة التعبير بالعتو مادة وصيغة»","url":""}]},{"id":"s25-30","number":30,"surah":25,"verses":[22],"references":[{"surah":25,"verses":[22]}],"verseLabel":"الفرقان: 22","question":"ما نكتة فصل قوله: ﴿لَا بُشْرَى يَوْمَئِذٍ لِلْمُجْرِمِينَ﴾؟","answer":"استؤنفت الجملة جوابًا عن سؤال مقدر عن حالهم عند رؤية الملائكة، فبينت أن الرؤية التي طلبوها تأتيهم في مقام الخوف والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص639، تحت عنوان «نكتة فصل قوله: ﴿لا بشرى يومئذ للمجرمين﴾»","url":""}]},{"id":"s25-114","number":114,"surah":25,"verses":[22],"references":[{"surah":25,"verses":[22]}],"verseLabel":"الفرقان: 22","question":"ما غرض النفي بـ﴿لَا﴾ النافية للجنس في قوله: ﴿لَا بُشْرَى﴾؟","answer":"استغرق النفي جنس البشرى كله، فقطع رجاء المجرمين في أي خبر سار أو نجاة يومئذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص640، تحت عنوان «غرض النفي بـ ﴿لا﴾ النافية للجنس في الآية الكريمة»","url":""}]},{"id":"s25-31","number":31,"surah":25,"verses":[23],"references":[{"surah":25,"verses":[23]}],"verseLabel":"الفرقان: 23","question":"ما غرض التشبيه البليغ في قوله: ﴿فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا﴾؟","answer":"جسد ذهاب نفع أعمالهم، فصارت كالدقائق التي تظهر في شعاع الشمس ولا يمكن جمعها أو الانتفاع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص652، تحت عنوان «الغرض من التعبير بالتشبيه البليغ في قوله: ﴿فجعلناه هباء منثورا﴾»","url":""}]},{"id":"s25-115","number":115,"surah":25,"verses":[23],"references":[{"surah":25,"verses":[23]}],"verseLabel":"الفرقان: 23","question":"لماذا وُصف الهباء بأنه ﴿مَنْثُورًا﴾؟","answer":"زاد الوصف صورة التفرق والضياع، فنفى أن يبقى للعمل أثر مجتمع ينفع صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص652، تحت عنوان «سر وصف الهباء بأنه منثور»","url":""}]},{"id":"s25-32","number":32,"surah":25,"verses":[24],"references":[{"surah":25,"verses":[24]}],"verseLabel":"الفرقان: 24","question":"ما غرض التفضيل بـ﴿خَيْرٌ﴾ في وصف أصحاب الجنة؟","answer":"جاء للتقرير والتوبيخ للمكذبين والبشارة للمؤمنين، ولا يقتضي إثبات خير في مستقر الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص658، تحت عنوان «الغرض من التعبير بالمسند (أفعل) تفضيل: ﴿خير﴾»","url":""}]},{"id":"s25-116","number":116,"surah":25,"verses":[24],"references":[{"surah":25,"verses":[24]}],"verseLabel":"الفرقان: 24","question":"ما دلالة التعبير عن موضع المؤمنين بـ﴿مُسْتَقَرًّا﴾؟","answer":"يصور ثبات مقامهم وطمأنينته وأمنهم من الزوال والاضطراب، فيقابل مصير أهل العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص659، تحت عنوان «دلالة التعبير عن موضع المؤمنين بالاستقرار»","url":""}]},{"id":"s25-117","number":117,"surah":25,"verses":[24],"references":[{"surah":25,"verses":[24]}],"verseLabel":"الفرقان: 24","question":"ما دلالة التعبير بـ﴿مَقِيلًا﴾ مادة وصيغة؟","answer":"يصور حسن الراحة وطيبها، سواء حمل على الاستراحة بعد الحساب أو شبّه نعيم الجنة براحة القائلة؛ ولا يلزم منه نوم أهل الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص660، تحت عنوان «دلالة التعبير بـ﴿مقيلا﴾ مادة وصيغة»","url":""}]},{"id":"s25-33","number":33,"surah":25,"verses":[25],"references":[{"surah":25,"verses":[25]}],"verseLabel":"الفرقان: 25","question":"ما دلالة التعبير بـ﴿تَشَقَّقُ﴾ مادة وصيغة؟","answer":"تصور المادة انصداع السماء، ويفيد التضعيف شدة التشقق وتكثره، فيجسد تغير نظامها وهول يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص666، تحت عنوان «دلالة التعبير بـ﴿تشقق﴾ مادة وصيغة»","url":""}]},{"id":"s25-118","number":118,"surah":25,"verses":[25],"references":[{"surah":25,"verses":[25]}],"verseLabel":"الفرقان: 25","question":"ما معنى الباء في قوله: ﴿تَشَقَّقُ السَّمَاءُ بِالْغَمَامِ﴾؟","answer":"تحتمل أن تتشقق السماء عن الغمام، أو بسببه، أو مع ظهوره؛ فتجمع الأوجه بين انصداع السماء ومشهد الغمام ونزول الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص667–668، تحت عنوان «معنى الباء ودلالتها في قوله: ﴿بالغمام﴾»","url":""}]},{"id":"s25-34","number":34,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما الكناية في قوله: ﴿يَعَضُّ الظَّالِمُ عَلَى يَدَيْهِ﴾؟","answer":"العض على اليدين كناية عن شدة الندم والحسرة، تنقل الانفعال النفسي إلى حركة محسوسة مؤلمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص683–684، تحت عنوان «بلاغة التعبير بالكناية»","url":""}]},{"id":"s25-119","number":119,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما بلاغة اختلاف العض على الأنامل والعض على اليدين في القرآن؟","answer":"ناسب عض الأنامل غيظ المنافقين مع بقاء أملهم في الإضرار، أما عض اليدين فمبالغة في حسرة الظالم بعد فوات التدارك؛ فاختلاف الصورة لاختلاف المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص684، تحت عنوان «بلاغة المتشابه اللفظي»","url":""}]},{"id":"s25-35","number":35,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما بلاغة التعبير عن اتباع الرسول بالمعية في قوله: ﴿مَعَ الرَّسُولِ سَبِيلًا﴾؟","answer":"صوّر الاتباع بسلوك طريق مع الرسول بوصفه دليلًا إلى النجاة، فالمعية معية هدى واقتداء لا مجرد قرب مكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص686–687، تحت عنوان «بلاغة التعبير عن الاتباع بالمعية مع الرسول»","url":""}]},{"id":"s25-120","number":120,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما غرض تنكير ﴿سَبِيلًا﴾ في قوله: ﴿اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا﴾؟","answer":"يحتمل تعظيم سبيل الاتباع المنجي، أو تعميم طرق الخير، أو إفراد سبيل الهدى في مقابلة مسالك الضلال المتعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص687–688، تحت عنوان «الغرض من تنكير ﴿سبيلا﴾»","url":""}]},{"id":"s25-36","number":36,"surah":25,"verses":[28,29],"references":[{"surah":25,"verses":[28,29]}],"verseLabel":"الفرقان: 28-29","question":"ما نكتة التكنية عن الخليل بـ﴿فُلَانًا﴾؟","answer":"لم تعين اسمًا لتعم العبرة كل خليل يصد صاحبه عن الحق، فلا تنحصر الحسرة في واقعة أو شخص مخصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص690، تحت عنوان «نكتة التكنية عن المقصود بـ﴿فلانا﴾»","url":""}]},{"id":"s25-121","number":121,"surah":25,"verses":[28,29],"references":[{"surah":25,"verses":[28,29]}],"verseLabel":"الفرقان: 28-29","question":"ما نكتة فصل قوله: ﴿لَقَدْ أَضَلَّنِي عَنِ الذِّكْرِ﴾؟","answer":"جاءت الجملة تعليلًا لحسرته على اتخاذ الخليل، فكشفت أن من قربه للنصرة صار سببًا في أعظم خسارته: الانصراف عن الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص691، تحت عنوان «نكتة فصل قوله: ﴿لقد أضلني﴾»","url":""}]},{"id":"s25-37","number":37,"surah":25,"verses":[29],"references":[{"surah":25,"verses":[29]}],"verseLabel":"الفرقان: 29","question":"ما دلالة ختم المشهد بقوله: ﴿وَكَانَ الشَّيْطَانُ لِلْإِنْسَانِ خَذُولًا﴾؟","answer":"قرر التذييل أن الخذلان شأن متكرر للشيطان: يزين الضلال ثم يترك الإنسان عند الحاجة، وصيغة خذول تبالغ في ذلك؛ ويحتمل أن تكون من كلام الظالم أو حكمًا عامًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص697، تحت عنوان «دلالة ختم الآية بقوله: ﴿وكان الشيطان للإنسان خذولا﴾»","url":""}]},{"id":"s25-38","number":38,"surah":25,"verses":[30],"references":[{"surah":25,"verses":[30]}],"verseLabel":"الفرقان: 30","question":"ما دلالة التعبير بالاتخاذ في قوله: ﴿اتَّخَذُوا هَذَا الْقُرْآنَ مَهْجُورًا﴾؟","answer":"يفيد أن الهجر صار فعلًا مقصودًا وحالة راسخة في معاملتهم للقرآن، لا إعراضًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص702–703، تحت عنوان «دلالة التعبير بالاتخاذ»","url":""}]},{"id":"s25-122","number":122,"surah":25,"verses":[30],"references":[{"surah":25,"verses":[30]}],"verseLabel":"الفرقان: 30","question":"ما غرض اسم الإشارة للقريب في قوله: ﴿هَذَا الْقُرْآنَ﴾؟","answer":"يستحضر القرآن قريبًا ظاهر الحجة ويعظمه، فتشتد المفارقة بين وضوحه وعلو شأنه وبين اتخاذهم إياه مهجورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص703–704، تحت عنوان «الغرض من التعبير باسم الإشارة للقريب»","url":""}]},{"id":"s25-39","number":39,"surah":25,"verses":[31],"references":[{"surah":25,"verses":[31]}],"verseLabel":"الفرقان: 31","question":"ما التشبيه في تقرير أن لكل نبي عدوًا من المجرمين، وما غرضه؟","answer":"شُبه حال الرسول مع أعدائه بأحوال الأنبياء قبله، تسليةً له ودعوة إلى الثبات؛ فالعداوة سنة ماضية لا علامة على ضعف الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص709–710، تحت عنوان «بلاغة التعبير بالتشبيه، وغرضه»","url":""}]},{"id":"s25-123","number":123,"surah":25,"verses":[31],"references":[{"surah":25,"verses":[31]}],"verseLabel":"الفرقان: 31","question":"ما دلالة الواو في قوله: ﴿وَكَفَى بِرَبِّكَ هَادِيًا وَنَصِيرًا﴾؟","answer":"عطفت الطمأنينة بكفاية هداية الله ونصره على ذكر عداوة المجرمين، فدفعت ما قد يورثه الكلام السابق من وحشة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص714، تحت عنوان «معنى الواو ودلالتها في ﴿وكفى بربك﴾»","url":""}]},{"id":"s25-40","number":40,"surah":25,"verses":[32],"references":[{"surah":25,"verses":[32]}],"verseLabel":"الفرقان: 32","question":"ما الحكمة من تعليل نزول القرآن مفرقًا بقوله: ﴿لِنُثَبِّتَ بِهِ فُؤَادَكَ﴾؟","answer":"التنزيل المتتابع يجدد تسلية الرسول ويقوي فؤاده أمام الأذى، وييسر الحفظ ويواكب الحوادث وتدرج الأحكام؛ فالتفريق مظهر حكمة لا نقص إحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص726–727، تحت عنوان «دلالة جملة التثبيت والحكمة منها»","url":""}]},{"id":"s25-41","number":41,"surah":25,"verses":[32],"references":[{"surah":25,"verses":[32]}],"verseLabel":"الفرقان: 32","question":"ما دلالة ﴿ورتلناه ترتيلا﴾ مع نزول القرآن مفرقا؟","answer":"الترتيل يفيد حسن التأليف ووضوح الدلالة وإحكام الترتيب، ويذكر الشرح فيه أيضا معنى تفريق التنزيل. فمع امتداد زمن نزوله بقي متناسقا متماسكا، حتى تبدو السورة كالكلمة الواحدة؛ وهذا من دلائل أنه ليس تأليفا بشريا متفرقا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص728، تحت عنوان «دلالة التعبير بـ﴿ورتلناه﴾ مادة وصيغة»","url":""}]},{"id":"s25-42","number":42,"surah":25,"verses":[33],"references":[{"surah":25,"verses":[33]}],"verseLabel":"الفرقان: 33","question":"ما دلالة الاستثناء في قوله: ﴿وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَاكَ بِالْحَقِّ﴾؟","answer":"يفيد أن كل شبهة أو اعتراض يأتون به يقابله جواب الحق الكاشف لبطلانه، فلا يتركون بلا بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص735، تحت عنوان «دلالة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s25-124","number":124,"surah":25,"verses":[33],"references":[{"surah":25,"verses":[33]}],"verseLabel":"الفرقان: 33","question":"ما دلالة التعبير بـ﴿وَأَحْسَنَ تَفْسِيرًا﴾ مادة وصيغة؟","answer":"يبين تفوق البيان القرآني في إيضاح المراد وإزالة اللبس، ولا يقتضي أفعل التفضيل أن تفسيرهم صحيح أو حسن في ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص739، تحت عنوان «دلالة التعبير بـ﴿وأحسن﴾ مادة وصيغة»","url":""}]},{"id":"s25-43","number":43,"surah":25,"verses":[34],"references":[{"surah":25,"verses":[34]}],"verseLabel":"الفرقان: 34","question":"ما دلالة الوعيد بحشرهم على وجوههم؟","answer":"يجمع الوعيد بين إذلالهم وتشويه وجوههم وتعذيبهم، جزاء لإعراضهم عن الحق وقلبهم الهدى ضلالا. فصورة الحشر على الوجوه تناسب انقلاب حالهم عما ظنوه لأنفسهم من العزة وعلو المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص746، تحت عنوان «بلاغة الوعيد لهم من خلال الجمع بين التشويه والتعذيب»","url":""}]},{"id":"s25-44","number":44,"surah":25,"verses":[35],"references":[{"surah":25,"verses":[35]}],"verseLabel":"الفرقان: 35","question":"ما دلالة حرف المعية في قوله: ﴿وَجَعَلْنَا مَعَهُ أَخَاهُ هَارُونَ﴾؟","answer":"تبرز المعية ملازمة هارون لموسى ومساندته له في أداء الرسالة ومواجهة أعبائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص756، تحت عنوان «دلالة التعبير بحرف المعية (مع)»","url":""}]},{"id":"s25-125","number":125,"surah":25,"verses":[35],"references":[{"surah":25,"verses":[35]}],"verseLabel":"الفرقان: 35","question":"ما دلالة التعبير بـ﴿وَزِيرًا﴾ مادة وصيغة؟","answer":"تفيد المعاونة وشد الأزر وحمل ثقل المهمة، فالأخوة هنا أخوة مؤازرة في الدعوة لا مجرد نسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص757، تحت عنوان «دلالة التعبير بـ﴿وزيرا﴾ مادة وصيغة»","url":""}]},{"id":"s25-45","number":45,"surah":25,"verses":[36],"references":[{"surah":25,"verses":[36]}],"verseLabel":"الفرقان: 36","question":"ما الإيجاز بالحذف في الانتقال إلى قوله: ﴿فَدَمَّرْنَاهُمْ تَدْمِيرًا﴾؟","answer":"حذف ما دل عليه السياق: فذهب موسى وهارون ودعوا القوم فكذبوهما، ثم وقع التدمير؛ واقتصر على إقامة الحجة ومآل المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص761–762، تحت عنوان «بلاغة الإيجاز بالحذف في فعل التدمير»","url":""}]},{"id":"s25-46","number":46,"surah":25,"verses":[37],"references":[{"surah":25,"verses":[37]}],"verseLabel":"الفرقان: 37","question":"ما سر التعبير عن قوم نوح بـ﴿كذبوا الرسل﴾ مع أن رسولهم نوح؟","answer":"تكذيب نوح يستلزم تكذيب الرسل جميعا لاتفاق دعوتهم إلى عبادة الله، ولأن إنكارهم بعثة البشر يطعن في أصل الرسالة. ومن وجوه الجمع أيضا تشنيع فعلهم وتأكيد أن تكذيب الرسول الواحد ليس أمرا هينا معزولا عن سائر الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص769، تحت عنوان «نكتة التعبير بالرسل جمعا»","url":""}]},{"id":"s25-47","number":47,"surah":25,"verses":[38],"references":[{"surah":25,"verses":[38]}],"verseLabel":"الفرقان: 38","question":"ما غرض تقديم أسماء عاد وثمود وأصحاب الرس والقرون؟","answer":"يشوق تقديم الأسماء إلى خبرهم، ثم يجمعهم الحكم اللاحق في تلقي الأمثال والإنذار ثم الهلاك بسبب التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص773–774، تحت عنوان «غرض تقديم الأسماء الأربعة»","url":""}]},{"id":"s25-126","number":126,"surah":25,"verses":[38],"references":[{"surah":25,"verses":[38]}],"verseLabel":"الفرقان: 38","question":"ما سر عطف ﴿وَقُرُونًا﴾ على الأقوام المذكورة؟","answer":"وسع العطف دائرة العبرة لتشمل أممًا كثيرة اشتركت في التكذيب والمآل، فلا يظن أن السنة مختصة بالأقوام المسماة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص774، تحت عنوان «سر عطف ﴿وقرونا﴾ على ما تقدمها من الأقوام»","url":""}]}]);
